window.ESAME_BIO_DATA = [{"id":1,"topic":"Citologia","type":"label","q":"Etichetta correttamente l'immagine.","img":"cellula_animale.jpg","zw":25,"zones":[{"x":24.0,"y":10.2,"ans":"RE rugoso"},{"x":22.8,"y":21.6,"ans":"RE liscio"},{"x":55.8,"y":8.7,"ans":"nucleo"},{"x":22.8,"y":83.5,"ans":"mitocondrio"},{"x":73.1,"y":79.4,"ans":"vescicola"},{"x":60.6,"y":91.8,"ans":"apparato di Golgi"}],"bank":[],"why":"Il RE rugoso è il sistema di sacche appiattite in continuità con l'involucro nucleare, costellato di ribosomi; il RE liscio è la rete di tubuli privi di ribosomi. Le pile di cisterne arancioni sono i dittiosomi dell'apparato di Golgi.","real":true},{"id":2,"topic":"Citologia","type":"cloze","q":"Osserva l'immagine e completa.","img":"cellula_animale.jpg","text":"È una cellula di tipo {0}. L'organismo è {1}.","answers":["eucariota","eterotrofo"],"groups":[0,1],"bank":[["procariota"],["fotoautotrofo"]],"why":"Nucleo delimitato da involucro ed endomembrane (RE, Golgi, mitocondri) indicano una cellula eucariota. Centrioli, flagello e assenza di parete, cloroplasti e grande vacuolo indicano una cellula animale, quindi un organismo eterotrofo.","real":true},{"id":3,"topic":"Citologia","type":"match","q":"Osserva l'immagine e scegli la risposta per ogni riga.","img":"membrana_numeri.jpg","rows":[{"label":"Il numero 1 indica:","ans":"dei carboidrati"},{"label":"Il numero 2 indica:","ans":"i fosfolipidi di membrana"},{"label":"In immagine è rappresentato:","ans":"la membrana cellulare"},{"label":"Il numero 3 indica:","ans":"delle proteine"}],"options":["dei carboidrati","degli amminoacidi","i fosfolipidi di membrana","delle proteine","la membrana cellulare","la parete cellulare","degli acidi nucleici"],"why":"È il modello a mosaico fluido: doppio strato fosfolipidico (2) con proteine intrinseche (3). Le catene ramificate esposte verso l'esterno (1) sono oligosaccaridi (glicocalice) legati a glicoproteine e glicolipidi: sono carboidrati, non amminoacidi.","real":true},{"id":4,"topic":"Citologia","type":"cloze","q":"Completa trascinando le parole nei riquadri.","text":"La membrana plasmatica è principalmente formata da {0}, molecole organiche che presentano una testa {1} e una coda {2}.","answers":["fosfolipidi","idrofila","idrofoba"],"bank":["fluida","proteine"],"why":"I fosfolipidi sono anfipatici: testa polare idrofila (gruppo fosfato) rivolta verso l'acqua e code di acidi grassi idrofobe rivolte verso l'interno del doppio strato.","real":true},{"id":5,"topic":"Citologia","type":"cloze","q":"Completa il testo sul vacuolo.","img":"cellula_vegetale_vacuolo.jpg","text":"I vacuoli sono generalmente {0} compartimenti ben visibili nelle cellule mature. La {1} del vacuolo è nota come {2} ed è una parte essenziale per la funzione di questo organello. Nuovi vacuoli si formano dalla fusione di {3} rilasciate dal dittiosoma. Inizialmente formano un nuovo compartimento noto come {4}. Una cellula {5} può avere centinaia di provacuoli. Durante la differenziazione cellulare, i provacuoli si fondono tra loro prima in piccoli vacuoli e alla fine in un grande vacuolo centrale. I vacuoli sono essenziali per l'{6} delle cellule vegetali e svolgono diverse funzioni a seconda del tipo di cellula. Tra le principali: il {7}, ovvero il livello di pressione idrostatica contro la parete cellulare della cellula vegetale, e l'accumulo di sostanze come {8}, {9} e {10}.","answers":["grandi","membrana","tonoplasto","vescicole","provacuolo","meristematica","accrescimento","turgore","sali","zuccheri","pigmenti"],"free":[[8,9,10]],"bank":["piccoli","parete","plasmalemma","ribosomi","differenziata","amido"],"why":"Nelle cellule mature il vacuolo è grande e centrale (fino al 90% del volume), delimitato dal tonoplasto. Nasce da vescicole del Golgi (dittiosomi) che formano provacuoli, numerosi nelle cellule meristematiche. Permette la distensione (accrescimento) cellulare, mantiene il turgore e accumula sali, zuccheri, acidi organici e pigmenti (antociani). Nota: la banca di parole è ricostruita, nello screenshot originale mancava.","real":true},{"id":6,"topic":"Citologia","type":"cloze","q":"Completa trascinando le parole nei riquadri.","text":"La cellula {0} è delimitata da una parete cellulare rigida, costituita da {1}, la cui composizione è {2} quella della parete dei procarioti.","answers":["vegetale","cellulosa","diversa da"],"groups":[0,1,2],"bank":[["animale"],["fosfolipidi"],["identica a"]],"why":"La parete della cellula vegetale è fatta di microfibrille di cellulosa in una matrice di emicellulose e pectine; quella dei batteri contiene peptidoglicano (mureina). La cellula animale non ha parete.","real":true},{"id":7,"topic":"Citologia","type":"cloze","q":"Completa trascinando le parole nei riquadri.","text":"{0} sono organelli che si trovano in tutte le cellule viventi. I {1} sono organelli propri della cellula vegetale.","answers":["Membrana cellulare e ribosomi","plastidi"],"groups":[0,1],"bank":[["Parete cellulare e mitocondri","Parete cellulare e ribosomi","Membrana cellulare e parete cellulare"],["flagelli","ribosomi","mitocondri","microtubuli"]],"why":"Membrana plasmatica e ribosomi sono presenti in ogni cellula, anche procariote. La parete manca nelle cellule animali, i mitocondri nei procarioti. I plastidi (cloroplasti, amiloplasti, cromoplasti…) sono esclusivi delle cellule vegetali.","real":true},{"id":8,"topic":"Citologia","type":"multi","q":"Quale di questi NON è uno dei principi della teoria cellulare?","opts":["Le cellule sono le unità fondamentali della vita","Le cellule sono l'unità di base della vita","Nuove cellule provengono da cellule esistenti","Tutte le cellule hanno un nucleo"],"correct":[3],"why":"La teoria cellulare afferma che tutti i viventi sono fatti di cellule, che la cellula è l'unità fondamentale della vita e che ogni cellula deriva da una cellula preesistente. Non dice che tutte le cellule hanno un nucleo: i procarioti ne sono privi.","real":true},{"id":9,"topic":"Citologia","type":"multi","q":"In quale organulo cellulare sono assemblate le proteine?","opts":["ribosomi","nucleo","membrana cellulare","apparato del Golgi"],"correct":[0],"why":"La sintesi proteica (traduzione) avviene sui ribosomi, liberi o legati al RE rugoso. Nel nucleo l'RNA viene trascritto; il Golgi modifica e smista proteine già sintetizzate.","real":true},{"id":10,"topic":"Citologia","type":"label","q":"Etichetta correttamente l'immagine.","img":"cloroplasto.jpg","zw":20,"zones":[{"x":62.0,"y":3.9,"ans":"membrana esterna"},{"x":34.8,"y":10.7,"ans":"membrana interna"},{"x":23.2,"y":19.1,"ans":"granum"},{"x":10.0,"y":34.7,"ans":"DNA"},{"x":10.0,"y":56.2,"ans":"amido","px":28.9,"py":72.5},{"x":87.1,"y":30.2,"ans":"ribosoma"},{"x":64.2,"y":90.0,"ans":"lumen"},{"x":85.2,"y":89.3,"ans":"tilacoide"},{"x":41.4,"y":95.5,"ans":"stroma","px":43.9,"py":81.3}],"bank":["parete","RNA","istoni"],"why":"Il cloroplasto ha un involucro a doppia membrana (esterna e interna). Nello stroma ci sono DNA circolare nudo (senza istoni, come nei batteri), ribosomi 70S e granuli di amido. I tilacoidi impilati formano i grana; lo spazio interno del tilacoide è il lumen. Non ha parete.","real":true},{"id":11,"topic":"Citologia","type":"cloze","q":"Completa trascinando le parole nei riquadri.","text":"Nelle cellule animali, vegetali e fungine l'RNA messaggero viene trasferito da {0} a {1} attraverso {2}.","answers":["nucleo","citosol","i pori nucleari"],"groups":[0,1,2],"bank":[["ribosomi","membrana plasmatica"],["ribosomi","nucleo"],["plasmodesmi","punteggiature"]],"why":"L'mRNA viene trascritto nel nucleo ed esce nel citosol attraverso i pori dell'involucro nucleare, dove verrà tradotto dai ribosomi. Plasmodesmi e punteggiature collegano invece cellule adiacenti.","real":true},{"id":12,"topic":"Citologia","type":"multi","q":"Seleziona gli elementi che fanno parte del citoscheletro:","opts":["microfilamenti di actina","microtubuli","microfibrille di cellulosa","plasmodesmi","tilacoidi"],"correct":[0,1],"why":"Il citoscheletro vegetale è formato da microtubuli (tubulina) e microfilamenti (actina). Le microfibrille di cellulosa sono nella parete, i plasmodesmi attraversano la parete, i tilacoidi sono nei cloroplasti.","real":true},{"id":13,"topic":"Citologia","type":"label","q":"Etichetta correttamente gli elementi.","img":"membrana_etichette.jpg","zw":14,"zones":[{"x":67.3,"y":9.2,"ans":"carboidrato"},{"x":29.8,"y":40.0,"ans":"fosfolipide"},{"x":54.2,"y":34.0,"ans":"proteina"}],"bank":[],"why":"Le catene ramificate sulla faccia esterna sono oligosaccaridi (carboidrati); il doppio strato è formato da fosfolipidi; le strutture che lo attraversano sono proteine transmembrana.","real":true},{"id":14,"topic":"Fiore e riproduzione","type":"label","q":"Etichetta correttamente l'immagine.","img":"fiore.jpg","zw":14,"zones":[{"x":36.4,"y":19.3,"ans":"stimma"},{"x":12.8,"y":39.6,"ans":"pistillo"},{"x":68.6,"y":16.5,"ans":"antera"},{"x":89.4,"y":23.4,"ans":"stame"},{"x":78.2,"y":31.3,"ans":"filamento"},{"x":50.5,"y":42.7,"ans":"stilo"},{"x":65.3,"y":49.5,"ans":"petalo"},{"x":40.9,"y":60.4,"ans":"ovario"},{"x":59.4,"y":60.4,"ans":"ovuli"},{"x":42.0,"y":70.9,"ans":"ricettacolo"},{"x":62.3,"y":79.2,"ans":"sepalo"},{"x":54.7,"y":90.4,"ans":"peduncolo"}],"bank":[],"why":"Il pistillo (parentesi a sinistra) comprende stimma, stilo e ovario con gli ovuli. Lo stame (ingrandito, parentesi a destra) è formato da filamento e antera. Sotto: petali, sepali, ricettacolo e peduncolo.","real":true},{"id":15,"topic":"Organografia","type":"label","q":"Indicare le parti.","img":"foglia_3d.jpg","zw":22,"zones":[{"x":69.4,"y":4.2,"ans":"epidermide superiore"},{"x":86.4,"y":12.2,"ans":"cuticola"},{"x":15.7,"y":42.3,"ans":"parenchima clorofilliano"},{"x":79.4,"y":53.8,"ans":"nervatura"},{"x":79.8,"y":71.9,"ans":"stoma"},{"x":72.0,"y":83.5,"ans":"epidermide inferiore"}],"bank":["periciclo","collenchima","sughero"],"why":"Nella foglia dorsiventrale: cuticola sopra l'epidermide superiore, mesofillo (parenchima clorofilliano a palizzata e lacunoso) con le nervature, epidermide inferiore con gli stomi. Periciclo (radice), collenchima (organi giovani in accrescimento) e sughero (periderma) non fanno parte della lamina.","real":true},{"id":16,"topic":"Organografia","type":"label","q":"Etichetta correttamente l'immagine.","img":"foglia_sezione.jpg","zw":50,"zones":[{"x":53.8,"y":6.4,"ans":"epidermide"},{"x":31.0,"y":27.6,"ans":"parenchima a palizzata"},{"x":69.0,"y":50.0,"ans":"fascio cribrovascolare"},{"x":41.6,"y":70.3,"ans":"parenchima lacunoso"}],"bank":[],"why":"Dall'alto: epidermide superiore, parenchima a palizzata (cellule allungate e fitte, ricche di cloroplasti), fascio cribrovascolare della nervatura, parenchima lacunoso (cellule irregolari con ampi spazi intercellulari).","real":true},{"id":17,"topic":"Organografia","type":"label","q":"Etichettare correttamente l'immagine (radice in sezione trasversale).","img":"radice_sezione.jpg","zw":30,"zones":[{"x":49.5,"y":10.9,"ans":"parenchima amilifero"},{"x":16.1,"y":41.2,"ans":"endoderma"},{"x":41.2,"y":60.7,"ans":"xilema"}],"bank":["periciclo","floema","cambio"],"why":"La corteccia è un parenchima amilifero (cellule piene di granuli d'amido). L'endoderma è l'anello di cellule che circonda il cilindro centrale; all'interno si trovano il periciclo, lo xilema (grandi vasi a parete rossa, disposti a raggi) e il floema tra le arche xilematiche. Nota: nell'esame i riquadri erano 6; qui sono tenuti solo i 3 identificabili con certezza, gli altri 3 termini restano come distrattori.","real":true},{"id":18,"topic":"Organografia","type":"cloze","q":"Completa trascinando le parole nei riquadri.","text":"L'{0} caratterizza il {1} delle Angiosperme {2}. In questa struttura il tessuto più esterno è {3}.","answers":["atassostele","fusto","monocotiledoni","epidermide"],"bank":["sughero","dicotiledoni","rizoma","corteccia","actinostele"],"why":"L'atassostele, con fasci collaterali chiusi sparsi nel parenchima fondamentale, è tipica del fusto delle Monocotiledoni. Non avendo accrescimento secondario, il tessuto più esterno resta l'epidermide (non il sughero). L'actinostele è la stele della radice.","real":true},{"id":19,"topic":"Organografia","type":"match","q":"Osserva la sezione di foglia e scegli la risposta per ogni riga.","img":"foglia_cripte.jpg","rows":[{"label":"Il numero 2 indica:","ans":"una cripta stomatica"},{"label":"Il numero 1 indica:","ans":"il parenchima a palizzata"},{"label":"La freccia arancione indica:","ans":"gli stomi"},{"label":"Il numero 3 indica:","ans":"un fascio cribrovascolare"}],"options":["una cripta stomatica","il parenchima a palizzata","gli stomi","un fascio cribrovascolare","un canale resinifero","il parenchima lacunoso","il sughero"],"why":"È una foglia xeromorfa (tipo oleandro): gli stomi sono infossati in cripte stomatiche (2) protette da tricomi, sotto il parenchima a palizzata (1); il cerchio (3) racchiude un piccolo fascio cribrovascolare. La freccia indica gli stomi sul fondo della cripta.","real":true},{"id":20,"topic":"Organografia","type":"mc","q":"Nella radice l'assorbimento dell'acqua è:","opts":["limitato all'esoderma","esteso all'intero apparato radicale","limitato alla porzione più prossima all'apice caulinare","limitato alla porzione dove sono presenti i peli radicali, diventando progressivamente meno efficiente nelle porzioni più vecchie"],"correct":3,"why":"L'assorbimento avviene soprattutto nella zona pilifera, dove i peli radicali aumentano enormemente la superficie. Nelle parti più vecchie la radice si suberifica e assorbe sempre meno. L'apice caulinare riguarda il fusto.","real":true},{"id":21,"topic":"Organografia","type":"mc","q":"I bulbi derivano dalla metamorfosi di:","opts":["un fusto che diventa raccorciato, e foglie che diventano organi di protezione e/o riserva","foglie che si sviluppano direttamente da radici","radici in cui predomina la funzione di riserva"],"correct":0,"why":"Il bulbo (es. cipolla) è un fusto molto raccorciato (girello) che porta foglie modificate: le catafille carnose di riserva e quelle esterne secche di protezione. Le radici di riserva sono radici tuberose, non bulbi.","real":true},{"id":22,"topic":"Istologia","type":"multi","q":"Quali delle seguenti sono fibre tessili di origine vegetale?","opts":["il lino, che è formato da fasci di trasporto privi di tessuto meccanico di sostegno","la seta, che è formata da un essudato proteico che al contatto dell'aria diventa solido","la canapa, che è formata da brattee modificate dell'infiorescenza","il cotone, che è formato da tricomi"],"correct":[3],"why":"Attenzione alle descrizioni: il cotone è formato dai lunghi tricomi dei semi. Lino e canapa sono fibre vegetali, ma di sclerenchima (fibre liberiane del fusto): non sono fasci di trasporto privi di tessuto meccanico, né brattee. La seta è di origine animale. L'unica alternativa con descrizione corretta è il cotone.","real":true},{"id":23,"topic":"Fiore e riproduzione","type":"mc","q":"I granuli di polline:","opts":["rappresentano il mezzo di distribuzione su lunga distanza di una pianta superiore","compaiono per la prima volta nelle felci eterosporee","sono dotati di movimento proprio, per potersi avvicinare alla cellula uovo femminile","sono dei microgametofiti ridotti a pochissime cellule"],"correct":3,"why":"Il granulo pollinico è il gametofito maschile (microgametofito) delle Spermatofite, ridotto a poche cellule (vegetativa e generativa). La dispersione a distanza è compito del seme; il polline non si muove da solo e compare con le Spermatofite, non con le felci.","real":true},{"id":24,"topic":"Istologia","type":"mc","q":"Il ritidoma:","opts":["è una radice specializzata, con funzioni di riserva","è l'insieme dei tessuti morti che si accumulano nella parte più esterna del fusto primario sotto l'epidermide","è ciò che chiamiamo volgarmente \"scorza\" di un albero o di un cespuglio"],"correct":2,"why":"Il ritidoma è la \"scorza\": l'insieme dei peridermi successivi e dei tessuti morti isolati all'esterno del fusto (e della radice) in struttura SECONDARIA. La seconda alternativa è una trappola: nel fusto primario non c'è ritidoma.","real":true},{"id":26000,"topic":"Organografia","type":"label","q":"Indica le parti della foglia.","img":"foglia_parti.jpg","zw":20,"zones":[{"x":41.4,"y":5.5,"ans":"apice"},{"x":43.7,"y":15.3,"ans":"margine"},{"x":45.2,"y":26.3,"ans":"lamina"},{"x":9.0,"y":80.8,"ans":"nervatura principale","w":17},{"x":47.9,"y":72.4,"ans":"nervatura secondaria"},{"x":53.1,"y":80.8,"ans":"picciolo"},{"x":91.5,"y":82.5,"ans":"base","w":15},{"x":19.0,"y":93.8,"ans":"faccia adassiale","w":32},{"x":73.8,"y":93.8,"ans":"faccia abassiale","w":32}],"bank":["stipola","ligula"],"why":"La foglia comprende lamina (con apice, margine, nervatura principale e secondarie), picciolo e base (o guaina). La faccia adassiale è quella superiore (ventrale), rivolta verso il fusto; quella abassiale è l'inferiore (dorsale).","real":false},{"id":26001,"topic":"Fiore e riproduzione","type":"label","q":"Dal fiore al frutto: etichetta le parti corrispondenti.","img":"fiore_frutto.jpg","zw":14,"zones":[{"x":60.9,"y":5.7,"ans":"stimma"},{"x":52.3,"y":20.9,"ans":"ovulo"},{"x":67.8,"y":21.9,"ans":"seme"},{"x":52.3,"y":35.3,"ans":"parete dell'ovario"},{"x":68.0,"y":36.3,"ans":"parete del frutto"},{"x":5.0,"y":31.8,"ans":"stame","w":10},{"x":52.0,"y":52.2,"ans":"petalo"},{"x":60.1,"y":65.7,"ans":"sepalo"},{"x":59.8,"y":81.6,"ans":"ricettacolo"}],"bank":["endosperma","antera"],"why":"Dopo la fecondazione l'ovario si trasforma nel frutto: la parete dell'ovario diventa parete del frutto (pericarpo) e ogni ovulo diventa un seme. Petali e stami cadono; possono persistere sepali e ricettacolo.","real":false},{"id":26002,"topic":"Fiore e riproduzione","type":"label","q":"Seme di pino in sezione: etichetta le parti.","img":"seme_pino.jpg","zw":24,"zones":[{"x":12.0,"y":15.4,"ans":"tegumenti"},{"x":19.2,"y":35.8,"ans":"gametofito"},{"x":75.8,"y":10.8,"ans":"cotiledoni"},{"x":85.4,"y":32.0,"ans":"epicotile"},{"x":86.0,"y":58.0,"ans":"embrione"},{"x":84.5,"y":76.4,"ans":"ipocotile"},{"x":21.0,"y":85.6,"ans":"micropilo"}],"bank":["pericarpo","endosperma secondario"],"why":"Nel seme delle Gimnosperme il tessuto di riserva è il gametofito femminile (aploide, detto endosperma primario), non un endosperma secondario triploide. L'embrione, con cotiledoni, epicotile e ipocotile, è avvolto dai tegumenti; il micropilo è l'apertura da cui è entrato il tubetto pollinico. Non c'è pericarpo: il seme è nudo.","real":false},{"id":20000,"topic":"Generalità e molecole","type":"mc","q":"L'atmosfera della Terra primordiale:","opts":["era riducente, priva di O₂ libero e ricca di CH₄, NH₃, H₂, CO₂, N₂ e H₂O","era ossidante, ricca di O₂ libero e protetta da uno strato di ozono","era riducente, ma già schermata dai raggi UV grazie allo strato di ozono","era priva di acqua, che comparve solo dopo la formazione degli oceani"],"correct":0,"why":"L'atmosfera primordiale era riducente: senza O₂ libero e satura di CH₄, NH₃, H₂, CO₂, N₂ e H₂O. Proprio l'assenza di ozono lasciava passare i raggi UV ad alta energia, che insieme a fulmini e attività geotermica fornirono energia per la sintesi abiotica.","real":false},{"id":20001,"topic":"Generalità e molecole","type":"mc","q":"L'esperimento di Miller-Urey (1953):","opts":["dimostrò che il DNA si forma spontaneamente da gas primitivi sottoposti a raggi UV","riprodusse la formazione dei primi coacervati a partire da ribozimi","dimostrò che i primi organismi erano procarioti fotoautotrofi aerobi","ottenne amminoacidi come glicina e alanina da acqua e gas primitivi sottoposti a scariche elettriche"],"correct":3,"why":"Miller e Urey scaldarono acqua (l'oceano) mescolandola a gas primitivi sotto scariche elettriche, ottenendo in una settimana composti organici solubili, tra cui amminoacidi come glicina, alanina, acido aspartico e glutammico. Non ottennero DNA né cellule.","real":false},{"id":20002,"topic":"Generalità e molecole","type":"mc","q":"La cosiddetta \"catastrofe dell'ossigeno\":","opts":["fu causata dai procarioti fotosintetici anossigenici che utilizzavano H₂S","provocò la distruzione dello strato di ozono e l'aumento dei raggi UV","fu causata dai cianobatteri che, scindendo H₂O, liberarono O₂ nell'atmosfera","favorì l'espansione degli organismi anaerobi obbligati"],"correct":2,"why":"Furono i cianobatteri, con la fotolisi dell'acqua, a liberare O₂: ciò causò l'estinzione degli anaerobi obbligati, formò l'ozonosfera e aprì la strada agli aerobi. I fotosintetizzatori che usavano H₂S non producevano ossigeno.","real":false},{"id":20003,"topic":"Generalità e molecole","type":"mc","q":"Le eterocisti dei cianobatteri:","opts":["sono cellule giganti ricche di amido che fungono da spore di resistenza in condizioni avverse","sono cellule a parete spessa che spengono il fotosistema II e si specializzano nella fissazione dell'azoto","sono cellule vegetative verdi deputate alla fotosintesi ossigenica attiva","sono cellule che producono O₂ per attivare l'enzima nitrogenasi"],"correct":1,"why":"Le eterocisti hanno parete spessa impermeabile all'O₂ e spengono il fotosistema II, perché la nitrogenasi viene inattivata irreversibilmente dall'ossigeno. Le cellule giganti con riserve che fanno da spore di resistenza sono invece gli acineti.","real":false},{"id":20004,"topic":"Generalità e molecole","type":"mc","q":"Gli organismi chemioautotrofi:","opts":["ricavano energia dalla luce e il carbonio da sostanze organiche già pronte","ricavano materia ed energia da sostanze organiche assunte dall'ambiente","ricavano energia dalla luce e sintetizzano molecole organiche da sostanze inorganiche","ricavano energia dall'ossidazione di composti inorganici e sintetizzano le proprie molecole organiche da sostanze inorganiche"],"correct":3,"why":"Gli autotrofi usano solo sostanze inorganiche per costruire le proprie molecole organiche; i chemioautotrofi ricavano energia da composti inorganici ossidabili, mentre i fotoautotrofi la ricavano dalla luce. Chi ha bisogno di sostanze organiche già pronte è eterotrofo.","real":false},{"id":20005,"topic":"Generalità e molecole","type":"mc","q":"L'amido:","opts":["è un polimero del glucosio con legami beta-1,4 glicosidici, principale componente della parete vegetale","è un polimero di N-acetilglucosammina che forma la parete dei funghi","è la principale riserva delle piante, formato da unità di glucosio con legame alfa-glicosidico, per 4/5 amilopectina e 1/5 amilosio","è un disaccaride formato da glucosio e fruttosio uniti per disidratazione"],"correct":2,"why":"L'amido è il polisaccaride di riserva delle piante: centinaia di glucosi uniti da legame alfa-glicosidico, per 4/5 amilopectina e 1/5 amilosio. Il legame beta-1,4 caratterizza la cellulosa; la N-acetilglucosammina forma la chitina; il saccarosio è un disaccaride.","real":false},{"id":20006,"topic":"Generalità e molecole","type":"mc","q":"La struttura secondaria delle proteine:","opts":["è costituita da ripiegamenti locali, come alfa-elica e foglietto beta, stabilizzati da legami idrogeno","è la sequenza lineare degli amminoacidi uniti da legami peptidici","è l'associazione di più catene polipeptidiche a struttura terziaria","non viene alterata dalla denaturazione, che modifica solo la sequenza degli amminoacidi"],"correct":0,"why":"La struttura secondaria comprende alfa-elica e foglietto beta, stabilizzati da legami idrogeno tra i gruppi carbossilici e amminici dello scheletro. La sequenza è la primaria, l'associazione di più catene la quaternaria; la denaturazione altera secondaria, terziaria e quaternaria senza cambiare la sequenza.","real":false},{"id":20007,"topic":"Generalità e molecole","type":"mc","q":"Nella doppia elica del DNA:","opts":["A si appaia con U tramite 2 legami idrogeno","A si appaia con T tramite 3 legami idrogeno, formando la coppia più stabile","le basi sono rivolte all'esterno e unite da legami fosfodiesterici","G si appaia con C tramite 3 legami idrogeno, formando la coppia più stabile"],"correct":3,"why":"G-C è unita da 3 legami idrogeno ed è la coppia più stabile; A-T ne ha 2. L'uracile è esclusivo dell'RNA. Le basi sono rivolte verso l'interno, mentre i legami fosfodiesterici 5'-3' formano lo scheletro esterno.","real":false},{"id":20008,"topic":"Generalità e molecole","type":"mc","q":"Nel ciclo della fotorespirazione, la CO₂ viene liberata:","opts":["nel perossisoma, durante l'ossidazione del glicolato a gliossilato","nel mitocondrio, quando due molecole di glicina formano una molecola di serina","nel cloroplasto, durante la fosforilazione del glicerato a 3-fosfoglicerato","nel perossisoma, durante la riduzione dell'idrossipiruvato a glicerato"],"correct":1,"why":"Nel mitocondrio due glicine vengono decarbossilate e deaminate a una serina, liberando CO₂ e NH₄⁺. Nel perossisoma l'ossidazione del glicolato produce H₂O₂, non CO₂; nel cloroplasto il glicerato viene fosforilato spendendo ATP.","real":false},{"id":20009,"topic":"Generalità e molecole","type":"mc","q":"Nelle piante C4, le cellule della guaina del fascio:","opts":["possiedono cloroplasti con grana sviluppati e sono prive di Rubisco","fissano la CO₂ atmosferica tramite la PEP-carbossilasi formando ossalacetato","possiedono cloroplasti con tilacoidi privi di grana e ricchi di Rubisco, dove il malato viene decarbossilato","accumulano acido malico nel vacuolo durante la notte"],"correct":2,"why":"Nell'anatomia Kranz la guaina del fascio ha cloroplasti agranali ricchi di Rubisco, dove il malato proveniente dal mesofillo viene decarbossilato concentrando la CO₂. Grana sviluppati, assenza di Rubisco e PEP-carbossilasi caratterizzano il mesofillo; l'accumulo notturno di malato nel vacuolo è tipico delle CAM.","real":false},{"id":20010,"topic":"Generalità e molecole","type":"mc","q":"Un viroide:","opts":["è un agente infettivo delle piante costituito solo da RNA circolare non codificante, privo di rivestimento proteico","è un parassita con DNA o RNA circondato da un capside proteico","è un procariote privo di parete che infetta le cellule vegetali","è un virus che si inserisce nel genoma dell'ospite restando latente"],"correct":0,"why":"Il viroide è solo un tratto di RNA circolare di 200-400 nucleotidi non codificanti, senza capside, e infetta le piante. L'acido nucleico circondato da capside, capace anche di latenza, è il virus.","real":false},{"id":20011,"topic":"Generalità e molecole","type":"mc","q":"Carl Woese definì i tre domini della vita confrontando:","opts":["la morfologia della parete cellulare dei procarioti","le modalità trofiche degli organismi","le sequenze amminoacidiche della Rubisco","le sequenze nucleotidiche dell'rRNA ribosomiale"],"correct":3,"why":"Nel 1970 Woese costruì l'albero filogenetico confrontando le sequenze dell'rRNA, definendo Bacteria, Archaea ed Eucarya. I caratteri morfologici sono meno significativi a causa della convergenza evolutiva; le modalità trofiche servono invece a distinguere i regni degli eucarioti.","real":false},{"id":20012,"topic":"Generalità e molecole","type":"mc","q":"Secondo la teoria endosimbiontica:","opts":["i procarioti derivano da cellule eucariotiche che hanno perso il nucleo","i pluricellulari derivano dall'associazione di procarioti diversi in colonie","gli eucarioti originano da cellule procariotiche predatrici che integrarono al loro interno procarioti più piccoli non digeriti","il nucleo deriva da un cianobatterio inglobato da una cellula eucariotica"],"correct":2,"why":"Gli eucarioti deriverebbero da procarioti che predavano procarioti più piccoli: alcuni, invece di essere digeriti, sopravvivevano nel predatore continuando a svolgere funzioni come respirazione e fotosintesi. I pluricellulari compaiono più tardi, formati da cellule eucariotiche.","real":false},{"id":20013,"topic":"Generalità e molecole","type":"mc","q":"Barbara McClintock, premio Nobel nel 1984:","opts":["scoprì nel mais i trasposoni, porzioni di DNA mobili","formulò le leggi dell'ereditarietà studiando i piselli","ottenne le immagini ai raggi X della doppia elica del DNA","scoprì il DNA isolandolo dai nuclei cellulari"],"correct":0,"why":"McClintock scoprì nel mais i trasposoni, porzioni mobili di DNA. Le leggi dell'ereditarietà sui piselli sono di Mendel, le immagini ai raggi X del DNA di Rosalind Franklin e la scoperta del DNA di Miescher (1869).","real":false},{"id":20014,"topic":"Generalità e molecole","type":"mc","q":"Synechocystis sp. PCC6803:","opts":["è il cianobatterio da cui si estrae il colorante alimentare blu","è stato il primo organismo fotosintetico con genoma completamente sequenziato","è il cianobatterio simbionte della felce acquatica Azolla","è il principale responsabile della formazione degli stromatoliti della Shark Bay"],"correct":1,"why":"Synechocystis sp. PCC6803 è un organismo modello: nel 1996 fu il primo fotosintetico a essere sequenziato completamente. Il colorante blu si estrae da Arthrospira (spirulina); il simbionte di Azolla è Anabaena azollae.","real":false},{"id":20015,"topic":"Generalità e molecole","type":"multi","q":"Quali caratteri condivisi da tutti i viventi dimostrano la loro origine monofiletica?","opts":["membrana plasmatica e ribosomi","vie metaboliche comuni come la glicolisi","duplicazione semiconservativa del DNA","presenza di un nucleo delimitato da membrana","flusso dell'informazione dal DNA alle proteine","parete cellulare contenente peptidoglicano"],"correct":[0,1,2,4],"why":"Procarioti ed eucarioti condividono membrana plasmatica, ribosomi, glicolisi, duplicazione semiconservativa e trascrizione/traduzione, segno di un antenato comune (LUCA). Il nucleo manca nei procarioti e il peptidoglicano è esclusivo dei Bacteria.","real":false},{"id":20016,"topic":"Generalità e molecole","type":"multi","q":"Seleziona le affermazioni corrette sulle Viridiplantae:","opts":["parete contenente cellulosa","plastidi con clorofilla a e clorofilla b","plastidi con ficobilisomi","parete contenente chitina","comprendono alghe verdi ed embriofite","comprendono anche i cianobatteri"],"correct":[0,1,4],"why":"Le Viridiplantae (alghe verdi ed embriofite) hanno parete con cellulosa e plastidi con clorofilla a e b, privi di ficobilisomi. La chitina è tipica dei funghi; cianobatteri, funghi e altre alghe sono esclusi dal gruppo.","real":false},{"id":20017,"topic":"Generalità e molecole","type":"multi","q":"Quali sono adattamenti dell'apparato vegetativo delle piante alla vita sulla terraferma?","opts":["cuticola impermeabile con stomi","spazi intercellulari ripieni di gas","rizoidi e radici per ancoraggio e assorbimento","tessuti vascolari quando la pianta supera alcuni centimetri","ficobiline come pigmenti accessori","eterocisti per la fissazione dell'azoto"],"correct":[0,1,2,3],"why":"Cuticola con stomi, spazi intercellulari con gas, rizoidi e radici, tessuti conduttori sono adattamenti vegetativi delle embriofite. Ficobiline ed eterocisti sono caratteristiche dei cianobatteri.","real":false},{"id":20018,"topic":"Generalità e molecole","type":"multi","q":"Con quali organismi i cianobatteri azotofissatori stabiliscono simbiosi?","opts":["molti licheni","sfagni (cellule ialine)","felci acquatiche del genere Azolla","radici coralliformi delle Cycadaceae","piccioli fogliari di Gunnera","noduli radicali delle leguminose"],"correct":[0,1,2,3,4],"why":"I cianobatteri (spesso Nostoc) vivono in simbiosi con funghi nei licheni, con briofite come gli sfagni, con Azolla (Anabaena azollae), nelle radici coralliformi delle Cycadaceae e con angiosperme come Gunnera. I noduli radicali delle leguminose ospitano invece batteri azotofissatori non cianobatterici (rizobi).","real":false},{"id":20019,"topic":"Generalità e molecole","type":"multi","q":"Quale di queste affermazioni sul metodo scientifico NON è corretta?","opts":["un risultato è valido se riproducibile da altre ricerche","l'onere della prova spetta a chi confuta una tesi consolidata","la scienza è assoluta e immutabile una volta validati i risultati","la peer review, pur non priva di difetti, costringe gli autori ai migliori standard","lo stato dell'arte è il punto raggiunto dalle ricerche in una disciplina"],"correct":[2],"why":"La scienza non è assoluta né immutabile: si rimette continuamente in discussione e procede per step sperimentati e validati. Le altre affermazioni (riproducibilità, onere della prova, peer review, stato dell'arte) sono corrette.","real":false},{"id":20020,"topic":"Generalità e molecole","type":"multi","q":"Seleziona le caratteristiche comuni a tutti gli organismi viventi:","opts":["sono formati da una o più cellule","contengono DNA e lo usano per riprodursi","sono tutti autotrofi","regolano il proprio ambiente interno (omeostasi)","possiedono una parete cellulare","rispondono agli stimoli"],"correct":[0,1,3,5],"why":"I viventi hanno base cellulare, informazione genetica nel DNA, omeostasi e reattività agli stimoli. Non sono tutti autotrofi (esistono gli eterotrofi) e non tutti hanno parete (gli animali ne sono privi).","real":false},{"id":20021,"topic":"Generalità e molecole","type":"cloze","q":"Completa trascinando le parole nei riquadri.","text":"Secondo l'ipotesi del mondo a {0}, le prime molecole genetiche erano in grado di auto-replicarsi e di agire da catalizzatori biologici: tali molecole sono dette {1}. In seguito il {2} sostituì questa molecola grazie alla sua maggiore stabilità chimica.","answers":["RNA","ribozimi","DNA"],"bank":["coacervati","proteine","protobionti"],"why":"Le prime molecole genetiche furono filamenti di RNA; i ribozimi sono RNA capaci di auto-replicarsi e catalizzare reazioni. Il DNA lo sostituì perché chimicamente più stabile. Coacervati e protobionti sono aggregati di polimeri, non molecole genetiche.","real":false},{"id":20022,"topic":"Generalità e molecole","type":"cloze","q":"Completa trascinando le parole nei riquadri.","text":"I trigliceridi sono formati da una molecola di {0} esterificata con tre acidi grassi. Gli acidi grassi {1} sono privi di doppi legami e solidi a temperatura ambiente; nei {2} uno degli acidi grassi è sostituito da un gruppo fosfato, che rende la molecola anfipatica.","answers":["glicerolo","saturi","fosfolipidi"],"bank":["glucosio","insaturi","steroli","cere"],"why":"I trigliceridi sono glicerolo più tre acidi grassi; i saturi non hanno doppi legami e sono solidi, gli insaturi sono piegati e fluidi. Nei fosfolipidi un acido grasso è sostituito da un fosfato, da cui la natura anfipatica. Le cere usano un alcol diverso dal glicerolo.","real":false},{"id":20023,"topic":"Generalità e molecole","type":"cloze","q":"Completa trascinando le parole nei riquadri.","text":"C, H, N e O costituiscono il {0} della materia secca dei viventi. Ogni atomo di carbonio può formare {1} legami covalenti, e i composti organici contengono C e H con almeno un legame {2}.","answers":["96%","quattro","carbonio–carbonio"],"groups":[0,1,2],"bank":[["50%"],["due"],["carbonio–ossigeno"]],"why":"Carbonio, idrogeno, azoto e ossigeno formano il 96% della materia secca, con l'aggiunta di zolfo e fosforo. Il carbonio forma quattro legami covalenti e i composti organici contengono C e H con almeno un legame C–C.","real":false},{"id":20024,"topic":"Generalità e molecole","type":"cloze","q":"Completa trascinando le parole nei riquadri.","text":"Nella sintesi per {0} due monomeri si legano liberando una molecola d'acqua, grazie a enzimi detti {1}; nell'{2}, al contrario, una molecola d'acqua rompe il polimero.","answers":["disidratazione","polimerasi","idrolisi"],"bank":["ossidazione","cellulasi","denaturazione"],"why":"Nella sintesi per disidratazione si rimuovono un H da un monomero e un OH dall'altro, liberando acqua, con catalisi delle polimerasi. L'idrolisi è il processo opposto: l'acqua cede H e OH ai due monomeri separandoli.","real":false},{"id":20025,"topic":"Generalità e molecole","type":"cloze","q":"Completa trascinando le parole nei riquadri.","text":"Nella {0}, che avviene nel nucleo, l'enzima {1} copia il messaggio del DNA in una molecola di mRNA. Nella {2}, che avviene nei {3}, l'mRNA guida la sintesi del polipeptide.","answers":["trascrizione","RNA polimerasi","traduzione","ribosomi"],"bank":["duplicazione","DNA polimerasi","mitocondri"],"why":"Secondo il dogma centrale (DNA → RNA → proteine), la trascrizione nel nucleo è catalizzata dalla RNA polimerasi, mentre la traduzione avviene nei ribosomi. La DNA polimerasi interviene nella duplicazione semiconservativa del DNA.","real":false},{"id":20026,"topic":"Generalità e molecole","type":"cloze","q":"Completa trascinando le parole nei riquadri.","text":"Nelle piante CAM gli stomi si aprono di {0}: la PEP-carbossilasi fissa la CO₂ e l'acido malico si accumula nel {1}, che si acidifica. Di {2}, con gli stomi chiusi, il malato viene decarbossilato e la CO₂ è fissata dalla {3}.","answers":["notte","vacuolo","giorno","Rubisco"],"bank":["cloroplasto","guaina del fascio","catalasi"],"why":"Le CAM separano le fasi nel tempo: di notte assorbono CO₂ e accumulano acido malico nel vacuolo (pH fino a 3); di giorno, a stomi chiusi, il malato viene decarbossilato e la CO₂ entra nel ciclo di Calvin tramite la Rubisco. La guaina del fascio riguarda invece la separazione spaziale delle C4.","real":false},{"id":20027,"topic":"Generalità e molecole","type":"cloze","q":"Completa trascinando le parole nei riquadri.","text":"Le cellule procariotiche non hanno {0} né organuli delimitati da membrane. Il loro DNA è una singola molecola ad {1}, associata a proteine {2}, e la regione della cellula che lo contiene è detta {3}.","answers":["nucleo","anello","non istoniche","nucleoide"],"bank":["istoniche","elica lineare","cromosoma"],"why":"I procarioti non hanno compartimenti interni: il DNA è una lunga molecola circolare associata a proteine non istoniche, raccolta nel nucleoide, che non è delimitato da membrana. Le proteine istoniche formano invece la cromatina degli eucarioti.","real":false},{"id":20028,"topic":"Generalità e molecole","type":"match","q":"Associa a ogni struttura dei cianobatteri la sua descrizione.","rows":[{"label":"Acineti","ans":"cellule giganti con riserve e pareti ispessite, spore di resistenza"},{"label":"Eterocisti","ans":"cellule a parete spessa specializzate nella fissazione dell'azoto"},{"label":"Tricoma","ans":"forma filamentosa coloniale più caratteristica"},{"label":"Stromatoliti","ans":"formazioni rocciose biogeniche dovute a sedimento intrappolato nella mucillagine"},{"label":"Ficobiline","ans":"pigmenti come ficoeritrina e ficocianina"}],"options":["cellule giganti con riserve e pareti ispessite, spore di resistenza","cellule a parete spessa specializzate nella fissazione dell'azoto","forma filamentosa coloniale più caratteristica","formazioni rocciose biogeniche dovute a sedimento intrappolato nella mucillagine","pigmenti come ficoeritrina e ficocianina","cellule verdi normali deputate alla fotosintesi attiva"],"why":"Gli acineti sono spore di resistenza ricche di riserve, le eterocisti fissano N₂, il tricoma è la forma filamentosa tipica, gli stromatoliti derivano dalla mucillagine che intrappola sedimento, le ficobiline sono pigmenti accessori. Le cellule vegetative sono quelle che fanno fotosintesi attiva.","real":false},{"id":20029,"topic":"Generalità e molecole","type":"match","q":"Associa a ogni gruppo di vegetali la sua caratteristica.","rows":[{"label":"Briofite","ans":"crittogame prive di sistema vascolare"},{"label":"Pteridofite","ans":"crittogame vascolari prive di semi"},{"label":"Gimnosperme","ans":"spermatofite a semi nudi"},{"label":"Angiosperme","ans":"spermatofite con semi racchiusi nel frutto"}],"options":["crittogame prive di sistema vascolare","crittogame vascolari prive di semi","spermatofite a semi nudi","spermatofite con semi racchiusi nel frutto","spermatofite prive di sistema vascolare"],"why":"Le briofite sono crittogame non vascolari; le pteridofite (felci) sono tracheofite senza semi; tra le spermatofite, le gimnosperme hanno semi nudi e le angiosperme semi racchiusi nel frutto. Non esistono spermatofite prive di sistema vascolare.","real":false},{"id":20030,"topic":"Generalità e molecole","type":"sort","q":"Trascina ogni caratteristica nel dominio giusto.","cats":["Bacteria","Archaea","Eucarya"],"items":[{"t":"Parete con peptidoglicano (mureina)","cat":0},{"t":"Includono i cianobatteri","cat":0},{"t":"Lipidi di membrana con legami etere e catene ramificate (fitanile)","cat":1},{"t":"Parete con pseudomureina o proteine S-layer","cat":1},{"t":"Metanogeni, anaerobi produttori di CH₄","cat":1},{"t":"Nucleo e organelli delimitati da endomembrane","cat":2},{"t":"Vera compartimentazione interna","cat":2}],"why":"I Bacteria, tra cui i cianobatteri, hanno parete con peptidoglicano; gli Archaea, filogeneticamente più vicini agli eucarioti, hanno lipidi con legami etere e catene ramificate, parete senza peptidoglicano e comprendono i metanogeni. Gli Eucarya hanno nucleo e organelli delimitati da membrane.","real":false},{"id":20031,"topic":"Generalità e molecole","type":"sort","q":"Trascina ogni caratteristica nel regno eucariotico giusto.","cats":["Protisti","Funghi","Animali","Piante"],"items":[{"t":"Gruppo parafiletico senza embrione né veri tessuti","cat":0},{"t":"Comprendono protozoi e alghe","cat":0},{"t":"Parete cellulare di chitina","cat":1},{"t":"Secernono enzimi idrolitici all'esterno e assorbono i monomeri digeriti","cat":1},{"t":"Eterotrofi per ingestione interna","cat":2},{"t":"Privi di parete, a crescita definita","cat":2},{"t":"Fotoautotrofi che si sviluppano da un embrione protetto da tessuti materni","cat":3}],"why":"I regni eucariotici si distinguono soprattutto per la modalità trofica. I Protisti sono un gruppo parafiletico senza embrione (protozoi, alghe, mixomiceti); i Funghi digeriscono all'esterno con enzimi secreti, assorbono i monomeri e hanno parete di chitina; gli Animali ingeriscono e non hanno parete; le Piante sono fotoautotrofe e si sviluppano da un embrione protetto.","real":false},{"id":21000,"topic":"Citologia","type":"mc","q":"La cellula procariota:","opts":["possiede una parete, se presente, costituita da cellulosa o chitina","si divide per mitosi e ha il DNA organizzato in cromatina","possiede DNA circolare libero nel citoplasma e, come organelli, solo ribosomi 70S","contiene mitocondri ma è priva di reticolo endoplasmatico"],"correct":2,"why":"Il procariote non ha membrana nucleare, ha DNA circolare libero, solo ribosomi 70S e parete a peptidoglicani, e si divide per scissione binaria. Parete in cellulosa o chitina, mitosi, cromatina e mitocondri sono caratteristiche eucariote.","real":false},{"id":21001,"topic":"Citologia","type":"mc","q":"Quale di queste strutture è presente nella cellula animale ma NON in quella vegetale?","opts":["vacuolo","centrioli","mitocondri","plastidi"],"correct":1,"why":"Centrioli, ciglia e flagelli e lisosomi sono esclusivi della cellula animale. Vacuolo e plastidi sono esclusivi della vegetale, mentre i mitocondri sono comuni a entrambe.","real":false},{"id":21002,"topic":"Citologia","type":"mc","q":"Il principio «omnis cellula e cellula» (ogni cellula deriva da una cellula preesistente) si deve a:","opts":["Robert Hooke, nel 1665","Lynn Margulis, nel 1967","Singer e Nicolson, nel 1972","Rudolf Virchow, nel 1858"],"correct":3,"why":"Virchow (1858) formulò il principio per cui tutte le cellule derivano da cellule preesistenti. Hooke coniò il termine «cells» nel 1665, Margulis propose la teoria endosimbiontica, Singer e Nicolson il modello a mosaico fluido.","real":false},{"id":21003,"topic":"Citologia","type":"mc","q":"Il principio secondo cui tutte le cellule provengono da cellule preesistenti:","opts":["confuta la teoria della generazione spontanea","fu formulato da Robert Hooke osservando il sughero al microscopio","vale solo per le cellule eucariote, originate per endosimbiosi","afferma che tutti gli organismi sono composti di cellule"],"correct":0,"why":"Il terzo principio della teoria cellulare, dovuto a Virchow, confuta la generazione spontanea. Hooke coniò solo il termine «cells»; che tutti gli organismi siano fatti di cellule è un principio distinto.","real":false},{"id":21004,"topic":"Citologia","type":"mc","q":"Nel modello a mosaico fluido della membrana:","opts":["la diffusione trasversale (flip-flop) dei lipidi è rapida e spontanea","la diffusione laterale dei lipidi è veloce, mentre il flip-flop è molto lento e mediato dalla flippasi","i lipidi sono uniti da legami covalenti che rendono statico il doppio strato","le code idrofobe dei fosfolipidi sono rivolte verso l'ambiente acquoso"],"correct":1,"why":"Il doppio strato non è statico e non ha legami covalenti tra i lipidi: diffusione laterale e rotazione sono veloci, il passaggio trasversale è lento e richiede la flippasi. Le code idrofobe sono rivolte verso l'interno del doppio strato.","real":false},{"id":21005,"topic":"Citologia","type":"mc","q":"La fluidità della membrana plasmatica aumenta:","opts":["in presenza di acidi grassi insaturi con doppi legami cis","all'aumentare della lunghezza delle catene degli acidi grassi","all'aumentare del contenuto di colesterolo","all'abbassarsi della temperatura"],"correct":0,"why":"I doppi legami cis piegano le code e ne impediscono il compattamento, aumentando la fluidità. Catene più lunghe, colesterolo e basse temperature invece la riducono (a basse temperature la membrana tende a gelificare).","real":false},{"id":21006,"topic":"Citologia","type":"mc","q":"Le acquaporine:","opts":["sono canali transmembrana che consentono un flusso rapido di acqua per osmosi, escludendo i protoni","consumano ATP per pompare acqua contro il suo gradiente","sono proteine estrinseche legate debolmente alle teste polari dei lipidi","sono presenti nel plasmalemma ma mai nel tonoplasto"],"correct":0,"why":"Le acquaporine sono canali proteici transmembrana selettivi: l'acqua passa per osmosi senza consumo di energia e i protoni sono esclusi. Sono abbondanti anche nel tonoplasto.","real":false},{"id":21007,"topic":"Citologia","type":"mc","q":"Il symporto saccarosio/H⁺ che carica gli zuccheri nel floema è un esempio di:","opts":["trasporto attivo primario","diffusione facilitata tramite canale","trasporto vescicolare","trasporto attivo secondario"],"correct":3,"why":"Il cotrasporto non consuma ATP direttamente ma sfrutta il gradiente di H⁺ creato dalla pompa protonica (primaria) per muovere un secondo soluto contro gradiente. Nel symporto i due soluti vanno nella stessa direzione.","real":false},{"id":21008,"topic":"Citologia","type":"mc","q":"Nelle cellule vegetali la pompa protonica H⁺-ATPasi di membrana:","opts":["immette protoni nel citoplasma acidificandolo","scambia 3 Na⁺ con 2 K⁺ consumando ATP","estrude protoni verso la parete generando un potenziale elettrico negativo all'interno","trasporta protoni sfruttando un gradiente di Na⁺, senza consumare ATP"],"correct":2,"why":"La H⁺-ATPasi è un trasporto attivo primario: idrolizza ATP per espellere H⁺ nella parete, creando gradiente di pH e interno negativo (forza proton-motrice). La Na⁺/K⁺-ATPasi è l'esempio tipico animale.","real":false},{"id":21009,"topic":"Citologia","type":"mc","q":"Il reticolo endoplasmatico liscio (SER):","opts":["è sede della sintesi dei lipidi di membrana e dell'accumulo di ioni Ca²⁺","porta ribosomi ancorati alla superficie tramite riboforine","è la sede della prima N-glicosilazione delle proteine neosintetizzate","produce e assembla le subunità ribosomiali"],"correct":0,"why":"Il SER, privo di ribosomi, sintetizza fosfolipidi, galattolipidi e ormoni steroidei, accumula Ca²⁺ e detossifica. Riboforine e N-glicosilazione riguardano il RER; le subunità ribosomiali si formano nel nucleolo.","real":false},{"id":21010,"topic":"Citologia","type":"mc","q":"I ribosomi:","opts":["sono organelli delimitati da una singola membrana, prodotti nel Golgi","sono di tipo 80S nel citoplasma eucariote e di tipo 70S in mitocondri e cloroplasti","sono di tipo 70S sia nel citoplasma eucariote sia nei procarioti","se legati al RER, sintetizzano le proteine destinate a mitocondri e perossisomi"],"correct":1,"why":"I ribosomi sono complessi ribonucleoproteici privi di membrana prodotti nel nucleolo: 80S nel citoplasma eucariote, 70S in mitocondri e cloroplasti. Le proteine per mitocondri e perossisomi sono prodotte dai ribosomi liberi.","real":false},{"id":21011,"topic":"Citologia","type":"mc","q":"Nella cellula vegetale l'apparato di Golgi (dittiosomi) è la sede principale di sintesi:","opts":["della cellulosa della parete","dei lipidi di membrana e degli ormoni steroidei","delle pectine e delle emicellulose della matrice di parete","degli RNA ribosomiali"],"correct":2,"why":"Il Golgi sintetizza ed esporta per via vescicolare i polisaccaridi non cellulosici della parete. La cellulosa è prodotta sulla membrana dalle rosette CesA, i lipidi nel SER e gli rRNA nel nucleolo.","real":false},{"id":21012,"topic":"Citologia","type":"mc","q":"La membrana interna del mitocondrio:","opts":["è ricca di cardiolipina, impermeabile agli ioni e ripiegata in creste","è ricca di porine e liberamente permeabile a ioni e piccole molecole","contiene il DNA circolare mitocondriale (condrioma)","è la sede degli enzimi del ciclo di Krebs"],"correct":0,"why":"La membrana interna, priva di porine e ricca di cardiolipina, forma le creste con catena di trasporto e ATP-sintasi. Le porine sono nella membrana esterna; DNA e ciclo di Krebs si trovano nella matrice.","real":false},{"id":21013,"topic":"Citologia","type":"mc","q":"I gliossisomi:","opts":["sono plastidi che accumulano lipidi e oli vegetali","sono i perossisomi che nelle foglie delle piante C3 partecipano alla fotorespirazione","sono vacuoli modificati che accumulano proteine di riserva","sono perossisomi specializzati dei semi oleosi in germinazione, che convertono i lipidi di riserva in zuccheri"],"correct":3,"why":"I gliossisomi contengono gli enzimi del ciclo del gliossilato, che trasforma i trigliceridi in saccarosio per nutrire l'embrione. Gli elaioplasti accumulano oli, i perossisomi fogliari partecipano alla fotorespirazione, i granuli di aleurone accumulano proteine.","real":false},{"id":21014,"topic":"Citologia","type":"mc","q":"I microfilamenti di actina, cooperando con la miosina:","opts":["formano il fragmoplasto e la banda premitotica","generano la ciclosi e guidano l'accrescimento apicale del tubetto pollinico","costituiscono la lamina nucleare sotto l'involucro","guidano le rosette CesA nella deposizione della cellulosa"],"correct":1,"why":"Actina e miosina producono il flusso citoplasmatico e l'accrescimento polarizzato del tubetto pollinico. Fragmoplasto, banda premitotica e guida delle rosette CesA sono compiti dei microtubuli, la lamina nucleare dei filamenti intermedi.","real":false},{"id":21015,"topic":"Citologia","type":"mc","q":"Attraverso i pori nucleari:","opts":["RNA e subunità ribosomiali escono verso il citoplasma per trasporto attivo","gli istoni escono dal nucleo per diffusione passiva","i ribosomi completi entrano nel nucleo per tradurre l'mRNA","passano solo ioni, mentre le macromolecole attraversano la doppia membrana"],"correct":0,"why":"Piccole proteine e metaboliti passano per via passiva, mentre RNA e subunità ribosomiali (in uscita) e istoni e polimerasi (in entrata) richiedono trasporto attivo con carrier. La traduzione avviene nel citoplasma, non nel nucleo.","real":false},{"id":21016,"topic":"Citologia","type":"mc","q":"Nella cellula eucariote la traduzione dell'mRNA avviene:","opts":["nel nucleo, contemporaneamente alla trascrizione","nel nucleolo, dove si assemblano i ribosomi","nel citoplasma, dopo l'uscita dell'RNA dal nucleo attraverso i pori","nello spazio tra le due membrane dell'involucro nucleare"],"correct":2,"why":"La compartimentazione eucariote separa replicazione e sintesi dell'RNA (nel nucleo) da traduzione e maturazione delle proteine (nel citoplasma). Nel nucleolo si formano solo le subunità ribosomiali, esportate separatamente.","real":false},{"id":21017,"topic":"Citologia","type":"mc","q":"Nel nucleolo:","opts":["si assemblano ribosomi 80S completi, che poi escono attraverso i pori","vengono tradotte le proteine ribosomiali","si forma la lamina nucleare di filamenti intermedi","la RNA polimerasi I trascrive i precursori degli rRNA, poi assemblati con proteine in subunità ribosomiali"],"correct":3,"why":"Il nucleolo trascrive e matura gli rRNA (18S, 5.8S, 28S) e li assembla con proteine importate dal citoplasma; le subunità minore e maggiore escono separatamente e formano il ribosoma nel citoplasma.","real":false},{"id":21018,"topic":"Citologia","type":"mc","q":"Il nucleosoma è formato da:","opts":["DNA avvolto attorno a un ottamero di istoni (due copie ciascuno di H2A, H2B, H3 e H4)","DNA avvolto attorno a un ottamero di istoni H1","RNA ribosomiale associato a proteine basiche","DNA linker associato a lamine e cheratine"],"correct":0,"why":"Circa 146 paia di basi si avvolgono attorno all'ottamero H2A, H2B, H3, H4. H1 è l'istone di collegamento associato al DNA linker tra un nucleosoma e l'altro.","real":false},{"id":21019,"topic":"Citologia","type":"mc","q":"I cromoplasti:","opts":["accumulano antociani idrosolubili che colorano fiori e frutti","sono plastidi privi di pigmento, specializzati nell'accumulo di amido","accumulano pigmenti carotenoidi e possono derivare da cloroplasti senescenti","possiedono tilacoidi ben strutturati impilati in grana"],"correct":2,"why":"I cromoplasti, privi di tilacoidi strutturati, accumulano carotenoidi lipofili (carotene, xantofille, licopene). Gli antociani idrosolubili stanno nel vacuolo; l'amido negli amiloplasti (leucoplasti).","real":false},{"id":21020,"topic":"Citologia","type":"mc","q":"Tra le due membrane dell'involucro del cloroplasto è presente:","opts":["uno strato di cellulosa, come nella parete","uno strato di peptidoglicano, prova dell'origine cianobatterica","la lamina nucleare","il lumen dei tilacoidi"],"correct":1,"why":"Lo strato di peptidoglicano tra le membrane del cloroplasto è un'evidenza della sua origine da un cianobatterio. Il lumen è lo spazio interno dei tilacoidi, dentro lo stroma.","real":false},{"id":21021,"topic":"Citologia","type":"mc","q":"Nell'enzima Rubisco:","opts":["le 8 subunità grandi sono codificate dal nucleo, le 8 piccole dal plastoma","tutte le subunità sono codificate dal plastoma e tradotte sui ribosomi 70S","tutte le subunità sono codificate dal nucleo e importate nel cloroplasto","le 8 subunità grandi sono codificate dal plastoma, le 8 piccole dal nucleo"],"correct":3,"why":"Le subunità grandi (con il sito attivo) sono codificate dal DNA plastidiale e tradotte sui 70S; le piccole sono nucleari, tradotte sugli 80S e importate. È un esempio di cooperazione plastoma-genoma.","real":false},{"id":21022,"topic":"Citologia","type":"mc","q":"Il succo vacuolare:","opts":["ha pH basico, che fa virare gli antociani al blu","ha pH acido e può accumulare antociani, alcaloidi e cristalli di ossalato di calcio","contiene carotenoidi liposolubili che colorano i frutti","è racchiuso da una doppia membrana di origine endosimbiontica"],"correct":1,"why":"Il succo vacuolare ha pH inferiore a 5 e accumula metaboliti secondari (antociani, alcaloidi, tannini) e cristalli. I carotenoidi stanno nei cromoplasti; il vacuolo è delimitato da una sola membrana, il tonoplasto.","real":false},{"id":21023,"topic":"Citologia","type":"mc","q":"La parete primaria:","opts":["è sottile ed estensibile, con cellulosa a tessitura dispersa in una matrice di emicellulose e pectine","si deposita solo al termine dell'accrescimento, in tre sottostrati S1, S2, S3","è comune a due cellule adiacenti ed è formata soprattutto da pectine","è impregnata di lignina fin dalla sua formazione"],"correct":0,"why":"La parete primaria, presente nelle cellule giovani, permette la distensione sotto il turgore. I sottostrati S1-S3 appartengono alla parete secondaria; lo strato comune pectico è la lamella mediana.","real":false},{"id":21024,"topic":"Citologia","type":"mc","q":"La lignificazione della parete:","opts":["procede dalla lamella mediana verso l'interno, alternando lamelle di suberina e cellulosa","riguarda solo la faccia esterna delle cellule, che restano vitali","procede dallo strato più interno verso la lamella mediana e impedisce la distensione cellulare","consiste nell'arricchimento in pectine con formazione di mucillagini"],"correct":2,"why":"La lignina, polimero aromatico idrofobo, irrigidisce la parete partendo dall'interno. Le lamelle alternate dalla lamella mediana sono tipiche della suberificazione, la faccia esterna della cutinizzazione, le mucillagini della gelificazione.","real":false},{"id":21025,"topic":"Citologia","type":"multi","q":"Seleziona gli elementi che fanno parte del citoscheletro:","opts":["microtubuli","filamenti intermedi","microfibrille di cellulosa","microfilamenti di actina","plasmodesmi","tilacoidi"],"correct":[0,1,3],"why":"Il citoscheletro comprende microtubuli, microfilamenti di actina e filamenti intermedi. Le microfibrille di cellulosa sono in parete, i plasmodesmi sono canali tra cellule e i tilacoidi sono membrane del cloroplasto.","real":false},{"id":21026,"topic":"Citologia","type":"multi","q":"Quali di questi NON sono principi della teoria cellulare?","opts":["le cellule sono le unità fondamentali della vita","tutti gli organismi sono composti di cellule","tutte le cellule possiedono un nucleo delimitato da membrana","tutte le cellule provengono da cellule preesistenti","le cellule possono formarsi per generazione spontanea"],"correct":[2,4],"why":"I tre principi sono: cellula come unità fondamentale, organismi composti di cellule, derivazione da cellule preesistenti. I procarioti non hanno nucleo e la generazione spontanea è proprio ciò che la teoria confuta.","real":false},{"id":21027,"topic":"Citologia","type":"multi","q":"Quali sono evidenze a supporto della teoria endosimbiontica?","opts":["mitocondri e cloroplasti hanno DNA e ribosomi 70S simili a quelli dei procarioti","mitocondri e cloroplasti si riproducono per fissione binaria","la cellula può riformare plastidi e mitocondri a partire dal reticolo endoplasmatico","porine e cardiolipine si trovano solo in procarioti, mitocondri e cloroplasti","i mitocondri possiedono centrioli propri"],"correct":[0,1,3],"why":"DNA e ribosomi 70S, divisione per fissione binaria e biomolecole esclusive (porine, cardiolipine) accomunano organelli e procarioti. Al contrario, se rimossi, plastidi e mitocondri non possono essere riformati dalla cellula.","real":false},{"id":21028,"topic":"Citologia","type":"multi","q":"Quali di queste cellule sono anucleate a maturità?","opts":["le cellule dell'endosperma dei semi","i tubi cribrosi del floema delle Angiosperme","le cellule meristematiche degli apici","i globuli rossi maturi dei mammiferi","alcune cellule algali"],"correct":[1,3],"why":"Tubi cribrosi delle Angiosperme e globuli rossi maturi dei mammiferi sono privi di nucleo. Endosperma e alcune cellule algali sono invece plurinucleate, le cellule meristematiche hanno un nucleo.","real":false},{"id":21029,"topic":"Citologia","type":"multi","q":"Seleziona le strutture presenti sia nella cellula vegetale sia in quella animale:","opts":["mitocondri","parete cellulare","ribosomi","lisosomi","citoscheletro","vacuolo"],"correct":[0,2,4],"why":"Plasmalemma, nucleo, endomembrane, ribosomi, mitocondri e citoscheletro sono comuni. Parete e vacuolo sono esclusivi della cellula vegetale, i lisosomi di quella animale.","real":false},{"id":21030,"topic":"Citologia","type":"multi","q":"Quali caratteristiche sono proprie dei plastidi e del plastoma?","opts":["DNA circolare privo di sequenze ripetitive ma con introni","ereditarietà uniparentale materna","divisione per scissione binaria","geni soggetti a crossing-over durante la meiosi","ribosomi di tipo 80S"],"correct":[0,1,2],"why":"Il plastoma è circolare con introni, l'ereditarietà è materna non mendeliana e i plastidi si dividono per scissione binaria. I geni degli organelli non fanno crossing-over e i ribosomi plastidiali sono 70S.","real":false},{"id":21031,"topic":"Citologia","type":"multi","q":"Quali di queste sostanze attraversano il doppio strato fosfolipidico per diffusione semplice?","opts":["O₂","CO₂","ioni K⁺","H₂O","glucosio"],"correct":[0,1,3],"why":"Per diffusione semplice passano gas e piccole molecole non polari o polari neutre come l'acqua. Gli ioni richiedono canali proteici e il glucosio trasportatori carrier (diffusione facilitata).","real":false},{"id":21032,"topic":"Citologia","type":"multi","q":"Quali sono funzioni del vacuolo della cellula vegetale?","opts":["mantenimento del turgore cellulare","funzione digestiva idrolitica, analoga ai lisosomi","accumulo di metaboliti secondari come alcaloidi e tannini","sintesi della cellulosa della parete","fotolisi dell'acqua"],"correct":[0,1,2],"why":"Il vacuolo accumula soluti che richiamano acqua (turgore), ha funzione litica e immagazzina metaboliti secondari. La cellulosa è sintetizzata dalle rosette CesA della membrana; la fotolisi avviene nei tilacoidi.","real":false},{"id":21033,"topic":"Citologia","type":"cloze","q":"Completa trascinando le parole nei riquadri.","text":"Il modello a {0}, proposto da Singer e Nicolson nel 1972, descrive la membrana come un doppio strato lipidico in cui la diffusione {1} è veloce, mentre la diffusione {2} (flip-flop) è molto lenta ed è mediata dall'enzima {3}.","answers":["mosaico fluido","laterale","trasversale","flippasi"],"bank":["doppia elica","catalasi","ATP-sintasi"],"why":"Nel mosaico fluido i lipidi si spostano rapidamente nel proprio strato, mentre il passaggio da uno strato all'altro è lento e richiede la flippasi.","real":false},{"id":21034,"topic":"Citologia","type":"cloze","q":"Completa trascinando le parole nei riquadri.","text":"Nella cellula eucariote l'RNA viene sintetizzato nel {0}; esce attraverso i {1} grazie a un trasporto {2} e viene tradotto nel {3} dai {4}.","answers":["nucleo","pori nucleari","attivo","citoplasma","ribosomi"],"bank":["passivo","plasmodesmi","vacuolo","lisosomi"],"why":"Trascrizione e maturazione dell'RNA avvengono nel nucleo; gli RNA escono con trasporto attivo mediato da carrier e la traduzione avviene nel citoplasma sui ribosomi. I plasmodesmi collegano cellule diverse, non nucleo e citoplasma.","real":false},{"id":21035,"topic":"Citologia","type":"cloze","q":"Completa trascinando le parole nei riquadri.","text":"La cellula {0} è priva di membrana nucleare, possiede ribosomi {1} e, se presente, una parete di {2}; si divide per {3}.","answers":["procariota","70S","peptidoglicani","scissione binaria"],"bank":[["eucariota"],["80S"],["cellulosa","chitina"],["mitosi","meiosi"]],"groups":[0,1,2,3],"why":"Il procariote ha DNA circolare libero, solo ribosomi 70S, parete a peptidoglicani e scissione binaria. Cellulosa o chitina, ribosomi 80S e mitosi/meiosi caratterizzano gli eucarioti.","real":false},{"id":21036,"topic":"Citologia","type":"cloze","q":"Completa trascinando le parole nei riquadri.","text":"Il termine «cells» fu coniato da {0} nel 1665 osservando il {1}; la teoria cellulare fu formulata nel {2} e completata da {3} con il principio «omnis cellula e cellula».","answers":["Robert Hooke","sughero","1839","Rudolf Virchow"],"bank":["Lynn Margulis","legno di quercia","1972"],"why":"Hooke osservò il sughero nel 1665; la teoria cellulare è del 1839 e Virchow nel 1858 aggiunse che ogni cellula deriva da una preesistente. Margulis è legata alla teoria endosimbiontica.","real":false},{"id":21037,"topic":"Citologia","type":"cloze","q":"Completa trascinando le parole nei riquadri.","text":"Nel cloroplasto i {0} impilati formano i {1}; nelle loro membrane avviene la fase luminosa, con la {2} dell'acqua, mentre il ciclo di Calvin avviene nello {3}.","answers":["tilacoidi","grana","fotolisi","stroma"],"bank":["plastoglobuli","idrolisi","lumen","cristalli"],"why":"I tilacoidi ospitano fotosistemi e fotolisi dell'acqua con rilascio di O₂; il ciclo di Calvin si svolge nello stroma, matrice che li circonda. Il lumen è lo spazio interno dei tilacoidi.","real":false},{"id":21038,"topic":"Citologia","type":"cloze","q":"Completa trascinando le parole nei riquadri.","text":"La parete cellulare si deposita in direzione {0}: lo strato più esterno, comune a due cellule adiacenti, è la {1}, ricca di {2}; segue la parete primaria e, al termine dell'accrescimento, la parete {3}.","answers":["centripeta","lamella mediana","pectine","secondaria"],"bank":["centrifuga","cutina","terziaria"],"why":"La parete è secreta dall'esterno verso l'interno: lamella mediana pectica, poi parete primaria, poi parete secondaria ricca di cellulosa, deposta solo dopo la fine dell'accrescimento.","real":false},{"id":21039,"topic":"Citologia","type":"cloze","q":"Completa trascinando le parole nei riquadri.","text":"La cellulosa è un polimero del {0} con legami {1}; è sintetizzata sulla membrana plasmatica dalle {2} di celluloso-sintasi, che si muovono lungo i {3} corticali.","answers":["glucosio","β-1,4","rosette","microtubuli"],"bank":["galattosio","α-1,4","dittiosomi","microfilamenti"],"why":"La cellulosa è un polimero lineare di glucosio β-1,4, prodotto dalle rosette CesA guidate dai microtubuli corticali. Pectine ed emicellulose sono invece sintetizzate nei dittiosomi.","real":false},{"id":21040,"topic":"Citologia","type":"cloze","q":"Completa trascinando le parole nei riquadri.","text":"Il vacuolo è delimitato dal {0}; i piccoli {1}, originati dal Golgi, si fondono nel grande vacuolo vegetativo. Nei semi i granuli di {2} sono vacuoli modificati che accumulano {3}.","answers":["tonoplasto","provacuoli","aleurone","proteine"],"bank":["plasmalemma","proplastidi","amido","lipidi"],"why":"Il tonoplasto deriva dalla fusione delle membrane dei provacuoli. I granuli di aleurone accumulano proteine solubili (globuline, albumine) mobilizzate alla germinazione; i proplastidi originano invece i plastidi.","real":false},{"id":21041,"topic":"Citologia","type":"cloze","q":"Completa trascinando le parole nei riquadri.","text":"L'amido {0} si accumula di giorno nello stroma del cloroplasto; di notte viene idrolizzato ed esportato nel floema come {1}. Negli organi di riserva viene ripolimerizzato negli {2} come amido secondario, in strati concentrici attorno all'{3}.","answers":["primario","saccarosio","amiloplasti","ilo"],"bank":["secondario","elaioplasti","nucleolo","amilosio"],"why":"L'amido primario, osmoticamente inattivo, evita squilibri nel cloroplasto; di notte è convertito in saccarosio e traslocato verso i sink, dove gli amiloplasti lo ridepongono attorno all'ilo. Gli elaioplasti accumulano oli.","real":false},{"id":21042,"topic":"Citologia","type":"cloze","q":"Completa trascinando le parole nei riquadri.","text":"Nella citocinesi vegetale le vescicole del {0}, guidate da un sistema di microtubuli detto {1}, formano la {2}, che si espande dal centro verso la periferia lasciando i {3}.","answers":["dittiosoma","fragmoplasto","piastra cellulare","plasmodesmi"],"bank":["centriolo","solco di divisione","desmosomi"],"why":"Nelle piante la citocinesi avviene per formazione della piastra cellulare dalle vescicole del Golgi guidate dal fragmoplasto; si espande centrifugamente fino alla parete preesistente, lasciando i plasmodesmi.","real":false},{"id":21043,"topic":"Citologia","type":"match","q":"Associa a ogni struttura la sua funzione principale.","rows":[{"label":"Nucleolo","ans":"sintesi degli rRNA e assemblaggio delle subunità ribosomiali"},{"label":"Reticolo endoplasmatico liscio","ans":"sintesi dei lipidi di membrana e accumulo di Ca²⁺"},{"label":"Faccia trans del Golgi","ans":"smistamento finale in vescicole secretorie"},{"label":"Perossisoma","ans":"demolizione dell'H₂O₂ tramite catalasi"},{"label":"Mitocondrio","ans":"ciclo di Krebs e sintesi di ATP"}],"options":["sintesi degli rRNA e assemblaggio delle subunità ribosomiali","sintesi dei lipidi di membrana e accumulo di Ca²⁺","smistamento finale in vescicole secretorie","demolizione dell'H₂O₂ tramite catalasi","ciclo di Krebs e sintesi di ATP","fotolisi dell'acqua","sintesi della cellulosa"],"why":"Ogni organello svolge funzioni compartimentate: nucleolo per i ribosomi, SER per i lipidi, trans-Golgi per lo smistamento, perossisomi per l'H₂O₂, mitocondri per la respirazione. La fotolisi avviene nei tilacoidi, la cellulosa è sintetizzata dalle rosette in membrana.","real":false},{"id":21044,"topic":"Citologia","type":"match","q":"Associa a ogni plastidio ciò che lo caratterizza.","rows":[{"label":"Cloroplasto","ans":"fotosintesi"},{"label":"Cromoplasto","ans":"accumulo di carotenoidi"},{"label":"Amiloplasto","ans":"accumulo di amido secondario"},{"label":"Elaioplasto","ans":"accumulo di lipidi e oli"},{"label":"Ezioplasto","ans":"sviluppo bloccato dall'assenza di luce"}],"options":["fotosintesi","accumulo di carotenoidi","accumulo di amido secondario","accumulo di lipidi e oli","sviluppo bloccato dall'assenza di luce","accumulo di antociani","ciclo del gliossilato"],"why":"Tutti i plastidi derivano dal proplastidio e si specializzano per funzione. Gli antociani sono pigmenti vacuolari e il ciclo del gliossilato avviene nei gliossisomi, che non sono plastidi.","real":false},{"id":21045,"topic":"Citologia","type":"match","q":"Associa a ogni modificazione della parete la sostanza o l'esempio corretto.","rows":[{"label":"Lignificazione","ans":"lignina, che evita il collasso dei vasi xilematici"},{"label":"Suberificazione","ans":"suberina, tipica di sughero ed endoderma"},{"label":"Cutinizzazione","ans":"cutina e cere sulla sola faccia esterna"},{"label":"Mineralizzazione","ans":"silice, come nel pelo urticante dell'ortica"},{"label":"Gelificazione","ans":"mucillagini, come nei semi di lino"}],"options":["lignina, che evita il collasso dei vasi xilematici","suberina, tipica di sughero ed endoderma","cutina e cere sulla sola faccia esterna","silice, come nel pelo urticante dell'ortica","mucillagini, come nei semi di lino","tannini e fenoli, come nell'ebano","callosio, che chiude i plasmodesmi"],"why":"Ogni modificazione deposita una sostanza diversa: lignina (rigidità), suberina (impermeabilità, cellule che muoiono), cutina e cere (esterne, cellula vitale), minerali (durezza), pectine mucillaginose (rigonfiamento). Tannini e fenoli sono tipici della pigmentazione.","real":false},{"id":21046,"topic":"Citologia","type":"sort","q":"Trascina ogni struttura nella categoria giusta.","cats":["Solo cellula vegetale","Solo cellula animale","Entrambe"],"items":[{"t":"Plastidi","cat":0},{"t":"Centrioli","cat":1},{"t":"Mitocondri","cat":2},{"t":"Parete cellulare","cat":0},{"t":"Lisosomi","cat":1},{"t":"Ribosomi","cat":2},{"t":"Vacuolo","cat":0},{"t":"Ciglia e flagelli","cat":1},{"t":"Citoscheletro","cat":2}],"why":"Plastidi, parete e vacuolo sono esclusivi dei vegetali; centrioli, ciglia e flagelli e lisosomi degli animali; ribosomi, mitocondri e citoscheletro sono comuni.","real":false},{"id":21047,"topic":"Citologia","type":"sort","q":"Trascina ogni caratteristica nel tipo di cellula corretto.","cats":["Cellula procariota","Cellula eucariota"],"items":[{"t":"DNA circolare libero nel citoplasma","cat":0},{"t":"DNA organizzato in cromatina","cat":1},{"t":"Parete con peptidoglicani","cat":0},{"t":"Parete con cellulosa o chitina","cat":1},{"t":"Divisione per scissione binaria","cat":0},{"t":"Divisione per mitosi o meiosi","cat":1},{"t":"Solo ribosomi 70S","cat":0},{"t":"Reticolo endoplasmatico e Golgi","cat":1}],"why":"Il procariote è privo di nucleo e quasi privo di organelli, con parete a peptidoglicani e scissione binaria. L'eucariote ha nucleo, cromatina, organelli e parete, se presente, di cellulosa o chitina.","real":false},{"id":21048,"topic":"Citologia","type":"sort","q":"Trascina ogni caratteristica nel componente del citoscheletro corrispondente.","cats":["Microtubuli","Microfilamenti di actina","Filamenti intermedi"],"items":[{"t":"Eterodimeri di alfa e beta-tubulina","cat":0},{"t":"Fragmoplasto e fuso mitotico","cat":0},{"t":"Binari per chinesine e dyneine","cat":0},{"t":"Ciclosi insieme alla miosina","cat":1},{"t":"Accrescimento del tubetto pollinico","cat":1},{"t":"Filamenti di 7 nm di F-actina","cat":1},{"t":"Lamina nucleare","cat":2},{"t":"Polimeri di proteine cheratiniche","cat":2}],"why":"I microtubuli (tubulina, 25 nm) formano fuso e fragmoplasto e fanno da binari per chinesine e dyneine; l'actina (7 nm) con la miosina produce ciclosi e crescita del tubetto pollinico; i filamenti intermedi (10 nm) danno stabilità e formano la lamina nucleare.","real":false},{"id":21049,"topic":"Citologia","type":"sort","q":"Trascina ogni caratteristica nello strato di parete corrispondente.","cats":["Lamella mediana","Parete primaria","Parete secondaria"],"items":[{"t":"Comune a due cellule adiacenti","cat":0},{"t":"Solubilizzata dalle pectinasi nella maturazione dei frutti","cat":0},{"t":"Cellulosa a tessitura dispersa","cat":1},{"t":"Consente la distensione sotto la pressione di turgore","cat":1},{"t":"Matrice idratata di xiloglicani e pectine","cat":1},{"t":"Microfibrille parallele in sottostrati S1, S2, S3","cat":2},{"t":"Deposta dopo la fine dell'accrescimento","cat":2}],"why":"La lamella mediana è pectica e condivisa tra cellule adiacenti; la parete primaria è sottile ed estensibile, con cellulosa disordinata in una matrice di emicellulose (xiloglicani) e pectine; la secondaria, deposta a crescita finita, ha microfibrille parallele in tre sottostrati.","real":false},{"id":22000,"topic":"Istologia","type":"mc","q":"Le divisioni pericline delle cellule meristematiche:","opts":["avvengono solo nelle cellule fondatrici della regione centrale dell'apice","formano una parete parallela alla superficie e aumentano il numero di strati sovrapposti","formano una parete perpendicolare alla superficie e accrescono l'organo in estensione superficiale","sono esclusive del meristema apicale della radice (RAM)"],"correct":1,"why":"Nelle divisioni pericline la parete neoformata è parallela alla superficie: aumentano gli strati sovrapposti (accrescimento in spessore, tipico dei cambi). La parete perpendicolare e l'estensione superficiale descrivono invece le divisioni anticline.","real":false},{"id":22001,"topic":"Istologia","type":"mc","q":"Nel meristema apicale, le cellule fondatrici:","opts":["sono situate alla periferia dell'apice e originano l'epidermide","sono situate nella regione centrale, si dividono lentamente e controllano il destino delle cellule circostanti","hanno perso la capacità di dividersi e fungono da riserva","si dividono rapidamente e si differenziano per prime"],"correct":1,"why":"Le cellule fondatrici (stem cells) stanno nella regione centrale del meristema apicale, si dividono lentamente e controllano il destino delle cellule vicine; non sono cellule a divisione rapida né differenziate.","real":false},{"id":22002,"topic":"Istologia","type":"mc","q":"I meristemi intercalari:","opts":["si trovano a livello dei nodi e cooperano alla crescita in lunghezza nei fusti delle monocotiledoni","si trovano agli apici di fusto e radice e determinano la crescita in lunghezza","sono responsabili dell'accrescimento in spessore delle dicotiledoni legnose","derivano da de-differenziamento di cellule adulte e producono il periderma"],"correct":0,"why":"I meristemi intercalari sono meristemi primari posti ai nodi: cooperano alla crescita in lunghezza nei fusti delle monocotiledoni (frumento, mais) e favoriscono la formazione dei rami. Gli apici ospitano SAM e RAM; periderma e spessore dipendono dai meristemi secondari.","real":false},{"id":22003,"topic":"Istologia","type":"mc","q":"Il cambio subero-fellodermico (fellogeno) produce:","opts":["epidermide verso l'esterno e parenchima corticale verso l'interno","sughero verso l'esterno e felloderma verso l'interno","legno verso l'interno e libro verso l'esterno","sughero verso l'interno e felloderma verso l'esterno"],"correct":1,"why":"Il fellogeno forma il periderma: sughero verso l'esterno e felloderma verso l'interno. Legno e libro sono prodotti dal cambio cribro-vascolare.","real":false},{"id":22004,"topic":"Istologia","type":"mc","q":"L'epidermide aerea tipica:","opts":["è priva di cuticola e ha funzione di assorbimento","è pluristratificata, ricca di cloroplasti e con ampi spazi intercellulari","è monostratificata, priva di spazi intercellulari e di cloroplasti, salvo le cellule di guardia","deriva dal dermatogeno del meristema radicale"],"correct":2,"why":"L'epidermide (dal protoderma) è tipicamente monostratificata (pluristratificata solo nelle xerofite), senza spazi intercellulari e priva di cloroplasti, eccetto le cellule di guardia. Assenza di cuticola, assorbimento e origine dal dermatogeno caratterizzano il rizoderma.","real":false},{"id":22005,"topic":"Istologia","type":"mc","q":"Nelle graminacee le cellule di guardia degli stomi sono:","opts":["prive di cloroplasti","collegate da plasmodesmi alle cellule compagne","reniformi","a manubrio con terminazioni bulbose"],"correct":3,"why":"Le graminacee hanno cellule di guardia a manubrio con terminazioni bulbose; quelle reniformi sono di dicotiledoni e monocotiledoni non graminacee. Le cellule di guardia hanno cloroplasti e gli stomi sono privi di plasmodesmi.","real":false},{"id":22006,"topic":"Istologia","type":"mc","q":"Le cellule bulliformi:","opts":["sono cellule ingrossate a pareti sottili che, perdendo turgore, fanno accartocciare la foglia delle Graminee","sono cellule suberificate che formano i punti di permeazione della radice","sono cellule sussidiarie che regolano l'apertura della rima stomatica","sono cellule morte ripiene d'aria che riflettono la radiazione solare"],"correct":0,"why":"Le cellule bulliformi sono gruppi di cellule ingrossate a pareti sottili e turgide, frequenti nelle Graminee di ambiente secco: in carenza idrica perdono turgore e la foglia si accartoccia, riducendo la superficie traspirante. Le cellule morte ripiene d'aria sono i peli di protezione.","real":false},{"id":22007,"topic":"Istologia","type":"mc","q":"La banda di Caspary:","opts":["favorisce la via apoplastica dell'acqua verso il cilindro centrale","è un ispessimento di cellulosa sulle pareti tangenziali delle cellule dell'esoderma","è uno strato di cutina e cere che copre la faccia esterna del rizoderma","è un'impregnazione ad anello di suberina e lignina sulle pareti radiali e trasversali dell'endoderma"],"correct":3,"why":"La banda di Caspary è un anello di suberina e lignina sulle pareti radiali e trasversali delle cellule dell'endoderma; blocca la via apoplastica e costringe le soluzioni a entrare nella via simplastica attraverso la membrana plasmatica.","real":false},{"id":22008,"topic":"Istologia","type":"mc","q":"Le lenticelle:","opts":["sono porzioni di periderma con cellule parenchimatiche arrotondate non suberificate, che consentono gli scambi gassosi","sono stomi modificati presenti nell'epidermide dei fusti in struttura primaria","sono aperture fisse al margine delle foglie che servono alla guttazione","sono canali schizogeni che secernono resina"],"correct":0,"why":"Nelle lenticelle il fellogeno produce un tessuto di riempimento di cellule arrotondate e non suberificate, con ampi spazi intercellulari permeabili ai gas, per la respirazione dei tessuti vivi profondi. Le aperture fisse per la guttazione sono gli idatodi.","real":false},{"id":22009,"topic":"Istologia","type":"mc","q":"Il collenchima:","opts":["è formato da cellule vive con pareti primarie non lignificate, ispessite in modo disomogeneo","comprende fibre e sclereidi","fornisce un sostegno rigido a organi che hanno terminato l'accrescimento","è formato da cellule morte con pareti secondarie uniformemente lignificate"],"correct":0,"why":"Il collenchima ha cellule vive con pareti primarie non lignificate ispessite in modo disomogeneo (pectine ed emicellulose) e dà sostegno plastico a organi giovani. Cellule morte lignificate, sostegno rigido, fibre e sclereidi riguardano lo sclerenchima.","real":false},{"id":22010,"topic":"Istologia","type":"mc","q":"Le brachisclereidi rotondeggianti presenti nella polpa della pera sono:","opts":["cellule di parenchima di riserva","cellule di collenchima angolare","cellule di sclerenchima","fibre tessili riunite in fasci"],"correct":2,"why":"Le sclereidi sono cellule sclerenchimatiche brevi e dure; le brachisclereidi rotondeggianti si trovano nella polpa della pera. Le fibre (canapa, lino) sono invece allungate e riunite in fasci.","real":false},{"id":22011,"topic":"Istologia","type":"mc","q":"Le tracheidi:","opts":["trasportano saccarosio dalle foglie agli organi sink","sono cellule vive associate a cellule albuminose","sono vasi chiusi tipici delle Gimnosperme, con punteggiature areolate munite di toro","sono vasi aperti con pareti trasversali completamente perforate, esclusivi delle Angiosperme"],"correct":2,"why":"Le tracheidi (vasi chiusi, tipiche delle Gimnosperme) sono cellule fusiformi senza pareti terminali perforate, con punteggiature areolate dotate di toro. I vasi aperti perforati sono le trachee; le cellule associate alle albuminose sono le cellule cribrose del floema.","real":false},{"id":22012,"topic":"Istologia","type":"mc","q":"Gli elementi dei tubetti cribrosi maturi:","opts":["hanno pareti trasversali completamente perforate prive di callosio","sono cellule vive con grande nucleo e numerosi ribosomi","sono cellule morte e lignificate","sono cellule vive prive di nucleo, associate a una cellula compagna nucleata"],"correct":3,"why":"I tubetti cribrosi (Angiosperme) sono cellule vive ma degenerate, senza nucleo, vacuolo, ribosomi e Golgi; ciascun elemento è associato a una cellula compagna viva e nucleata. Le aree cribrose hanno pori rivestiti di callosio.","real":false},{"id":22013,"topic":"Istologia","type":"mc","q":"I vasi xilematici anulati:","opts":["sono i più giovani e primitivi, estensibili, tipici di zone in attiva crescita per distensione","presentano pareti lignificate con fessure oblunghe","hanno la massima estensione della lignificazione e numerose punteggiature","non sono estensibili e si trovano in zone con accrescimento completato"],"correct":0,"why":"Gli anulati, con ispessimenti ad anello, sono i più giovani e primitivi ed estensibili. Fessure oblunghe e non estensibilità descrivono gli scalariformi; la massima lignificazione i punteggiati.","real":false},{"id":22014,"topic":"Istologia","type":"mc","q":"Un fascio cribrovascolare collaterale aperto:","opts":["ha floema e xilema separati dal cambio ed è tipico dei fusti di dicotiledoni e gimnosperme","ha lo xilema che circonda completamente il floema","ha una seconda zona di floema interna allo xilema","ha floema e xilema a contatto ed è tipico dei fusti delle monocotiledoni"],"correct":0,"why":"I collaterali aperti hanno xilema e floema separati dal cambio (fusti di dicotiledoni e gimnosperme); i chiusi, a contatto, sono delle monocotiledoni. Floema interno = bicollaterale; xilema attorno al floema = concentrico perixilematico.","real":false},{"id":22015,"topic":"Istologia","type":"mc","q":"Le tasche oleifere della buccia degli agrumi sono un esempio di secrezione:","opts":["intracellulare in idioblasti","merocrina (schizogena)","olocrina (lisigena)","tramite peli ghiandolari"],"correct":2,"why":"Nelle tasche lisigene degli agrumi le cellule secernenti degenerano e si dissolvono liberando gli oli essenziali: secrezione olocrina. Nella merocrina (es. canali resiniferi) le cellule restano vive e integre.","real":false},{"id":22016,"topic":"Istologia","type":"mc","q":"Gli idatodi:","opts":["sono stomi regolabili che controllano la traspirazione","sono porzioni di periderma permeabili ai gas","sono aperture fisse al margine delle foglie, funzionali alla guttazione","sono ghiandole che eliminano NaCl nelle piante alofile"],"correct":2,"why":"Gli idatodi sono aperture fisse e non regolabili al margine fogliare, dove terminano le nervature, in contatto apoplastico con lo xilema: servono alla guttazione. L'eliminazione di NaCl spetta alle ghiandole del sale; il periderma permeabile ai gas sono le lenticelle.","real":false},{"id":22017,"topic":"Istologia","type":"multi","q":"Seleziona le caratteristiche delle cellule dei meristemi primari:","opts":["nucleo grande e citoplasma denso","abbondanti sostanze di riserva","cellule piccole e isodiametriche","vacuoli assenti o piccoli (provacuoli)","pareti secondarie lignificate","ampi spazi intercellulari"],"correct":[0,2,3],"why":"Le cellule meristematiche primarie sono piccole, isodiametriche, senza spazi intercellulari, con citoplasma denso, nucleo grande e provacuoli; hanno pareti sottili celluloso-pectiche e sono quasi prive di riserve.","real":false},{"id":22018,"topic":"Istologia","type":"multi","q":"Quali tra questi sono tessuti definitivi complessi (formati da più tipi cellulari)?","opts":["tessuti meccanici","tessuti tegumentali","tessuti parenchimatici","tessuti secretori","tessuti vascolari"],"correct":[3,4],"why":"Per struttura i tessuti definitivi si dividono in semplici (tegumentali, parenchimatici, meccanici) e complessi (vascolari e secretori).","real":false},{"id":22019,"topic":"Istologia","type":"multi","q":"Seleziona le caratteristiche del rizoderma:","opts":["le sue cellule contengono la banda di Caspary","è monostratificato","è rivestito da una spessa cuticola","presenta tricoblasti che formano i peli radicali","è privo di stomi"],"correct":[1,3,4],"why":"Il rizoderma è monostratificato, con parete pectocellulosica sottile, privo di cuticola e stomi; i tricoblasti formano i peli radicali. La banda di Caspary è dell'endoderma.","real":false},{"id":22020,"topic":"Istologia","type":"multi","q":"Quali delle seguenti sono funzioni dei tricomi (peli)?","opts":["conduzione della linfa elaborata","difesa dagli erbivori","produzione di sughero","funzione aggrappante","protezione dall'eccessiva traspirazione"],"correct":[1,3,4],"why":"I tricomi proteggono da traspirazione eccessiva e radiazioni, difendono dagli erbivori, possono essere aggrappanti e mediano la relazione con i pronubi. Il trasporto di linfa elaborata spetta al floema, il sughero al fellogeno.","real":false},{"id":22021,"topic":"Istologia","type":"multi","q":"Seleziona le piante con laticiferi articolati (catene di cellule fuse per dissoluzione delle pareti trasversali):","opts":["papavero da oppio","tarassaco","luppolo","oleandro","Euphorbia"],"correct":[0,1],"why":"Tarassaco e papavero da oppio hanno laticiferi articolati; Euphorbia e oleandro hanno laticiferi non articolati (singole cellule giganti plurinucleate). Il luppolo è citato per i peli ghiandolari.","real":false},{"id":22022,"topic":"Istologia","type":"cloze","q":"Completa trascinando le parole nei riquadri.","text":"Il cambio cribro-vascolare ha attività {0}: produce {1} verso l'interno e {2} verso l'esterno.","answers":["dipleurica","xilema secondario","floema secondario"],"bank":["sughero","felloderma","monopleurica"],"why":"Il cambio cribro-vascolare è dipleurico: forma legno (xilema secondario) verso l'interno e libro (floema secondario) verso l'esterno; sughero e felloderma derivano dal fellogeno.","real":false},{"id":22023,"topic":"Istologia","type":"cloze","q":"Completa trascinando le parole nei riquadri.","text":"Nella radice, le cellule del rizoderma che si estroflettono formando i peli radicali sono dette {0}, mentre le cellule appiattite prive di peli sono dette {1}. Quando i peli degenerano, la protezione passa all'{2}, strato più esterno del parenchima corticale che spesso {3}.","answers":["tricoblasti","atricoblasti","esoderma","suberifica"],"bank":["endoderma","meristemoidi","lignifica","cutinizza"],"why":"Tricoblasti = cellule pilifere; atricoblasti = cellule senza peli. L'esoderma deriva dallo strato più esterno del parenchima corticale che spesso suberifica; l'endoderma è lo strato interno della corteccia.","real":false},{"id":22024,"topic":"Istologia","type":"cloze","q":"Completa trascinando le parole nei riquadri.","text":"La cuticola è formata da {0} e {1}, apposte esternamente alla parete delle cellule {2}; copre solo la faccia esterna, così la cellula resta {3}.","answers":["cutina","cere","epidermiche","vitale"],"bank":["suberina","lignina","morta","rizodermiche"],"why":"La cuticola è uno strato idrofobico di cutina e cere sulla faccia esterna delle cellule epidermiche, che restano vitali ricevendo acqua dalle cellule vicine. Suberina e lignina impregnano sughero e banda di Caspary; il rizoderma è privo di cuticola.","free":[[0,1]],"real":false},{"id":22025,"topic":"Istologia","type":"cloze","q":"Completa trascinando le parole nei riquadri.","text":"Il parenchima clorofilliano a {0} ha cellule cilindriche allungate perpendicolarmente alla superficie fogliare, mentre quello {1} ha cellule lasse con ampi spazi intercellulari. Il parenchima {2} è tipico delle piante succulente, l'{3} delle idrofite.","answers":["palizzata","lacunoso","acquifero","aerenchima"],"bank":["amilifero","collenchima","sclerenchima"],"why":"Il clorenchima si divide in palizzata e lacunoso; il parenchima acquifero è di succulente e alofite, l'aerenchima (aerifero) delle idrofite. Il parenchima amilifero è di riserva.","real":false},{"id":22026,"topic":"Istologia","type":"cloze","q":"Completa trascinando le parole nei riquadri.","text":"Il {0} trasporta la linfa grezza in senso ascendente ed è formato da cellule {1}; il {2} trasporta la linfa elaborata, principalmente {3}.","answers":["xilema","morte","floema","saccarosio"],"bank":["vive","cellulosa","amido"],"why":"Lo xilema (legno) porta acqua e sali dalle radici alle foglie con cellule morte lignificate; il floema (libro) trasporta gli assimilati, soprattutto saccarosio, con cellule vive.","real":false},{"id":22027,"topic":"Istologia","type":"cloze","q":"Completa trascinando le parole nei riquadri.","text":"Nelle punteggiature areolate l'ispessimento centrale detto {0} funziona da valvola contro {1}; i vasi possono essere sigillati anche dalle {2}, estroflessioni delle cellule {3} adiacenti al legno.","answers":["toro","l'embolia","tille","parenchimatiche"],"bank":["callosio","la guttazione","sclerenchimatiche","lenticelle"],"why":"Il toro occlude la punteggiatura se il vaso vicino è pieno d'aria, bloccando l'embolia. Le tille sono estroflessioni di cellule parenchimatiche che entrano nel vaso attraverso le punteggiature sigillandolo.","real":false},{"id":22028,"topic":"Istologia","type":"cloze","q":"Completa trascinando le parole nei riquadri.","text":"Gli spazi intercellulari di origine {0} si formano per allontanamento delle cellule con digestione della lamella mediana; quelli di origine {1} per digestione di intere cellule, comprese le pareti.","answers":["schizogena","lisigena"],"bank":[["anticlina"],["periclina"]],"why":"Schizogeno: le cellule si separano digerendo la lamella mediana; lisigeno: alcune cellule vengono digerite interamente.","groups":[0,1],"real":false},{"id":22029,"topic":"Istologia","type":"match","q":"Associa a ogni tipo di collenchima la sua caratteristica.","rows":[{"label":"Angolare","ans":"ispessimenti agli angoli cellulari"},{"label":"Lamellare","ans":"ispessimenti sulle pareti tangenziali"},{"label":"Annulare","ans":"lume cellulare circolare"}],"options":["ispessimenti agli angoli cellulari","ispessimenti sulle pareti tangenziali","lume cellulare circolare","pareti secondarie uniformemente lignificate"],"why":"Il collenchima angolare è ispessito agli angoli, il lamellare sulle pareti tangenziali, l'annulare ha lume circolare. Pareti secondarie uniformemente lignificate sono tipiche dello sclerenchima.","real":false},{"id":22030,"topic":"Istologia","type":"match","q":"Associa a ogni sclereide la sua localizzazione tipica.","rows":[{"label":"Brachisclereidi","ans":"polpa della pera"},{"label":"Astrosclereidi","ans":"piante acquatiche"},{"label":"Osteosclereidi","ans":"tegumenti dei semi"}],"options":["polpa della pera","piante acquatiche","tegumenti dei semi","fusti di canapa e lino"],"why":"Brachisclereidi rotondeggianti nella polpa di pera, astrosclereidi ramificate nelle piante acquatiche, osteosclereidi a forma di osso nei tegumenti dei semi. Canapa e lino sono esempi di fibre sclerenchimatiche.","real":false},{"id":22031,"topic":"Istologia","type":"match","q":"Associa a ogni tipo di fascio cribrovascolare un esempio.","rows":[{"label":"Bicollaterale","ans":"fusti di Cucurbitaceae e Solanaceae"},{"label":"Concentrico perixilematico","ans":"rizomi di monocotiledoni"},{"label":"Concentrico perifloematico","ans":"fusti di pteridofite"},{"label":"Alterno (radiale)","ans":"radici"},{"label":"Collaterale chiuso","ans":"fusti di monocotiledoni"}],"options":["fusti di Cucurbitaceae e Solanaceae","rizomi di monocotiledoni","fusti di pteridofite","radici","fusti di monocotiledoni","fusti di gimnosperme"],"why":"Bicollaterali in Cucurbitaceae e Solanaceae; perixilematici nei rizomi di monocotiledoni; perifloematici nei fusti di pteridofite; alterni nelle radici; collaterali chiusi nei fusti di monocotiledoni. I fusti di gimnosperme hanno fasci collaterali aperti.","real":false},{"id":22032,"topic":"Istologia","type":"sort","q":"Trascina ogni caratteristica nel tessuto giusto.","cats":["Collenchima","Sclerenchima"],"items":[{"t":"cellule vive ad alto contenuto idrico","cat":0},{"t":"pareti primarie non lignificate","cat":0},{"t":"sostegno per organi giovani in crescita","cat":0},{"t":"cellule morte a maturità","cat":1},{"t":"pareti secondarie uniformemente lignificate","cat":1},{"t":"fibre di canapa e lino","cat":1},{"t":"sclereidi","cat":1}],"why":"Il collenchima è vivo, con pareti primarie non lignificate ispessite in modo disomogeneo, adatto a organi giovani; lo sclerenchima è morto, con pareti secondarie lignificate e comprende fibre e sclereidi.","real":false},{"id":22033,"topic":"Istologia","type":"sort","q":"Trascina ogni elemento nel tessuto di conduzione a cui appartiene.","cats":["Xilema","Floema"],"items":[{"t":"tracheidi","cat":0},{"t":"trachee","cat":0},{"t":"toro","cat":0},{"t":"tille","cat":0},{"t":"cellule albuminose","cat":1},{"t":"tubetti cribrosi","cat":1},{"t":"callosio","cat":1},{"t":"cellula compagna","cat":1}],"why":"Tracheidi, trachee, punteggiature con toro e tille riguardano lo xilema; cellule cribrose con albuminose, tubetti cribrosi, aree cribrose con callosio e cellule compagne riguardano il floema.","real":false},{"id":22034,"topic":"Istologia","type":"sort","q":"Tipo di secrezione: trascina ogni esempio nella categoria giusta.","cats":["Intracellulare","Extracellulare olocrina (lisigena)","Extracellulare merocrina (schizogena)"],"items":[{"t":"idioblasti oleiferi della cannella","cat":0},{"t":"cellule a tannini","cat":0},{"t":"cellule a mucillagine","cat":0},{"t":"tasche della buccia degli agrumi","cat":1},{"t":"canali resiniferi delle conifere","cat":2}],"why":"Negli idioblasti (oleiferi, a mucillagine, a tannini) il secreto resta nel protoplasto. Le tasche degli agrumi si formano per dissoluzione delle cellule (olocrina); i canali resiniferi hanno un epitelio vivo che secerne in una cavità schizogena (merocrina).","real":false},{"id":23000,"topic":"Organografia","type":"mc","q":"L'eustele delle Dicotiledoni è caratterizzata da:","opts":["fasci collaterali chiusi numerosi, sparsi in tutto il parenchima fondamentale","fasci collaterali aperti distribuiti senza distinzione fra corteccia e midollo","fasci collaterali aperti disposti in un unico anello che separa corteccia e midollo","arche xilematiche e floematiche alterne disposte a raggiera"],"correct":2,"why":"Nell'eustele (Dicotiledoni e Gimnosperme) i fasci collaterali aperti formano un anello regolare fra corteccia e midollo, separati da raggi midollari. I fasci chiusi sparsi sono dell'atassostele delle Monocotiledoni; le arche alterne a raggiera sono l'actinostele della radice.","real":false},{"id":23001,"topic":"Organografia","type":"mc","q":"Nell'atassostele delle Monocotiledoni, l'apparente disordine dei fasci dipende:","opts":["dalla diversa profondità a cui penetrano i fasci fogliari","dalla differenziazione centripeta dello xilema","dall'assenza di endoderma nel cilindro centrale del fusto","dalla formazione del cambio interfasciale nei raggi midollari"],"correct":0,"why":"Il disordine dei fasci dell'atassostele è solo apparente: dipende dalla diversa profondità a cui penetrano nel fusto i fasci provenienti dalle foglie. Il cambio interfasciale riguarda l'accrescimento secondario delle Dicotiledoni, assente nelle Monocotiledoni.","real":false},{"id":23002,"topic":"Organografia","type":"mc","q":"Il durame (duramen):","opts":["è il legno più giovane ed esterno, chiaro, con vasi attivi nella conduzione","è l'insieme dei tessuti morti esterni all'ultimo periderma","è il legno più vecchio e centrale, non più conduttore, con vasi occlusi da tille","è il legno tardivo di ogni cerchia, con trachee strette e molte fibre"],"correct":2,"why":"Il durame è il legno centrale e più scuro, con vasi occlusi da tille e pareti impregnate di tannini e resine, con funzione di sostegno. Il legno giovane e conduttore è l'alburno; i tessuti morti esterni all'ultimo periderma formano il ritidoma.","real":false},{"id":23003,"topic":"Organografia","type":"mc","q":"Il ritidoma:","opts":["è l'insieme di sughero, fellogeno e felloderma","è l'insieme dei tessuti morti esterni all'ultimo periderma","è l'insieme dei tessuti morti interni all'ultimo periderma del fusto secondario","è il parenchima prodotto verso l'interno dal fellogeno"],"correct":1,"why":"Il ritidoma (scorza) comprende i tessuti morti esterni all'ultimo periderma, che isolati dal sughero disseccano e desquamano. Sughero, fellogeno e felloderma formano il periderma; il felloderma è il parenchima prodotto verso l'interno dal fellogeno.","real":false},{"id":23004,"topic":"Organografia","type":"mc","q":"Il fellogeno del fusto può differenziarsi:","opts":["sotto l'epidermide, nella corteccia o nel libro, ma mai più internamente del libro","esclusivamente dal periciclo, sia nel fusto sia nella radice","anche nel legno, quando il periderma precedente si è desquamato","solo sotto l'epidermide, e dura per tutta la vita della pianta"],"correct":0,"why":"Il fellogeno si differenzia da cellule già differenziate sotto l'epidermide, nella corteccia o nel libro, mai più internamente del libro; dura in genere un solo anno e se ne riforma uno più interno.","real":false},{"id":23005,"topic":"Organografia","type":"mc","q":"Il centro quiescente dell'apice radicale:","opts":["è formato dal caliptrogeno e produce le cellule della cuffia","contiene gli statoliti che percepiscono la direzione della gravità","è l'istogeno che origina il cilindro centrale della radice","è un gruppo di cellule a mitosi molto rallentata che funge da serbatoio di cellule meristematiche"],"correct":3,"why":"Il centro quiescente ha attività mitotica molto rallentata, funge da riserva di cellule meristematiche e inibisce il differenziamento delle iniziali circostanti. Gli statoliti sono nella columella della cuffia; il cilindro centrale deriva dal pleroma.","real":false},{"id":23006,"topic":"Organografia","type":"mc","q":"Nel gravitropismo positivo della radice:","opts":["l'auxina si accumula sul lato inferiore, che si allunga più di quello superiore","gli statoliti della columella redistribuiscono l'auxina verso il lato inferiore, il cui allungamento viene inibito","l'auxina si accumula sul lato superiore e ne inibisce l'allungamento","gli statoliti del centro quiescente stimolano l'allungamento del lato superiore"],"correct":1,"why":"Lo spostamento degli statoliti (granuli di amido) della columella porta l'auxina al lato inferiore; nella radice l'auxina in eccesso inibisce l'allungamento, quindi il lato inferiore cresce meno e la radice si piega verso il basso.","real":false},{"id":23007,"topic":"Organografia","type":"mc","q":"Qual è la prova sicura per distinguere una radice da un fusto in struttura secondaria?","opts":["la presenza di raggi midollari più stretti","la presenza, al centro, del protoxilema esarco della struttura primaria","la presenza di cerchie annuali ben visibili nel legno","la presenza di un periderma con lenticelle"],"correct":1,"why":"Al centro della radice resta il protoxilema esarco della struttura primaria, mentre nel fusto è endarco. Nella radice inoltre le cerchie annuali sono meno visibili e i raggi più larghi; il periderma con lenticelle si forma in entrambi gli organi.","real":false},{"id":23008,"topic":"Organografia","type":"mc","q":"I peli radicali:","opts":["originano dal periciclo e hanno quindi origine endogena","sono rivestiti da una spessa cuticola che limita la perdita d'acqua","sono estroflessioni unicellulari del rizoderma, a vita brevissima","sono estroflessioni pluricellulari dell'esoderma, persistenti"],"correct":2,"why":"I peli radicali sono estroflessioni unicellulari del rizoderma (privo di cuticola), a vita brevissima, che aumentano la superficie assorbente. Dal periciclo originano invece le radici laterali; l'esoderma sostituisce il rizoderma dopo la caduta dei peli.","real":false},{"id":23009,"topic":"Organografia","type":"mc","q":"Le radici laterali originano:","opts":["dal rizoderma, e hanno quindi origine esogena","dal periciclo, e hanno quindi origine endogena","dall'endoderma, e hanno quindi origine endogena","dalle gemme ascellari, e hanno quindi origine esogena"],"correct":1,"why":"Le radici laterali nascono dal periciclo (strato rizogeno), subito interno all'endoderma: sono endogene e attraversano corteccia ed epidermide per emergere, a differenza dei rami del fusto, che sono esogeni.","real":false},{"id":23010,"topic":"Organografia","type":"mc","q":"L'apparato radicale omorrizico:","opts":["è tipico delle Monocotiledoni: la radice embrionale degenera ed è sostituita da radici avventizie","ha una radice principale che supera sempre le laterali per lunghezza e potenza","ha la radice principale poco sviluppata e le laterali superficiali","ha radici laterali della stessa potenza della principale, che permane"],"correct":0,"why":"Nell'apparato omorrizico la radice embrionale degenera precocemente ed è sostituita da numerose radici avventizie fascicolate dal colletto. Gli altri tipi (a fittone, fascicolato, a disco) sono allorrizici, cioè la radice embrionale permane.","real":false},{"id":23011,"topic":"Organografia","type":"mc","q":"La banda del Caspary:","opts":["è un deposito di suberina sulle pareti trasversali e radiali dell'endoderma che interrompe la via apoplastica","è un deposito di suberina sulle pareti tangenziali dell'esoderma che interrompe la via simplastica","è un ispessimento di cellulosa dell'endoderma che favorisce la via apoplastica","è un deposito di lignina sulle pareti del periciclo che interrompe la via simplastica"],"correct":0,"why":"La banda del Caspary è suberina deposta sulle pareti trasversali e radiali dell'endoderma: blocca la via apoplastica e obbliga le soluzioni a passare per via simplastica, permettendo alla pianta di filtrare gli ioni.","real":false},{"id":23012,"topic":"Organografia","type":"mc","q":"Nella foglia bifacciale il parenchima a palizzata:","opts":["è presente verso entrambe le facce, poco distinguibile dal lacunoso mediano","si trova sotto l'epidermide inferiore, con cellule colonnari ricche di cloroplasti","si trova verso la pagina inferiore, con ampi spazi intercellulari e camere sottostomatiche","si trova sotto l'epidermide superiore, con cellule colonnari ricche di cloroplasti"],"correct":3,"why":"Nella foglia dorsoventrale la palizzata è sotto l'epidermide superiore ed è specializzata nella fotosintesi; verso la pagina inferiore c'è il lacunoso con le camere sottostomatiche. La palizzata verso entrambe le facce è tipica della foglia isolaterale.","real":false},{"id":23013,"topic":"Organografia","type":"mc","q":"Le cellule bulliformi:","opts":["sono grandi cellule epidermiche delle graminacee che determinano l'arrotolamento della lamina","sono cellule di guardia che regolano l'apertura degli stomi delle graminacee","sono cellule del mesofillo delle Dicotiledoni che accumulano acqua","sono cellule della guaina del fascio che coadiuvano il trasporto"],"correct":0,"why":"Le cellule bulliformi sono grandi cellule epidermiche delle Monocotiledoni (graminacee) che, variando il turgore, fanno arrotolare e dispiegare la lamina. Non sono cellule di guardia né cellule del mesofillo delle Dicotiledoni.","real":false},{"id":23014,"topic":"Organografia","type":"mc","q":"Quale carattere è tipico delle foglie xeromorfe?","opts":["vasi conduttori ridotti, con più floema che xilema","stomi presenti solo sulla pagina superiore","stomi infossati in cripte stomatiche protette da tricomi","cuticola sottile e mesofillo con parenchimi aeriferi"],"correct":2,"why":"Le foglie xeromorfe hanno cuticola spessa, epidermidi cutinizzate, stomi in cripte con tricomi e spesso ipoderma sclerenchimatico. Cuticola sottile, parenchimi aeriferi e più floema che xilema sono caratteri delle idrofite; gli stomi superiori delle foglie galleggianti.","real":false},{"id":23015,"topic":"Organografia","type":"mc","q":"La foglia unifacciale:","opts":["è la foglia aghiforme delle conifere con fasci in posizione centrale","deriva per incurvamento e saldatura dei margini del lembo, come in iris","ha la superficie esterna coincidente con la pagina superiore","è tipica delle Dicotiledoni a portamento plagiotropo"],"correct":1,"why":"La foglia unifacciale, quasi esclusiva delle Monocotiledoni, nasce dall'incurvamento e saldatura dei margini del lembo; la superficie esterna coincide con la pagina inferiore (es. iris, erba cipollina). La foglia aghiforme con fasci centrali è la centrica delle Gimnosperme.","real":false},{"id":23016,"topic":"Organografia","type":"mc","q":"L'abscissione fogliare è correlata a:","opts":["un aumento della produzione di auxina nella foglia senescente","un accumulo di citochinine nella zona di abscissione","una diminuita produzione di etilene e un aumento di gibberelline","una diminuita produzione di auxina nella foglia, con intervento dell'etilene"],"correct":3,"why":"Con la senescenza la foglia produce meno auxina e aumenta l'etilene, che induce nella zona di abscissione la secrezione di cellulasi e pectinasi; la cicatrice viene poi sigillata da uno strato di sughero.","real":false},{"id":23017,"topic":"Organografia","type":"mc","q":"Le stipole:","opts":["sono rigonfiamenti basali del picciolo responsabili delle nastie","sono espansioni membranose della base fogliare che abbracciano il fusto","sono appendici alla base del picciolo che possono saldarsi in ocrea","sono foglie con sviluppo arrestato che proteggono le gemme"],"correct":2,"why":"Le stipole sono appendici alla base del picciolo: possono essere fotosintetizzanti (Pisum), saldarsi in ocrea (Polygonaceae) o diventare viticci o spine. La guaina abbraccia il fusto, il pulvino causa le nastie, le perule proteggono le gemme.","real":false},{"id":23018,"topic":"Organografia","type":"mc","q":"La ramificazione monopodiale:","opts":["vede l'asse principale accrescersi più dei rami secondari, con chioma conica (es. Abies)","vede la gemma apicale cessare di funzionare, con chioma globulare (es. Quercus)","vede una sola gemma laterale formare un falso asse continuo","vede svilupparsi simmetricamente due gemme laterali che formano rami a Y"],"correct":0,"why":"Nella ramificazione monopodiale la gemma apicale mantiene la dominanza e la chioma è conica o piramidale. La perdita della gemma apicale con chioma globulare è la simpodiale, che si divide in dicasio (rami a Y) e monocasio (falso asse).","real":false},{"id":23019,"topic":"Organografia","type":"mc","q":"I bulbi sono:","opts":["radici laterali tuberizzate con parenchima corticale di riserva","fusti carnosi di riserva con foglie piccole e sottili","fusti sotterranei ingrossati che portano solo gemme e non radici","gemme sotterranee con apice vegetativo avvolto da catafilli che svolgono la riserva"],"correct":3,"why":"Nel bulbo (es. Allium cepa) la riserva è svolta dalle foglie trasformate (catafilli) attorno all'apice. Il fusto sotterraneo che porta solo gemme è il tubero; il fusto carnoso con foglie sottili è il bulbo-tubero (Crocus sativus).","real":false},{"id":23020,"topic":"Organografia","type":"mc","q":"I fattori Nod:","opts":["sono proteine della membrana peribatteroide di origine vegetale","sono lipochitooligosaccaridi prodotti dal batterio in risposta ai flavonoidi della pianta","sono flavonoidi secreti dalla radice che inducono i geni nod nei rizobi","sono subunità della nitrogenasi che riducono l'azoto atmosferico"],"correct":1,"why":"La sequenza è: flavonoidi (pianta) -> geni nod -> fattori Nod (batterio), lipochitooligosaccaridi che innescano il primordio nodulare e l'incurvamento del pelo radicale. La nitrogenasi è codificata dai geni nifHDK.","real":false},{"id":23021,"topic":"Organografia","type":"mc","q":"I noduli determinati (globosi):","opts":["hanno un meristema apicale persistente, come in Medicago sativa","mostrano in sezione longitudinale zone di sviluppo dalla I alla III","derivano da un meristema sferico transitorio, come in Glycine max","contengono simbiosomi con un singolo batteroide ingrossato fino a 30 volte"],"correct":2,"why":"I noduli determinati (Glycine max, Phaseolus vulgaris) derivano da un meristema sferico transitorio e hanno simbiosomi con più batteroidi a bastoncello. Meristema persistente, zone I-III e singolo batteroide ingrossato caratterizzano i noduli indeterminati (Medicago, Pisum).","real":false},{"id":23022,"topic":"Organografia","type":"mc","q":"Nelle endomicorrize (vescicolo-arbuscolari):","opts":["il fungo rompe la membrana plasmatica e digerisce il citoplasma","il fungo forma un manto attorno alla radice e penetra solo fra le cellule","il fungo è quasi sempre un Basidiomycota","il fungo penetra nelle cellule corticali senza rompere la membrana plasmatica"],"correct":3,"why":"Nelle endomicorrize (Zygomycota) le ife entrano nelle cellule corticali e la membrana plasmatica si invagina attorno a esse senza rompersi. Il manto (micoclena) con penetrazione solo intercellulare e i Basidiomycota caratterizzano le ectomicorrize.","real":false},{"id":23023,"topic":"Organografia","type":"mc","q":"L'attivatore NifA dei rizobi:","opts":["codifica le subunità strutturali della nitrogenasi","è espresso e attivo solo a bassa tensione di ossigeno (microaerobiosi)","è necessario per assimilare l'NH4+ tramite la via GS/GOGAT","è attivo solo in presenza di elevate concentrazioni di NH4+"],"correct":1,"why":"NifA attiva la trascrizione dei geni nif solo in microaerobiosi ed è repressa dall'NH4+. Le subunità della nitrogenasi sono codificate da nifHDK; l'assimilazione GS/GOGAT nei batteroidi è invece quasi spenta.","real":false},{"id":23024,"topic":"Organografia","type":"mc","q":"Nella simbiosi rizobi-leguminose, l'ammonio prodotto nei batteroidi:","opts":["viene usato soprattutto per la crescita e la divisione dei batteroidi","viene trasportato come ureidi nelle leguminose temperate","viene assimilato dal batterio tramite la GDH assimilatoria","viene escreto verso la pianta anziché essere assimilato per la crescita batterica"],"correct":3,"why":"Nei rizobi fissazione e assimilazione sono disaccoppiate: l'NH4+ è ceduto alla pianta, a differenza dei diazotrofi liberi come Klebsiella. La GDH assimilatoria è assente nei rizobi e l'azoto viaggia come glutammina nelle leguminose temperate, come ureidi in quelle tropicali.","real":false},{"id":23025,"topic":"Organografia","type":"multi","q":"Seleziona i caratteri della struttura primaria della radice:","opts":["protoxilema endarco","actinostele con arche xilematiche e floematiche alterne","protoxilema esarco","fasci collaterali aperti disposti in un anello","rizoderma privo di cuticola","endoderma con banda del Caspary"],"correct":[1,2,4,5],"why":"Nella radice primaria il rizoderma non ha cuticola, il cilindro centrale è delimitato dall'endoderma e l'actinostele ha arche alterne con xilema centripeto (esarco). L'anello di fasci collaterali e il protoxilema endarco sono del fusto.","real":false},{"id":23026,"topic":"Organografia","type":"multi","q":"Quali sono funzioni della cuffia (caliptra)?","opts":["lubrificazione tramite mucigel polisaccaridico","percezione della gravità tramite statoliti","origine delle radici laterali","protezione del meristema apicale","assorbimento di acqua e sali minerali"],"correct":[0,1,3],"why":"La cuffia protegge il meristema, lubrifica con il mucigel e, tramite gli statoliti della columella, media il gravitropismo. L'assorbimento avviene nella zona pilifera; le radici laterali nascono dal periciclo.","real":false},{"id":23027,"topic":"Organografia","type":"multi","q":"Seleziona le strutture di origine fogliare (fillomi):","opts":["spata delle Araceae","cladodi di Ruscus aculeatus","cirri di Pisum sativum","perule delle gemme","catafilli dei bulbi","spine di Gleditsia triacanthos"],"correct":[0,2,3,4],"why":"Catafilli, perule, cirri di Pisum (foglioline trasformate) e ipsofilli come la spata delle Araceae derivano da foglie. I cladodi di Ruscus e le spine di Gleditsia sono invece rami trasformati.","real":false},{"id":23028,"topic":"Organografia","type":"multi","q":"Quali caratteri presentano le foglie di idrofite sommerse?","opts":["assenza di stomi","stomi infossati in cripte stomatiche","parenchimi aeriferi con grandi spazi intercellulari","cuticola sottile","vasi conduttori ridotti, con più floema che xilema","ipoderma meccanico sclerenchimatico"],"correct":[0,2,3,4],"why":"Le idrofite hanno cuticola sottile, mesofillo aerifero, vasi ridotti con più floema che xilema e, se sommerse, nessuno stoma. Ipoderma sclerenchimatico e cripte stomatiche sono adattamenti xeromorfi.","real":false},{"id":23029,"topic":"Organografia","type":"multi","q":"Quali caratteri del legno indicano una radice piuttosto che un fusto?","opts":["vasi di diametro maggiore","raggi midollari più larghi","legno più ricco di vasi e più povero di fibre","protoxilema endarco al centro","cerchie annuali più visibili"],"correct":[0,1,2],"why":"Il legno di radice ha più vasi, più larghi, meno fibre e raggi più larghi, con cerchie meno visibili. Al centro la radice mostra protoxilema esarco, mentre quello endarco è tipico del fusto.","real":false},{"id":23030,"topic":"Organografia","type":"multi","q":"Quali generi di piante carnivore hanno trappole adesive?","opts":["Pinguicula","Sarracenia","Utricularia","Nepenthes","Dionaea","Drosera"],"correct":[0,5],"why":"Drosera e Pinguicula hanno trappole adesive con ghiandole che secernono sostanze collose ed enzimi, le più ancestrali. Dionaea ha trappole a scatto, Nepenthes e Sarracenia ad ascidio, Utricularia ad aspirazione.","real":false},{"id":23031,"topic":"Organografia","type":"multi","q":"Quali affermazioni sulla simbiosi rizobi-leguminose sono corrette?","opts":["l'NH4+ esterno inibisce la formazione dei filamenti di infezione","nei batteroidi l'assimilazione dell'NH4+ tramite GS/GOGAT è molto attiva","le radici secernono flavonoidi che inducono i geni nod","i batteri vengono rilasciati nelle cellule per endocitosi e diventano batteroidi","i rizobi liberi nel suolo fissano attivamente l'azoto"],"correct":[0,2,3],"why":"Flavonoidi -> geni nod -> fattori Nod -> filamenti di infezione -> endocitosi -> batteroidi; l'N combinato esterno inibisce le prime tappe. I batteri liberi nel suolo non fissano azoto e nei batteroidi l'assimilazione dell'NH4+ è quasi spenta.","real":false},{"id":23032,"topic":"Organografia","type":"multi","q":"Seleziona i tessuti prodotti dal cambio cribro-vascolare:","opts":["sughero","felloderma","raggi parenchimatici","floema secondario (libro)","xilema secondario (legno)"],"correct":[2,3,4],"why":"Il cambio cribro-vascolare, ad attività dipleurica, produce legno verso l'interno e libro verso l'esterno, oltre ai raggi (dalle iniziali dei raggi). Sughero e felloderma sono prodotti dal fellogeno.","real":false},{"id":23033,"topic":"Organografia","type":"cloze","q":"Completa trascinando le parole nei riquadri.","text":"Un fascio cribro-vascolare si dice {0} quando tra metafloema e metaxilema restano cellule meristematiche; si dice {1} quando non rimangono meristemi, come nelle {2}.","answers":["aperto","chiuso","Monocotiledoni"],"bank":["collaterale","Dicotiledoni","Gimnosperme"],"why":"Il fascio aperto conserva il cambio (Gimnosperme e Dicotiledoni) ed è l'unico che permette l'accrescimento secondario; nel fascio chiuso delle Monocotiledoni il procambio è consumato.","real":false},{"id":23034,"topic":"Organografia","type":"cloze","q":"Completa trascinando le parole nei riquadri.","text":"Il {0}, organizzato in cordoni, differenzia i fasci cribro-vascolari, mentre il {1} origina l'epidermide. Nel fascio il primo elemento a differenziarsi, all'esterno, è il {2}; internamente segue il {3}; poi si formano metafloema e metaxilema.","answers":["procambio","protoderma","protofloema","protoxilema"],"bank":["meristema fondamentale","metaxilema","metafloema"],"why":"Il procambio differenzia i fasci, il protoderma origina l'epidermide e il meristema fondamentale i parenchimi. Il differenziamento procede dall'esterno all'interno: protofloema, protoxilema, poi metafloema e metaxilema.","real":false},{"id":23035,"topic":"Organografia","type":"cloze","q":"Completa trascinando le parole nei riquadri.","text":"Nell'apice caulinare delle Angiosperme la {0} si divide solo anticlinalmente: lo strato L1 origina l'{1} e L2 la corteccia. Il {2} (L3) si divide anche periclinalmente e origina i tessuti della stele.","answers":["tunica","epidermide","corpus"],"bank":["caliptra","periciclo","endoderma"],"why":"Secondo il modello tunica-corpus, la tunica (L1, L2) aumenta il numero di cellule ma non di strati; il corpus (L3) aumenta cellule e strati e forma la stele. La caliptra è esclusiva della radice.","real":false},{"id":23036,"topic":"Organografia","type":"cloze","q":"Completa trascinando le parole nei riquadri.","text":"Nella zona di assorbimento l'endoderma presenta ispessimenti a forma di {0}; allontanandosi dall'apice la {1} si accumula anche sulla parete tangenziale esterna, dando ispessimenti a forma di {2}.","answers":["U","suberina","O"],"bank":["lignina","cutina","V"],"why":"Gli ispessimenti di suberina dell'endoderma sono a U nella zona assorbente e diventano a O più lontano dall'apice, quando si deposita suberina anche sulla parete tangenziale esterna.","real":false},{"id":23037,"topic":"Organografia","type":"cloze","q":"Completa trascinando le parole nei riquadri.","text":"Nella via {0} le soluzioni fluiscono nelle pareti e negli spazi intercellulari senza attraversare membrane; nella via {1} entrano nel citoplasma e passano da cellula a cellula tramite i {2}.","answers":["apoplastica","simplastica","plasmodesmi"],"bank":["xilematica","vacuoli","stomi"],"why":"La via apoplastica è extracellulare e viene interrotta dalla banda del Caspary; la via simplastica attraversa la membrana selettiva e prosegue attraverso i plasmodesmi.","real":false},{"id":23038,"topic":"Organografia","type":"cloze","q":"Completa trascinando le parole nei riquadri.","text":"Il fellogeno produce {0} verso l'esterno e {1} verso l'interno; insieme al fellogeno questi tessuti costituiscono il {2}.","answers":["sughero","felloderma","periderma"],"bank":["ritidoma","libro","legno"],"why":"Il fellogeno è dipleurico: sughero all'esterno e felloderma (parenchima) all'interno; i tre insieme sono il periderma. Il ritidoma è l'insieme dei tessuti morti esterni all'ultimo periderma; libro e legno sono prodotti dal cambio cribro-vascolare.","real":false},{"id":23039,"topic":"Organografia","type":"cloze","q":"Completa trascinando le parole nei riquadri.","text":"In una cerchia annuale il legno {0} ha grosse trachee a lume ampio, mentre il legno {1} ha trachee strette e molte fibre. Il legno delle Gimnosperme, con sole tracheidi e fibrotracheidi, è detto {2}.","answers":["primaverile","tardivo","omoxilo"],"bank":["eteroxilo","alburno","durame"],"why":"La cerchia comprende legno primaverile (conduzione) e tardivo o di chiusura (sostegno). Il legno omoxilo delle Gimnosperme ha solo tracheidi e fibrotracheidi; quello eteroxilo delle Angiosperme ha anche trachee, fibre e parenchima.","real":false},{"id":23040,"topic":"Organografia","type":"cloze","q":"Completa trascinando le parole nei riquadri.","text":"Le foglie con stomi sulla sola pagina inferiore, tipiche delle Dicotiledoni, sono {0}; quelle con stomi su entrambe le pagine, tipiche delle Monocotiledoni, sono {1}; le foglie galleggianti, con stomi sulla pagina superiore, sono {2}.","answers":["ipostomatiche","anfistomatiche","epistomatiche"],"bank":["astomatiche","sclerofille"],"why":"La distribuzione degli stomi distingue foglie ipostomatiche (pagina inferiore), anfistomatiche (entrambe le pagine, es. graminacee) ed epistomatiche (pagina superiore, es. foglie galleggianti). Le foglie sommerse delle idrofite sono prive di stomi; sclerofille indica foglie xeromorfe con ipoderma sclerenchimatico.","real":false},{"id":23041,"topic":"Organografia","type":"cloze","q":"Completa trascinando le parole nei riquadri.","text":"La fillotassi è {0} con una foglia per nodo, {1} con due foglie per nodo e {2} con tre o più foglie per nodo.","answers":["alterna","opposta","verticillata"],"bank":["plagiotropa","ortotropa"],"why":"La fillotassi, costante nella specie, è alterna (1 foglia per nodo), opposta (2) o verticillata (3 o più). Plagiotropo e ortotropo descrivono invece il portamento della foglia rispetto al terreno.","real":false},{"id":23042,"topic":"Organografia","type":"cloze","q":"Completa trascinando le parole nei riquadri.","text":"La gemma apicale produce {0}, che con trasporto polare {1} inibisce le gemme laterali; asportando l'apice, le {2} provenienti dalle radici stimolano le gemme laterali a germogliare.","answers":["auxina","basipeto","citochinine"],"bank":["etilene","acropeto","cellulasi"],"why":"La dominanza apicale dipende dall'auxina (IAA) che scende lungo il fusto con trasporto polare basipeto; con la cimatura il flusso si interrompe e le citochinine radicali attivano le gemme laterali. L'etilene interviene nell'abscissione, le cellulasi sono enzimi idrolitici.","real":false},{"id":23043,"topic":"Organografia","type":"match","q":"Associa a ogni istogeno dell'apice radicale il tessuto che origina.","rows":[{"label":"Dermatogeno (protoderma)","ans":"epidermide radicale"},{"label":"Periblema","ans":"corteccia primaria"},{"label":"Pleroma","ans":"cilindro centrale"},{"label":"Caliptrogeno","ans":"cuffia"}],"options":["corteccia primaria","sughero","felloderma","cuffia","epidermide radicale","cilindro centrale"],"why":"Il dermatogeno forma l'epidermide radicale, il periblema la corteccia, il pleroma il cilindro centrale e il caliptrogeno la cuffia. Sughero e felloderma sono tessuti secondari prodotti dal fellogeno, non dagli istogeni dell'apice.","real":false},{"id":23044,"topic":"Organografia","type":"match","q":"Associa a ogni tipo di ramo la sua descrizione.","rows":[{"label":"Macroblasti","ans":"rami lunghi con apice attivo a lungo"},{"label":"Brachiblasti","ans":"rami corti a internodi brevi che portano fiori"},{"label":"Polloni","ans":"rami vigorosi da gemme avventizie su radici o colletto"},{"label":"Cladodi","ans":"rami trasformati con aspetto e funzione di foglie"}],"options":["rami lunghi con apice attivo a lungo","rami corti a internodi brevi che portano fiori","fusticini striscianti che radicano ai nodi","rami vigorosi da gemme avventizie su radici o colletto","rami trasformati con aspetto e funzione di foglie"],"why":"I macroblasti espandono la chioma, i brachiblasti portano fiori e frutti, i polloni nascono da gemme avventizie; i cladodi (Ruscus) sono rami fotosintetici simili a foglie. I fusticini che radicano ai nodi sono gli stoloni.","real":false},{"id":23045,"topic":"Organografia","type":"match","q":"Associa a ogni termine della simbiosi azotofissatrice la sua definizione.","rows":[{"label":"Flavonoidi","ans":"segnali della radice che inducono i geni nod"},{"label":"Filamento di infezione","ans":"tubo di materiale simile alla parete in cui crescono i batteri"},{"label":"Batteroide","ans":"forma differenziata non divisiva che riduce l'N2"},{"label":"Simbiosoma","ans":"batteroide con spazio e membrana peribatteroide"},{"label":"Nitrogenasi","ans":"complesso che riduce l'N2 ad ammoniaca"}],"options":["via di assimilazione GS/GOGAT dell'ammonio","forma differenziata non divisiva che riduce l'N2","segnali della radice che inducono i geni nod","batteroide con spazio e membrana peribatteroide","complesso che riduce l'N2 ad ammoniaca","tubo di materiale simile alla parete in cui crescono i batteri"],"why":"I flavonoidi della pianta avviano il dialogo, i batteri crescono nei filamenti di infezione e, liberati per endocitosi, diventano batteroidi racchiusi nel simbiosoma, dove la nitrogenasi riduce l'N2. La via GS/GOGAT serve all'assimilazione dell'ammonio, quasi spenta nei batteroidi.","real":false},{"id":23046,"topic":"Organografia","type":"sort","q":"Riconosci l'organo: trascina ogni struttura nell'organo da cui deriva.","cats":["Radice","Fusto","Foglia"],"items":[{"t":"Cirro di Pisum sativum","cat":2},{"t":"Organo di riserva di Ipomoea batatas","cat":0},{"t":"Cladodio di Ruscus aculeatus","cat":1},{"t":"Tubero di Solanum tuberosum","cat":1},{"t":"Spina di Gleditsia triacanthos","cat":1},{"t":"Spina delle Cactaceae","cat":2},{"t":"Pneumatoforo delle mangrovie","cat":0},{"t":"Austorio di Cuscuta","cat":0},{"t":"Perula","cat":2}],"why":"Tubero, cladodio e spine di Gleditsia sono fusti o rami modificati; pneumatofori, austori e l'organo di riserva di Ipomoea batatas (radice laterale tuberizzata) sono radici; spine delle Cactaceae, cirri di Pisum e perule sono fillomi.","real":false},{"id":23047,"topic":"Organografia","type":"sort","q":"Riconosci l'organo: trascina ogni struttura nell'organo da cui deriva.","cats":["Radice","Fusto","Foglia"],"items":[{"t":"Spata delle Araceae","cat":2},{"t":"Organo che si accorcia trascinando il bulbo in profondità","cat":0},{"t":"Parte ingrossata della carota","cat":0},{"t":"Stolone","cat":1},{"t":"Catafilli di riserva di Allium cepa","cat":2},{"t":"Spina di Robinia pseudoacacia","cat":2},{"t":"Contrafforti alla base del tronco di alberi tropicali","cat":0},{"t":"Bulbo-tubero di Crocus sativus (parte di riserva)","cat":1},{"t":"Rizoma","cat":1}],"why":"Rizomi, stoloni e la parte carnosa del bulbo-tubero sono fusti; i catafilli della cipolla, le spine stipolari di Robinia e la spata (ipsofillo) sono di origine fogliare; radici contrattili (che trascinano bulbi in profondità), radici tabulari (contrafforti) e il fittone tuberizzato della carota sono radici.","real":false},{"id":23048,"topic":"Organografia","type":"sort","q":"Trascina ogni carattere nel gruppo in cui è tipico.","cats":["Monocotiledoni","Dicotiledoni"],"items":[{"t":"Atassostele","cat":0},{"t":"Apparato radicale omorrizico","cat":0},{"t":"Fasci collaterali chiusi nel fusto","cat":0},{"t":"Actinostele con 4-6 arche","cat":1},{"t":"Fasci aperti con cambio","cat":1},{"t":"Foglia bifacciale ipostomatica","cat":1},{"t":"Actinostele con oltre 15 arche e midollo centrale","cat":0},{"t":"Eustele","cat":1},{"t":"Foglia isolaterale con cellule bulliformi","cat":0}],"why":"Le Monocotiledoni hanno atassostele con fasci chiusi, foglie isolaterali anfistomatiche con cellule bulliformi, apparato omorrizico e radici con molte arche. Le Dicotiledoni hanno eustele con fasci aperti, foglie bifacciali ipostomatiche e poche arche radicali.","real":false},{"id":23049,"topic":"Organografia","type":"sort","q":"Trascina ogni carattere nella simbiosi radicale corrispondente.","cats":["Ectomicorrize","Endomicorrize","Noduli azotofissatori"],"items":[{"t":"Funghi Zygomycota","cat":1},{"t":"Funghi quasi sempre Basidiomycota","cat":0},{"t":"Rhizobium nelle leguminose","cat":2},{"t":"Frankia in Alnus","cat":2},{"t":"Ife solo fra le cellule della corteccia","cat":0},{"t":"Simbiosomi","cat":2},{"t":"Ife dentro le cellule corticali, membrana invaginata","cat":1},{"t":"Circa 80% delle erbacee","cat":1},{"t":"Manto di ife attorno alla radice (micoclena)","cat":0}],"why":"Le ectomicorrize formano un manto e restano intercellulari (Basidiomycota); le endomicorrize VAM (Zygomycota) entrano nelle cellule corticali e sono le più comuni nelle erbacee; i noduli ospitano batteri azotofissatori come Rhizobium o Frankia, racchiusi in simbiosomi.","real":false},{"id":24000,"topic":"Fiore e riproduzione","type":"mc","q":"Nel ciclo aplodiplonte delle piante, i gameti sono prodotti:","opts":["dallo sporofito, per meiosi, all'interno degli sporangi","dal gametofito, per mitosi, all'interno dei gametangi","dal gametofito, per meiosi, all'interno di anteridi e archegoni","dallo sporofito, per mitosi, all'interno dei gametangi"],"correct":1,"why":"Il gametofito è già aploide e produce i gameti per mitosi nei gametangi (anteridi e archegoni). La meiosi avviene invece nello sporofito, negli sporangi, e produce spore, non gameti.","real":false},{"id":24001,"topic":"Fiore e riproduzione","type":"mc","q":"Nelle briofite (muschi) lo sporofito:","opts":["è la pianta verde e fogliosa, troficamente indipendente, che forma il tappeto del muschio","si sviluppa dal protallo cuoriforme e diventa rapidamente indipendente","è una struttura transitoria formata da seta e capsula, parassita del gametofito","produce gameti maschili biflagellati all'interno degli anteridi"],"correct":2,"why":"Nei muschi lo sporofito (2n) si sviluppa dentro l'archegonio fecondato ed è una seta sormontata da una capsula, che dipende troficamente dal gametofito. La pianta verde fogliosa è il gametofito, che porta anche gli anteridi; il protallo è il gametofito delle felci.","real":false},{"id":24002,"topic":"Fiore e riproduzione","type":"mc","q":"Il protallo delle felci:","opts":["è lo sporofito giovane, ancora legato alla pianta madre","è un gruppo di sporangi posto sulla pagina inferiore delle fronde","è un gametofito aploide eterotrofo, parassita dello sporofito","è un gametofito aploide autotrofo, privo di tessuti vascolari"],"correct":3,"why":"Il protallo è il gametofito (n) delle Pteridofite: una piccola lamina verde a forma di cuore, autotrofa, senza tessuti vascolari, che porta anteridi e archegoni. I gruppi di sporangi sulle fronde sono i sori; è lo sporofito giovane a essere inizialmente legato al protallo, non il contrario.","real":false},{"id":24003,"topic":"Fiore e riproduzione","type":"multi","q":"Seleziona le affermazioni corrette sul trend evolutivo del ciclo vitale nelle piante terrestri:","opts":["il gametofito si riduce progressivamente a favore dello sporofito","nelle Spermatofite il gametofito femminile è contenuto interamente nell'ovulo","la riduzione del gametofito ha reso la fecondazione più dipendente dall'acqua liquida","il gametofito maschile delle Spermatofite si riduce al granulo pollinico","nelle Spermatofite la generazione dominante è quella aploide"],"correct":[0,1,3],"why":"Con la conquista della terraferma il gametofito (n) si riduce drasticamente ed è protetto nei tessuti dello sporofito (2n), che domina: il femminile resta nell'ovulo, il maschile diventa il granulo pollinico. Il trasporto del polline da parte di vento o insetti libera la fecondazione dal vincolo dell'acqua, anziché aumentarlo.","real":false},{"id":24004,"topic":"Fiore e riproduzione","type":"sort","q":"Alternanza di generazioni: trascina ogni struttura nella generazione a cui appartiene.","cats":["Sporofito (2n)","Gametofito (n)"],"items":[{"t":"Pianta verde fogliosa del muschio","cat":1},{"t":"Seta e capsula del muschio","cat":0},{"t":"Fronda della felce","cat":0},{"t":"Protallo cuoriforme","cat":1},{"t":"Granulo pollinico","cat":1},{"t":"Sacco embrionale","cat":1},{"t":"Nocella dell'ovulo","cat":0},{"t":"Embrione del seme","cat":0},{"t":"Endosperma primario delle Gimnosperme","cat":1}],"why":"Sono gametofiti la pianta fogliosa del muschio, il protallo delle felci, il granulo pollinico, il sacco embrionale e l'endosperma primario (gametofito femminile delle Gimnosperme). Sono sporofitici seta e capsula dei muschi, la fronda della felce, la nocella (macrosporangio 2n) e l'embrione, che è il nuovo sporofito.","real":false},{"id":24005,"topic":"Fiore e riproduzione","type":"cloze","q":"Completa trascinando le parole nei riquadri.","text":"Nel ciclo aplodiplonte la generazione diploide, detta {0}, si sviluppa dallo zigote per mitosi; in organi detti {1} alcune cellule madri compiono la meiosi, producendo {2} aploidi che, germinando, originano il {3}.","answers":["sporofito","sporangi","spore","gametofito"],"bank":["gametangi","gameti","zigoti"],"why":"Lo sporofito (2n) deriva dallo zigote e compie la meiosi sporica negli sporangi, producendo spore aploidi; queste germinano per mitosi nel gametofito. I gametangi sono gli organi del gametofito che producono i gameti.","real":false},{"id":24006,"topic":"Fiore e riproduzione","type":"mc","q":"Durante la maturazione del frutto:","opts":["i cromoplasti si trasformano in cloroplasti e la buccia rinverdisce","la polpa si indurisce per sintesi di nuove pectine ed emicellulose","l'etilene accelera il processo, che può essere ritardato con alta concentrazione di CO₂","l'auxina prodotta dagli acheni inibisce l'accrescimento del ricettacolo"],"correct":2,"why":"La maturazione è accelerata dall'etilene e rallentata da poco etilene e molta CO₂, che ne inibisce il recettore. Avviene il contrario dei distrattori: i cloroplasti diventano cromoplasti, la polpa si rammollisce per idrolisi di pectine ed emicellulose e l'auxina degli acheni stimola lo sviluppo del ricettacolo.","real":false},{"id":24007,"topic":"Fiore e riproduzione","type":"match","q":"Associa a ogni tipo di ciclo ontogenetico la sua caratteristica.","rows":[{"label":"Aplonte","ans":"lo zigote è l'unica cellula 2n e va subito in meiosi"},{"label":"Diplonte","ans":"i gameti sono prodotti per meiosi"},{"label":"Aplodiplonte","ans":"la meiosi produce spore che originano il gametofito"},{"label":"Ciclo isomorfico","ans":"gametofito e sporofito di aspetto simile (Ulva)"}],"options":["lo zigote è l'unica cellula 2n e va subito in meiosi","i gameti sono prodotti per meiosi","la meiosi produce spore che originano il gametofito","gametofito e sporofito di aspetto simile (Ulva)","lo zigote compie mitosi e produce spore diploidi","i gameti sono prodotti dallo sporofito per mitosi"],"why":"Nell'aplonte prevale la fase n e solo lo zigote è diploide; nel diplonte prevale la fase 2n e la meiosi produce direttamente i gameti; nell'aplodiplonte la meiosi è intermedia e produce spore. Il ciclo isomorfico ha generazioni simili, come in Ulva. Le spore dei cicli vegetali derivano dalla meiosi e sono aploidi, e i gameti sono prodotti dal gametofito, non dallo sporofito.","real":false},{"id":24008,"topic":"Fiore e riproduzione","type":"mc","q":"Nelle Gimnosperme il granulo pollinico rilasciato:","opts":["è un gametofito maschile immaturo di poche cellule, dotato di sacche aerifere","è una microspora diploide che compirà la meiosi dopo l'impollinazione","contiene due gameti maschili flagellati pronti per la fecondazione","si forma nei coni femminili, all'interno della nocella"],"correct":0,"why":"Il polline delle Gimnosperme è il gametofito maschile immaturo (n): due cellule protallari degenerate, una cellula generativa e una del tubetto, con due sacche aerifere per l'impollinazione anemofila. Si forma nelle sacche polliniche dei coni maschili; i nuclei spermatici si formano più tardi e sono privi di flagelli.","real":false},{"id":24009,"topic":"Fiore e riproduzione","type":"mc","q":"Nelle Spermatofite l'ovulo immaturo:","opts":["è un microsporangio che libera spore trasportate dal vento","è il gametofito maschile ridotto a due o tre cellule","è un macrosporangio (nocella) protetto dai tegumenti, che non rilascia mai le spore","è un archegonio con la cellula uovo, privo di tegumenti protettivi"],"correct":2,"why":"Le Spermatofite sono eterosporee: l'ovulo è un macrosporangio (nocella) avvolto dai tegumenti e la macrospora germina restando al suo interno. Il microsporangio corrisponde alle sacche polliniche, e il gametofito ridotto a poche cellule è il granulo pollinico.","real":false},{"id":24010,"topic":"Fiore e riproduzione","type":"cloze","q":"Completa trascinando le parole nei riquadri.","text":"Nel seme di Gimnosperma coesistono tre generazioni: {0} (vecchio sporofito, 2n), {1} (gametofito femminile, n) e {2} (nuovo sporofito, 2n).","answers":["tegumento","endosperma primario","embrione"],"bank":["endosperma secondario","esocarpo","ovario"],"why":"Il tegumento deriva dai tegumenti dell'ovulo e quindi dallo sporofito madre; l'endosperma primario aploide è il corpo del gametofito femminile; l'embrione deriva dallo zigote. L'endosperma secondario (3n) esiste solo nelle Angiosperme, mentre ovario ed esocarpo riguardano il fiore e il frutto delle Angiosperme.","real":false},{"id":24011,"topic":"Fiore e riproduzione","type":"mc","q":"Nella fecondazione sifonogama delle Gimnosperme:","opts":["i gameti maschili flagellati nuotano nella goccia di impollinazione fino all'archegonio","il tubetto scarica due nuclei spermatici nell'archegonio: uno feconda la cellula uovo, l'altro degenera","il secondo nucleo spermatico si fonde con due nuclei polari e forma un tessuto triploide","tra impollinazione e fecondazione trascorrono al massimo poche ore"],"correct":1,"why":"Nella sifonogamia il tubetto pollinico porta all'archegonio due nuclei spermatici privi di flagelli: uno forma lo zigote e l'altro degenera. La fusione con i nuclei polari appartiene alla doppia fecondazione delle Angiosperme. Nelle Gimnosperme il processo è lentissimo e può durare più di un anno.","real":false},{"id":24012,"topic":"Fiore e riproduzione","type":"mc","q":"La partenocarpia:","opts":["è la formazione di semi con un embrione clonale, senza meiosi né fecondazione","è la produzione di semi direttamente dal polline, con genoma solo paterno","è la dispersione dei semi a opera dell'uomo, volontaria o involontaria","è la formazione di frutti privi di semi senza impollinazione né fecondazione"],"correct":3,"why":"La partenocarpia, naturale o indotta (per esempio con auxine e gibberelline), dà frutti senza semi, come banane e alcune arance. I semi clonali sono tipici dell'apomissia, i semi di solo polline dell'androgenesi (Cupressus dupreziana) e la dispersione a opera dell'uomo è l'antropocoria.","real":false},{"id":24013,"topic":"Fiore e riproduzione","type":"cloze","q":"Completa trascinando le parole nei riquadri.","text":"Il calice è formato da {0} e protegge il bocciolo; la corolla è formata da {1} con funzione {2}. Nel gineceo lo {3} cattura il polline grazie alla sua superficie papillosa e viscosa.","answers":["sepali","petali","vessillare","stimma"],"bank":["tepali","stilo","trofica"],"why":"Calice (sepali) e corolla (petali, di funzione vessillare, cioè di richiamo degli impollinatori) formano il perianzio. I tepali si hanno quando sepali e petali non sono differenziati (perigonio). Lo stimma cattura il polline, mentre lo stilo è solo un canale di transito.","real":false},{"id":24014,"topic":"Fiore e riproduzione","type":"multi","q":"Seleziona le associazioni corrette tra termine e caratteristica del fiore:","opts":["aploclamidato: un solo involucro (perigonio a tepali)","eteroclamidato: due involucri uguali tra loro","zigomorfo: simmetria bilaterale (dorsoventrale)","gamopetalo: petali concresciuti","attinomorfo: nessun piano di simmetria","aclamidato: privo di involucro"],"correct":[0,2,3,5],"why":"Eteroclamidato indica due involucri diversi (calice e corolla); se sono uguali il fiore è omoclamidato. Il fiore attinomorfo ha simmetria raggiata; quello senza piani di simmetria è detto irregolare.","real":false},{"id":24015,"topic":"Fiore e riproduzione","type":"sort","q":"Tipi di androceo: trascina ogni pianta nella categoria giusta.","cats":["Didinamo","Tetradinamo","Diadelfo","Antere conniventi o saldate (sinantere)"],"items":[{"t":"Lamio (Lamiaceae)","cat":0},{"t":"Bocca di leone","cat":0},{"t":"Cavolo (Brassicaceae)","cat":1},{"t":"Rucola (Brassicaceae)","cat":1},{"t":"Pisello (Fabaceae)","cat":2},{"t":"Fagiolo (Fabaceae)","cat":2},{"t":"Girasole (Asteraceae)","cat":3},{"t":"Pomodoro (Solanaceae)","cat":3}],"why":"La bocca di leone e le Lamiaceae come il lamio hanno androceo didinamo (quattro stami, due lunghi e due corti). Le Brassicaceae lo hanno tetradinamo (sei stami, quattro lunghi e due corti). Le Fabaceae papilionate lo hanno diadelfo, con filamenti in due fasci (9+1). Nel pomodoro (Solanaceae) le antere sono conniventi, accostate a cono attorno allo stilo; nel girasole (Asteraceae) sono saldate a tubo (sinantere).","real":false},{"id":24016,"topic":"Fiore e riproduzione","type":"match","q":"Associa a ogni tipo di androceo la sua descrizione.","rows":[{"label":"Didinamo","ans":"4 stami: 2 lunghi e 2 corti"},{"label":"Tetradinamo","ans":"6 stami: 4 lunghi e 2 corti"},{"label":"Monoadelfo","ans":"filamenti saldati in un unico fascio"},{"label":"Diadelfo","ans":"filamenti riuniti in due fasci"},{"label":"Antere conniventi o sinantere","ans":"antere unite a tubo attorno allo stilo, filamenti liberi"}],"options":["4 stami: 2 lunghi e 2 corti","6 stami: 4 lunghi e 2 corti","filamenti saldati in un unico fascio","filamenti riuniti in due fasci","antere unite a tubo attorno allo stilo, filamenti liberi","stami liberi, tutti della stessa lunghezza"],"why":"I suffissi -dinamo si riferiscono alla lunghezza relativa degli stami (di- = due lunghi, tetra- = quattro lunghi), mentre -adelfo si riferisce ai filamenti saldati in fasci (uno nelle Malvaceae, due nelle Fabaceae papilionate). Nelle antere conniventi (Solanaceae) o sinantere (Asteraceae) sono le antere a essere unite attorno allo stilo, mentre i filamenti restano liberi.","real":false},{"id":24017,"topic":"Fiore e riproduzione","type":"mc","q":"L'impollinazione anemogama è caratterizzata da:","opts":["polline scarso, di grandi dimensioni e con esina molto ornamentata","perianzio vistoso e abbondante produzione di nettare","enorme produzione di polline, stami ben esposti e perianzio ridotto","fioritura tardiva, dopo la completa emissione delle foglie"],"correct":2,"why":"Il vento non è un vettore specifico, perciò le piante anemofile producono moltissimo polline piccolo e poco ornamentato, con stami esposti e senza perianzio vistoso né nettari. Fioriscono presto, prima di emettere le foglie. Perianzio vistoso e nettare sono adattamenti all'impollinazione zoogama.","real":false},{"id":24018,"topic":"Fiore e riproduzione","type":"sort","q":"Tipi di gineceo: trascina ogni pianta (o frutto) nella categoria giusta.","cats":["Monocarpico","Apocarpico","Sincarpico"],"items":[{"t":"Fagiolo (legume)","cat":0},{"t":"Pesco (drupa)","cat":0},{"t":"Mora e lampone (Rubus)","cat":1},{"t":"Liriodendron (aggregato di samare)","cat":1},{"t":"Fragola (conocarpo con acheni)","cat":1},{"t":"Cavolo (siliqua)","cat":2},{"t":"Quercia (ghianda)","cat":2},{"t":"Carota (schizocarpo delle Apiaceae)","cat":2}],"why":"Il legume e la drupa derivano da un solo carpello (gineceo monocarpico). Polidrupe di Rubus, aggregati di samare di Liriodendron e la fragola nascono da più pistilli separati dello stesso fiore (gineceo apocarpico). Siliqua, noce (ghianda) e schizocarpo derivano da più carpelli fusi in un unico ovario (gineceo sincarpico).","real":false},{"id":24019,"topic":"Fiore e riproduzione","type":"sort","q":"Posizione dell'ovario: trascina ogni pianta nella categoria giusta.","cats":["Ovario supero (fiore ipogino)","Ovario infero (fiore epigino)"],"items":[{"t":"Tulipano","cat":0},{"t":"Pomodoro","cat":0},{"t":"Pisello","cat":0},{"t":"Cavolo","cat":0},{"t":"Zucca","cat":1},{"t":"Melo","cat":1},{"t":"Girasole","cat":1},{"t":"Carota","cat":1}],"why":"Nel tulipano, nel pomodoro, nelle Fabaceae e nelle Brassicaceae l'ovario sta sopra l'inserzione degli altri verticilli (supero). In Cucurbitaceae, melo (il pomo è un falso frutto, con polpa derivata dal ricettacolo), Asteraceae e Apiaceae l'ovario è immerso sotto gli altri verticilli (infero).","real":false},{"id":24020,"topic":"Fiore e riproduzione","type":"mc","q":"Nell'anafase I della meiosi:","opts":["i cromosomi omologhi si separano, mentre i cromatidi fratelli restano uniti al centromero","i cromatidi fratelli si separano e migrano ai poli opposti","avviene il crossing-over tra cromatidi non fratelli","si forma il complesso sinaptonemale tra gli omologhi"],"correct":0,"why":"L'anafase I è riduzionale: separa gli omologhi e dimezza il corredo, mentre i cromatidi fratelli si separano solo nella meiosi II. Crossing-over (pachitene) e complesso sinaptonemale (zigotene) avvengono durante la profase I.","real":false},{"id":24021,"topic":"Fiore e riproduzione","type":"cloze","q":"Completa trascinando le parole nei riquadri.","text":"Se l'ovario è {0} il fiore è detto ipogino; se è {1} il fiore è epigino; se è {2} il fiore è perigino.","answers":["supero","infero","seminfero"],"bank":["sincarpico","apocarpico"],"why":"La posizione dell'ovario è un carattere diagnostico: all'ovario supero corrisponde il fiore ipogino, all'infero l'epigino, al seminfero il perigino. Sincarpico e apocarpico indicano invece come sono uniti i carpelli, non la posizione dell'ovario.","real":false},{"id":24022,"topic":"Fiore e riproduzione","type":"mc","q":"Il funicolo:","opts":["è il poro apicale che interrompe il tegumento dell'ovulo","è il canale di transito del tubetto pollinico nel pistillo","è la cicatrice lasciata sul seme dal punto di ancoraggio al frutto","collega l'ovulo alla placenta e termina nella calaza"],"correct":3,"why":"Il funicolo unisce l'ovulo alla placenta dell'ovario e termina nella calaza, alla base dell'ovulo. Il poro del tegumento è il micropilo, il canale del pistillo è lo stilo e la cicatrice sul seme è l'ilo.","real":false},{"id":24023,"topic":"Fiore e riproduzione","type":"mc","q":"Nel granulo pollinico delle Angiosperme la cellula vegetativa:","opts":["è la piccola cellula che produce i due gameti maschili","è la cellula grande che formerà il tubetto pollinico","deriva direttamente dalla meiosi della cellula madre","secerne callasi per liberare le microspore della tetrade"],"correct":1,"why":"La mitosi asimmetrica della microspora produce una grande cellula vegetativa, che forma il tubetto, e una piccola cellula generativa, che produce i gameti. Le callasi sono secrete dalle cellule del tappeto dell'antera, e la meiosi produce le microspore, non la cellula vegetativa.","real":false},{"id":24024,"topic":"Fiore e riproduzione","type":"cloze","q":"Completa trascinando le parole nei riquadri.","text":"La parete esterna del granulo pollinico è l'{0}, un guscio resistentissimo costituito da {1}; la parete interna sottile è l'{2}, di natura {3}.","answers":["esina","sporopollenina","intina","cellulosica"],"bank":["callosio","suberica","lignina"],"why":"L'esina è fatta di sporopollenina, un polimero lipidico impermeabile e insolubile, con motivi specie-specifici. L'intina è sottile e cellulosica. Il callosio è la parete che tiene unite le tetradi e viene dissolta dalle callasi.","real":false},{"id":24025,"topic":"Fiore e riproduzione","type":"mc","q":"Gli Imenotteri (api, bombi) come pronubi:","opts":["sono i più efficienti e distinguono l'ultravioletto ma non il rosso","sono probabilmente i primi pronubi, attratti da fiori chiari con odore forte","visitano di notte fiori bianchi e profumati, con lungo sperone nettarifero","sono attratti dai fiori carogna, che odorano di carne in putrefazione"],"correct":0,"why":"Api e bombi sono i pronubi più efficienti e vedono l'ultravioletto (guide del nettare) ma non il rosso. I primi pronubi, guidati dall'olfatto, sono probabilmente i Coleotteri; i fiori bianchi notturni con sperone sono visitati dalle falene; i fiori carogna attirano coleotteri e mosche carnarie.","real":false},{"id":24026,"topic":"Fiore e riproduzione","type":"match","q":"Associa a ogni componente del sacco embrionale (modello Polygonum) la sua caratteristica.","rows":[{"label":"Oosfera","ans":"cellula uovo situata al polo micropilare"},{"label":"Sinergidi","ans":"secernono segnali (LURE) che guidano il tubetto"},{"label":"Antipodi","ans":"tre cellule al polo calazale"},{"label":"Cellula centrale","ans":"contiene i due nuclei polari"}],"options":["cellula uovo situata al polo micropilare","secernono segnali (LURE) che guidano il tubetto","tre cellule al polo calazale","contiene i due nuclei polari","formano il sospensore dell'embrione","macrospore che degenerano verso il micropilo"],"why":"Il sacco embrionale ha 7 cellule e 8 nuclei: al polo micropilare l'oosfera con due sinergidi, al polo calazale tre antipodi e al centro una grande cellula con due nuclei polari. Il sospensore si forma dal proembrione dopo la fecondazione, e le macrospore degenerate precedono la formazione del sacco.","real":false},{"id":24027,"topic":"Fiore e riproduzione","type":"mc","q":"Nella doppia fecondazione delle Angiosperme il secondo nucleo spermatico:","opts":["si fonde con la cellula uovo originando lo zigote","degenera senza partecipare alla fecondazione","si fonde con una sinergide e forma un secondo embrione","si fonde con i due nuclei polari originando un nucleo triploide"],"correct":3,"why":"Il primo nucleo spermatico feconda l'oosfera (zigote 2n), il secondo si unisce ai due nuclei polari e forma il nucleo 3n da cui nasce l'endosperma secondario. Il nucleo che degenera è tipico della sifonogamia delle Gimnosperme.","real":false},{"id":24028,"topic":"Fiore e riproduzione","type":"cloze","q":"Completa trascinando le parole nei riquadri.","text":"Un nucleo spermatico feconda la cellula uovo, detta {0}, originando lo zigote {1}; l'altro si fonde con i due nuclei {2}, da cui deriva l'endosperma {3}, triploide.","answers":["oosfera","diploide","polari","secondario"],"bank":["sinergide","triploide","antipodali","primario"],"why":"La prima fecondazione dà lo zigote diploide, cioè il nuovo sporofito; la seconda unisce il secondo nucleo spermatico ai due nuclei polari e forma l'endosperma secondario 3n. L'endosperma primario è aploide ed è tipico delle Gimnosperme; sinergidi e antipodi non vengono fecondati.","real":false},{"id":24029,"topic":"Fiore e riproduzione","type":"multi","q":"Seleziona le affermazioni corrette sul tubetto pollinico delle Angiosperme:","opts":["si forma dall'intina estrusa attraverso un poro dell'esina","durante il tragitto la cellula generativa produce due gameti maschili flagellati","è guidato da gradienti di Ca²⁺ e da segnali peptidici delle sinergidi","penetra nell'ovulo attraverso il micropilo","scarica i nuclei spermatici dentro una cellula antipodale"],"correct":[0,2,3],"why":"La cellula vegetativa estrude l'intina da un poro dell'esina e il tubetto, guidato dal calcio e dai segnali delle sinergidi, entra dal micropilo. I due gameti sono privi di flagelli e vengono scaricati in una sinergide, non negli antipodi, che stanno al polo calazale.","real":false},{"id":24030,"topic":"Fiore e riproduzione","type":"mc","q":"Lo scutello:","opts":["è il cotiledone ridotto delle Monocotiledoni che trasferisce all'embrione le riserve dell'endosperma","è il cotiledone carnoso dei semi esalbuminosi delle Dicotiledoni","è la cicatrice del punto di ancoraggio del seme al frutto","è l'asse dell'embrione compreso tra i cotiledoni e la radichetta"],"correct":0,"why":"Nelle Monocotiledoni (per esempio il mais) l'unico cotiledone è lo scutello, che idrolizza e assorbe l'endosperma abbondante. I cotiledoni carnosi sono tipici delle Dicotiledoni a seme esalbuminoso, la cicatrice è l'ilo e l'asse sotto i cotiledoni è l'ipocotile.","real":false},{"id":24031,"topic":"Fiore e riproduzione","type":"sort","q":"Riserve del seme: trascina ogni pianta nella categoria giusta.","cats":["Seme albuminoso (endospermico)","Seme esalbuminoso (cotiledonare)"],"items":[{"t":"Mais","cat":0},{"t":"Grano","cat":0},{"t":"Riso","cat":0},{"t":"Fagiolo","cat":1},{"t":"Pisello","cat":1},{"t":"Arachide","cat":1}],"why":"Nei cereali (Monocotiledoni) l'endosperma secondario resta abbondante a maturità e il seme è albuminoso. Nelle leguminose (Dicotiledoni) l'embrione riassorbe l'endosperma e accumula le riserve nei cotiledoni carnosi, quindi il seme è esalbuminoso.","real":false},{"id":24032,"topic":"Fiore e riproduzione","type":"mc","q":"Nelle drupe il nocciolo corrisponde:","opts":["al tegumento seminale lignificato","al mesocarpo fibroso e disidratato","all'endocarpo fortemente lignificato","all'esocarpo cutinizzato e ceroso"],"correct":2,"why":"Nella drupa (pesca, oliva, ciliegia) il mesocarpo è carnoso e l'endocarpo, che deriva dall'epidermide interna del carpello, lignifica formando il nocciolo che contiene il seme. Il tegumento seminale è la pellicola del seme, dentro il nocciolo.","real":false},{"id":24033,"topic":"Fiore e riproduzione","type":"mc","q":"La siliqua:","opts":["è tipica delle Brassicaceae e si apre in due valve lasciando il replo con i semi","deriva da un ovario monocarpellare e si apre lungo una sola sutura","è un achenio alato adattato alla dispersione anemocora","è un frutto indeiscente con pericarpo saldato al tegumento del seme"],"correct":0,"why":"La siliqua è un frutto secco deiscente che deriva da un ovario bicarpellare sincarpico: le due valve si staccano e i semi restano sul replo. Il frutto monocarpellare che si apre lungo una sola sutura è il follicolo, l'achenio alato è la samara e la cariosside ha il pericarpo saldato al seme.","real":false},{"id":24034,"topic":"Fiore e riproduzione","type":"match","q":"Associa a ogni tipo di frutto un esempio corretto.","rows":[{"label":"Cariosside","ans":"grano, mais (Poaceae)"},{"label":"Legume","ans":"fagiolo, pisello (Fabaceae)"},{"label":"Samara","ans":"acero"},{"label":"Esperidio","ans":"agrumi"},{"label":"Peponide","ans":"cucurbitacee"},{"label":"Balaustio","ans":"melograno"}],"options":["grano, mais (Poaceae)","fagiolo, pisello (Fabaceae)","acero","agrumi","cucurbitacee","melograno","mela, pera","fico"],"why":"La cariosside è tipica delle Poaceae, il legume delle Fabaceae, la samara (achenio alato) dell'acero, l'esperidio degli agrumi, il peponide delle cucurbitacee e il balaustio del melograno. Mela e pera sono pomi (falsi frutti) e il fico è un siconio (infruttescenza).","real":false},{"id":24035,"topic":"Fiore e riproduzione","type":"multi","q":"Seleziona i casi in cui la parte carnosa NON deriva dall'ovario (falsi frutti o infruttescenze):","opts":["mela","fragola","pesca","pomodoro","fico","uva"],"correct":[0,1,4],"why":"Nel pomo (mela) e nel conocarpo (fragola) la polpa deriva dal ricettacolo; il fico è un siconio, un ricettacolo cavo tappezzato di fiori. Pesca (drupa), pomodoro e uva (bacche) sono veri frutti, con la parte carnosa che deriva dalla parete dell'ovario.","real":false},{"id":24036,"topic":"Fiore e riproduzione","type":"mc","q":"Dal punto di vista botanico, la noce commerciale (Juglans):","opts":["è una vera noce, con pericarpo legnoso e seme libero","è una drupa","è un achenio","è una cariosside"],"correct":1,"why":"La noce di Juglans è botanicamente una drupa. La vera noce, come la ghianda della quercia, deriva da un ovario pluricarpellare sincarpico supero, con pericarpo legnoso e seme libero.","real":false},{"id":24037,"topic":"Fiore e riproduzione","type":"mc","q":"La mirmecoria è:","opts":["la dispersione di frutti uncinati che si agganciano al pelo degli animali","la dispersione di semi ingeriti che attraversano intatti l'apparato digerente","il lancio attivo dei semi dovuto alla pressione idrostatica","il trasporto nei formicai di semi provvisti di elaiosomi"],"correct":3,"why":"Nella mirmecoria le formiche portano nei formicai semi con elaiosomi (corpi oleosi). I frutti uncinati come quelli di Arctium sono un esempio di epizoocoria, i semi ingeriti di endozoocoria e il lancio per pressione (Ecballium) di autocoria.","real":false},{"id":24038,"topic":"Fiore e riproduzione","type":"cloze","q":"Completa trascinando le parole nei riquadri.","text":"Le piante {0} fioriscono una sola volta e la fioritura ne determina la morte (es. Agave); le {1} fioriscono più volte (es. Paeonia). Nelle piante {2} solo organi specifici partecipano alla riproduzione.","answers":["monocarpiche","policarpiche","eucarpiche"],"bank":["olocarpiche","monoiche","dioiche"],"why":"Monocarpiche e policarpiche indicano quante volte la pianta fiorisce; eucarpiche e olocarpiche indicano quanta parte del corpo entra in riproduzione (l'olocarpia, con scomparsa dell'individuo, riguarda solo gli unicellulari). Monoiche e dioiche indicano invece se organi maschili e femminili stanno sulla stessa pianta o su piante diverse.","real":false},{"id":24039,"topic":"Fiore e riproduzione","type":"mc","q":"Nell'embriogenesi delle Angiosperme il sospensore:","opts":["deriva dalla cellula calazale del proembrione e forma i cotiledoni","è l'asse dell'embrione compreso tra i cotiledoni e la radichetta","deriva dalla cellula micropilare del proembrione, spinge l'embrione nel tessuto di riserva e poi muore","è il tessuto triploide di riserva dei semi albuminosi"],"correct":2,"why":"Lo zigote si divide in modo asimmetrico: la cellula verso il micropilo forma il sospensore, che nutre l'embrione, produce ormoni e muore allo stadio a torpedine; la cellula calazale forma l'embrione. L'asse tra cotiledoni e radice è l'ipocotile e il tessuto 3n è l'endosperma secondario.","real":false},{"id":24040,"topic":"Fiore e riproduzione","type":"multi","q":"Seleziona le strutture o tecniche di moltiplicazione vegetativa (agamica):","opts":["stoloni della fragola","tuberi della patata","bulbilli","samare dell'acero","talee e margotte","granuli pollinici"],"correct":[0,1,2,4],"why":"La moltiplicazione vegetativa usa parti del corpo vegetativo e produce, per mitosi, cloni della pianta madre: stoloni, tuberi, bulbilli, talee, margotte e innesti. Le samare sono frutti che contengono semi, e il polline è il gametofito maschile: entrambi appartengono alla riproduzione sessuale.","real":false},{"id":24041,"topic":"Fiore e riproduzione","type":"mc","q":"L'apomissia:","opts":["forma semi con un embrione nato senza meiosi né fusione dei gameti, clone della pianta madre","forma frutti privi di semi in assenza di impollinazione e fecondazione","è l'impollinazione di un fiore con il polline dello stesso individuo","è la propagazione per talea favorita dagli ormoni radicanti"],"correct":0,"why":"L'apomissia è una riproduzione asessuata attraverso il seme, frequente in Poaceae, Asteraceae e Rosaceae (Rubus). I frutti senza semi derivano dalla partenocarpia, l'autoimpollinazione è l'autogamia (che resta sessuale) e la talea è propagazione vegetativa senza seme.","real":false},{"id":24042,"topic":"Fiore e riproduzione","type":"cloze","q":"Completa trascinando le parole nei riquadri.","text":"Si parla di {0} quando i gameti hanno uguale forma e dimensione, di {1} quando hanno la stessa forma ma dimensioni diverse e di {2} quando il gamete femminile è grande e immobile: quest'ultima è la modalità di tutte le piante.","answers":["isogamia","anisogamia","oogamia"],"bank":["gametangiogamia","somatogamia"],"why":"Isogamia, anisogamia e oogamia classificano i gameti in base a morfologia e dimensione; tutte le piante sono oogame. Gametangiogamia (fusione di gametangi interi) e somatogamia (fusione di strutture non specializzate) indicano invece che cosa si fonde, per esempio in ascomiceti e basidiomiceti.","real":false},{"id":24043,"topic":"Fiore e riproduzione","type":"multi","q":"Seleziona i meccanismi che ostacolano l'autogamia e favoriscono l'allogamia:","opts":["autosterilità","dicogamia (proterandria o proteroginia)","eterostilia (es. Primula)","ercogamia","apomissia"],"correct":[0,1,2,3],"why":"Autosterilità (incompatibilità), dicogamia (maturazione degli organi sessuali in tempi diversi), eterostilia (morfi con stili e stami di lunghezza diversa) ed ercogamia (posizione reciproca di stami e pistillo) favoriscono l'impollinazione incrociata. L'apomissia invece produce semi clonali senza fecondazione.","real":false},{"id":24044,"topic":"Fiore e riproduzione","type":"mc","q":"I semi recalcitranti:","opts":["sopportano la disidratazione e restano dormienti per decenni","non tollerano il disseccamento e devono germinare subito (querce, castani)","vengono rilasciati solo dopo il passaggio del fuoco (serotinia)","hanno una dormienza endogena dovuta all'ABA contenuto nei cotiledoni"],"correct":1,"why":"I semi recalcitranti, come quelli di querce, aceri, castani e ippocastani, non sopportano la disidratazione e devono germinare subito. Quelli che la tollerano e restano dormienti a lungo sono gli ortodossi; la serotinia riguarda il rilascio dei semi dopo il fuoco (Pinus halepensis).","real":false},{"id":25000,"topic":"Sistematica","type":"mc","q":"La sistematica:","opts":["unisce in base alle somiglianze, stabilendo per mezzo di norme entità convenzionali","distingue in base alle differenze e individua in natura gruppi reali e concreti","si occupa solo di dare i nomi alle specie secondo le regole dell'ICBN","raggruppa gli organismi in base a pochi caratteri di facile osservazione"],"correct":1,"why":"La sistematica distingue in base alle differenze e riconosce gruppi reali (unità sistematiche), occupandosi di identificazione, denominazione e storia evolutiva. Unire per somiglianze in entità convenzionali stabilite da norme è invece il compito della tassonomia; l'uso di pochi caratteri evidenti è tipico dei sistemi artificiali.","real":false},{"id":25001,"topic":"Sistematica","type":"cloze","q":"Completa trascinando le parole nei riquadri.","text":"Secondo l'ICBN la famiglia ha il suffisso {0}, l'ordine il suffisso {1}, la classe il suffisso {2} e il phylum (divisione) il suffisso {3}.","answers":["-aceae","-ales","-opsida","-phyta"],"bank":["-idae","-oideae","-bionta"],"why":"Famiglia -aceae (Aceraceae), ordine -ales (Sapindales), classe -opsida (Angiospermopsida), divisione -phyta (Embryophyta). -idae indica la sottoclasse, -oideae la sottofamiglia e -bionta il regno.","real":false},{"id":25002,"topic":"Sistematica","type":"mc","q":"Le analogie:","opts":["derivano da un progenitore comune che possedeva la caratteristica e indicano vera parentela","sono i caratteri derivati condivisi che la cladistica usa per definire i cladi","sono frutto di un'evoluzione convergente in gruppi non imparentati, come Cactaceae ed Euphorbiaceae","sono somiglianze biochimiche rilevate misurando l'affinità del DNA/RNA"],"correct":2,"why":"Le analogie nascono da evoluzione convergente e producono fenotipi simili in gruppi non imparentati (Cactaceae ed Euphorbiaceae succulente), per cui ingannano. Sono le omologie, derivate da un antenato comune, a essere indizio di parentela.","real":false},{"id":25003,"topic":"Sistematica","type":"multi","q":"Seleziona le affermazioni corrette sulla nomenclatura binomia:","opts":["è stata introdotta da Linneo con Species Plantarum (1753)","il primo nome indica il genere e si scrive con l'iniziale maiuscola","il nome dell'autore si scrive in corsivo come il binomio","se l'autore è già stato citato nel testo, il suo nome si può omettere","l'epiteto specifico è spesso descrittivo (es. grandiflora, acaulis)"],"correct":[0,1,4],"why":"Il binomio latino in corsivo (genere con maiuscola + epiteto specifico, spesso descrittivo) fu introdotto da Linneo nel 1753. Il nome dell'autore non va in corsivo e può essere abbreviato fino all'iniziale, ma non deve mai essere omesso.","real":false},{"id":25004,"topic":"Sistematica","type":"mc","q":"Nel nome Cirsium tuberosum (L.) All., l'autore riportato tra parentesi indica:","opts":["lo studioso che descrisse la specie per primo, prima che All. la cambiasse di genere o di rango","l'autore di un sinonimo pubblicato successivamente e quindi non più valido","che il nome è un nomen conservandum, usato anche se non rispetta il codice","l'autore della cultivar, registrata secondo l'ICNCP"],"correct":0,"why":"Quando una specie già descritta cambia rango o viene attribuita a un altro genere, lo studioso originario va tra parentesi, seguito da chi ha fatto il cambiamento. Le parentesi non indicano né sinonimi, né nomi conservati, né cultivar (queste ultime si indicano con virgolette semplici o cv.).","real":false},{"id":25005,"topic":"Sistematica","type":"mc","q":"Secondo il principio di priorità:","opts":["il nome corretto di un taxon è quello più usato in tutto il mondo","il nome corretto è il primo attribuito in accordo con le regole di nomenclatura","la data di inizio dei nomi delle piante vascolari è il De Plantis di Cesalpino","i nomi pubblicati in seguito per lo stesso taxon restano validi come alternativi"],"correct":1,"why":"È corretto il primo nome attribuito secondo le regole; la data di inizio per le piante vascolari è Species Plantarum di Linneo. I nomi successivi per lo stesso taxon sono sinonimi non corretti; l'uso comune conta solo per i nomina conservanda (es. Crucifere, Composite), che sono un'eccezione.","real":false},{"id":25006,"topic":"Sistematica","type":"match","q":"Associa a ogni nome la categoria che esprime.","rows":[{"label":"Mentha arvensis L. ssp. austriaca (Jacq.) Briq.","ans":"sottospecie"},{"label":"Oenothera suaveolens Pers. var. latipetala Soldano","ans":"varietà"},{"label":"Cetraria islandica L. f. minima","ans":"forma"},{"label":"Capsicum annuum 'deep purple'","ans":"cultivar"},{"label":"Tilia x vulgaris","ans":"ibrido"}],"options":["sottospecie","varietà","forma","cultivar","ibrido","nomen conservandum"],"why":"Le categorie infraspecifiche si indicano con ssp., var. e f.; le cultivar (piante migliorate in coltivazione) con virgolette semplici o cv.; gli ibridi con il segno x (Tilia x vulgaris, ibrido spontaneo tra T. platyphyllos e T. cordata).","real":false},{"id":25007,"topic":"Sistematica","type":"cloze","q":"Completa trascinando le parole nei riquadri.","text":"La cladistica impone che i cladi siano gruppi {0}, cioè formati da organismi tutti derivati da un comune antenato. Le dicotiledoni tradizionali sono invece {1}, mentre le eudicotiledoni si riconoscono per il polline {2}.","answers":["monofiletici","parafiletiche","tricolpato"],"bank":["polifiletici","polifiletiche","monosolcato","inaperturato"],"why":"I cladi devono essere monofiletici. Le dicotiledoni tradizionali sono parafiletiche e non formano un gruppo naturale; le eudicotiledoni, monofiletiche, hanno come sinapomorfia il polline tricolpato. Il polline monosolcato è tipico delle monocotiledoni.","real":false},{"id":25008,"topic":"Sistematica","type":"mc","q":"Il sistema di classificazione di Linneo:","opts":["era un sistema naturale, basato su numerosi caratteri morfologici","era un sistema filogenetico, basato sull'origine comune degli organismi","raggruppava sempre insieme le piante più simili fra loro","era un sistema artificiale, basato soprattutto sui caratteri degli stami"],"correct":3,"why":"Linneo propose sistemi artificiali basati su pochi caratteri ben definiti, soprattutto degli stami. Fra gli svantaggi c'erano la scelta arbitraria dei caratteri e il fatto che non sempre le piante più simili venivano raggruppate insieme. I sistemi naturali arrivano nel secolo successivo, quelli filogenetici dopo Darwin.","real":false},{"id":25009,"topic":"Sistematica","type":"mc","q":"Identificare (o determinare) una pianta significa:","opts":["attribuire un esemplare a una specie già nota","descrivere un taxon nuovo per la scienza e collocarlo nello schema gerarchico","raccogliere campioni essiccati e allestirli in un erbario","ricostruire l'albero filogenetico di un gruppo di specie"],"correct":0,"why":"Identificare significa riconoscere un esemplare e attribuirlo a una specie già nota, ad esempio con chiavi dicotomiche. Descrivere e collocare un taxon nuovo è invece classificare; l'erbario è solo uno strumento pratico.","real":false},{"id":25010,"topic":"Sistematica","type":"mc","q":"Il gruppo progenitore delle piante terrestri (Embryophyta) va ricercato tra:","opts":["i cianobatteri azotofissatori","le Charophyceae (alghe verdi)","le alghe brune","le Cycadophyta"],"correct":1,"why":"Con le Charophyceae le piante terrestri condividono cellule flagellate asimmetriche, fragmoplasto, piastra cellulare, plasmodesmi e affinità molecolari; Coleochaete o Chara sono indicate come sister group. Le Cycadophyta sono già spermatofite.","real":false},{"id":25011,"topic":"Sistematica","type":"mc","q":"Andrea Cesalpino (1519-1603):","opts":["introdusse la nomenclatura binomia con Species Plantarum","classificò oltre 600 specie descritte minuziosamente in epoca romana","fu il primo a suggerire una relazione tra struttura e funzione dei caratteri morfologici","pubblicò On the Origin of species, trasformando il significato delle categorie tassonomiche"],"correct":2,"why":"Cesalpino (De Plantis Libri XVI) classificò 1500 specie, collegò struttura e funzione dei caratteri, raggruppò le entità in gruppi via via superiori e realizzò uno dei primi erbari. La binomia è di Linneo, le 600 specie di Plinio il Vecchio, l'Origin di Darwin.","real":false},{"id":25012,"topic":"Sistematica","type":"mc","q":"Il seme delle gimnosperme è detto 'nudo' perché:","opts":["è privo di tegumenti seminali","non contiene un endosperma di riserva","si sviluppa sul macrosporofillo senza esserne racchiuso, e il frutto manca","l'embrione non è circondato da tessuti diploidi"],"correct":2,"why":"L'ovulo è portato allo scoperto sul macrosporofillo e non è racchiuso in un ovario, per cui non si forma il frutto. Il seme ha comunque tegumenti diploidi, un endosperma primario aploide di riserva e l'embrione.","real":false},{"id":25013,"topic":"Sistematica","type":"sort","q":"Gimnosperme: trascina ogni struttura nel corretto livello di ploidia.","cats":["Diploide (2n)","Aploide (n)"],"items":[{"t":"Tegumenti dell'ovulo","cat":0},{"t":"Nocella","cat":0},{"t":"Endosperma primario","cat":1},{"t":"Embrione","cat":0},{"t":"Granulo pollinico (microspora)","cat":1},{"t":"Microsporofillo","cat":0},{"t":"Macrospora","cat":1}],"why":"Tegumenti, nocella, microsporofilli ed embrione appartengono allo sporofito diploide. Microspore e macrospora derivano dalla meiosi e sono aploidi, come l'endosperma primario, che è il gametofito femminile.","real":false},{"id":25014,"topic":"Sistematica","type":"match","q":"Associa a ogni phylum di gimnosperme il carattere distintivo.","rows":[{"label":"Cycadophyta","ans":"radici coralloidi che ospitano cianobatteri azotofissatori"},{"label":"Ginkgophyta","ans":"foglie flabelliformi decidue a ciuffetti su brachiblasti"},{"label":"Gnetophyta","ans":"legno eteroxilo con trachee nello xilema"},{"label":"Coniferophyta","ans":"gruppo più numeroso, con 7 famiglie e oltre 600 specie"}],"options":["radici coralloidi che ospitano cianobatteri azotofissatori","foglie flabelliformi decidue a ciuffetti su brachiblasti","legno eteroxilo con trachee nello xilema","gruppo più numeroso, con 7 famiglie e oltre 600 specie","ovuli racchiusi in un ovario che diventa frutto"],"why":"Le cicadi ospitano Anabaena e Nostoc nelle radici coralloidi; Ginkgo ha foglie a ventaglio su brachiblasti; le Gnetophyta sono l'eccezione con legno eteroxilo e vasi; le conifere sono il gruppo più numeroso. Nessuna gimnosperma ha ovuli racchiusi in un ovario.","real":false},{"id":25015,"topic":"Sistematica","type":"sort","q":"Conifere: trascina ogni genere nella famiglia di appartenenza.","cats":["Pinaceae","Cupressaceae","Taxaceae"],"items":[{"t":"Abies","cat":0},{"t":"Larix","cat":0},{"t":"Cedrus","cat":0},{"t":"Juniperus","cat":1},{"t":"Cupressus","cat":1},{"t":"Sequoia","cat":1},{"t":"Taxus","cat":2},{"t":"Torreya","cat":2}],"why":"Abies, Larix e Cedrus (con Picea e Pinus) sono Pinaceae; Juniperus, Cupressus, Sequoia (con Thuja e Taxodium) sono Cupressaceae; Taxus e Torreya sono Taxaceae, conifere prive di canali resiniferi e con ovulo avvolto da arillo.","real":false},{"id":25016,"topic":"Sistematica","type":"mc","q":"L'arillo di Taxus baccata:","opts":["è un frutto carnoso che deriva dalla trasformazione dell'ovario","è un involucro carnoso derivato da un cercine alla base dell'ovulo, unica parte non tossica","è formato dalle squame ovulifere saldate e divenute carnose","è il tegumento carnoso e puzzolente del seme, ricoperto di pruina"],"correct":1,"why":"L'arillo nasce dalla proliferazione di un cercine alla base dell'ovulo, avvolge il seme a maturità e ne favorisce la dispersione; è l'unica parte del tasso non velenosa. Non è un frutto; le squame ovulifere saldate formano i galbuli delle Cupressaceae; il tegumento carnoso puzzolente è quello di Ginkgo.","real":false},{"id":25017,"topic":"Sistematica","type":"mc","q":"Il larice (Larix decidua):","opts":["ha aghi subpungenti inseriti su pulvilli e coni penduli non desquamanti","ha coni eretti che si disarticolano a maturità","è l'unica conifera italiana caducifoglia, con aghi morbidi su brachiblasti","ha aghi in fascetti di 5 e semi dispersi dalla nocciolaia"],"correct":2,"why":"Il larice perde gli aghi, che sono morbidi e portati su brachiblasti; è eliofilo e pioniero sulle Alpi. I pulvilli e i coni penduli sono di Picea abies, i coni eretti che si disarticolano di Abies alba, gli aghi a 5 e la nocciolaia di Pinus cembra.","real":false},{"id":25018,"topic":"Sistematica","type":"cloze","q":"Completa trascinando le parole nei riquadri.","text":"Nelle Cupressaceae, dopo la fecondazione, le squame ovulifere si saldano formando i {0}. Cupressus sempervirens è una specie {1} con foglie squamiformi embricate, mentre Juniperus communis è una specie {2}, arbustiva, con foglie {3} verticillate a tre.","answers":["galbuli","monoica","dioica","aghiformi"],"groups":[0,1,1,2],"bank":[["arilli","strobili"],["ermafrodita"],["squamiformi"]],"why":"I galbuli sono coni con squame saldate, legnose (cipresso) o carnose (coccole del ginepro). Cupressus è monoico, Juniperus dioico; il ginepro comune ha foglie aghiformi pungenti verticillate a tre, il cipresso foglie a squama.","real":false},{"id":25019,"topic":"Sistematica","type":"multi","q":"Seleziona i caratteri delle Gnetophyta che rappresentano convergenze con le angiosperme:","opts":["produzione di nettare","trachee (vasi) nello xilema","un processo simile alla doppia fecondazione in Ephedra","endosperma triploide in Ephedra","ovuli racchiusi in un ovario chiuso","gameti maschili ciliati"],"correct":[0,1,2],"why":"Le Gnetophyta producono nettare, hanno vasi e, in Ephedra, una doppia fecondazione che però non genera un endosperma triploide. I loro ovuli non sono chiusi in un ovario, e i gameti ciliati sono un carattere primitivo di Cycas e Ginkgo, non una convergenza con le angiosperme.","real":false},{"id":25020,"topic":"Sistematica","type":"mc","q":"In Ginkgo biloba:","opts":["il seme è racchiuso in un frutto carnoso e puzzolente","i gameti maschili sono ciliati e la fecondazione avviene a terra, dopo la caduta degli ovuli","gli ovuli sono portati da squame ovulifere riunite in strobili complessi","la pianta è monoica e si coltivano preferibilmente esemplari femminili"],"correct":1,"why":"Ginkgo ha gameti maschili ciliati e la fecondazione avviene a terra. Il seme ha un tegumento carnoso puzzolente ma non è un frutto; gli ovuli stanno a coppie su peduncoli, non in strobili; la specie è dioica e si preferiscono gli individui maschili, propagati per innesto.","real":false},{"id":25021,"topic":"Sistematica","type":"cloze","q":"Completa trascinando le parole nei riquadri.","text":"Nell'ovulo delle gimnosperme i tegumenti avvolgono un tessuto diploide detto {0}. I tegumenti sono interrotti nella zona del {1}, mentre la parte opposta, aderente al macrosporofillo, è il polo {2}. Il gametofito femminile aploide, che contiene gli archegoni, è l'{3} primario.","answers":["nocella","micropilo","calazale","endosperma"],"bank":["arillo","embrione","apicale"],"why":"I tegumenti (2n) racchiudono la nocella (2n) e si aprono al micropilo, da cui entra il polline; dal lato opposto c'è il polo calazale. Nella nocella la macrospora forma l'endosperma primario (n), che è il gametofito femminile con gli archegoni.","real":false},{"id":25022,"topic":"Sistematica","type":"mc","q":"Qual è il sister group di tutte le altre angiosperme?","opts":["Nymphaeales","Austrobaileyales","Amborella trichopoda","Acorus (Acorales)"],"correct":2,"why":"Amborella trichopoda (Amborellales) è la linea più basale delle angiosperme; dopo di lei si staccano Nymphaeales e Austrobaileyales (grado ANITA). Acorus è invece alla base delle sole monocotiledoni.","real":false},{"id":25023,"topic":"Sistematica","type":"multi","q":"Seleziona i caratteri tipici delle monocotiledoni (Liliopsida):","opts":["embrione con un solo cotiledone","fasci cribrovascolari dispersi nel parenchima (atassostele)","polline tricolpato","radici avventizie in apparato fascicolato","regolare accrescimento secondario dovuto al cambio","polline monosolcato"],"correct":[0,1,3,5],"why":"Un cotiledone, trimeria, atassostele, polline monosolcato, foglie parallelinervie e radici avventizie sono i caratteri chiave, da valutare nel loro insieme. Il polline tricolpato definisce le eudicotiledoni; di norma nelle monocotiledoni manca l'accrescimento secondario (Dracaena è un'eccezione anomala).","real":false},{"id":25024,"topic":"Sistematica","type":"sort","q":"Tipi di androceo: trascina ogni specie nella categoria giusta.","cats":["Tetradinamo","Didinamo","Monoadelfo (filamenti saldati)","Antere saldate o conniventi a tubo"],"items":[{"t":"Sinapis alba","cat":0},{"t":"Brassica oleracea","cat":0},{"t":"Ocimum basilicum","cat":1},{"t":"Geranium robertianum","cat":2},{"t":"Gossypium hirsutum","cat":2},{"t":"Solanum lycopersicum","cat":3},{"t":"Helianthus annuus","cat":3}],"why":"Le Brassicaceae hanno androceo tetradinamo (4 stami lunghi e 2 corti), le Lamiaceae didinamo. Geraniaceae (10 stami fusi alla base) e Malvaceae (tubo staminale attorno allo stilo) hanno stami monoadelfi. Le Solanaceae hanno antere conniventi a tubo, le Asteraceae antere saldate a tubo (singenesio).","real":false},{"id":25025,"topic":"Sistematica","type":"sort","q":"Trascina ogni frutto nella categoria giusta.","cats":["Secco deiscente","Secco indeiscente","Carnoso"],"items":[{"t":"Siliqua di Brassica","cat":0},{"t":"Legume di Glycine max","cat":0},{"t":"Capsula poricida di Papaver","cat":0},{"t":"Cariosside di Zea mays","cat":1},{"t":"Achenio di Helianthus annuus","cat":1},{"t":"Esperidio di Citrus sinensis","cat":2},{"t":"Peponide di Cucumis melo","cat":2},{"t":"Drupa di Olea europaea","cat":2}],"why":"Siliqua, legume e capsula sono secchi e si aprono per liberare i semi. Cariosside (frutto saldato al seme) e achenio sono secchi e non si aprono. Esperidio e peponide sono bacche modificate, e la drupa dell'olivo ha mesocarpo oleoso: sono tutti frutti carnosi.","real":false},{"id":25026,"topic":"Sistematica","type":"match","q":"Associa a ogni specie la sua famiglia.","rows":[{"label":"Punica granatum","ans":"Lythraceae"},{"label":"Theobroma cacao","ans":"Malvaceae"},{"label":"Coffea arabica","ans":"Rubiaceae"},{"label":"Humulus lupulus","ans":"Cannabaceae"},{"label":"Ficus carica","ans":"Moraceae"}],"options":["Lythraceae","Malvaceae","Rubiaceae","Cannabaceae","Moraceae","Solanaceae","Rutaceae"],"why":"Il melograno (balaustio) è una Lythraceae; il cacao, caulifloro, è una Malvaceae; il caffè (ovario infero, stipole interpicciolari) è una Rubiaceae; il luppolo, dioico, è una Cannabaceae; il fico (siconio) è una Moraceae.","real":false},{"id":25027,"topic":"Sistematica","type":"sort","q":"Specie di interesse agrario: trascina ogni specie nella sua famiglia.","cats":["Poaceae","Fabaceae","Brassicaceae"],"items":[{"t":"Zea mays","cat":0},{"t":"Oryza sativa","cat":0},{"t":"Secale cereale","cat":0},{"t":"Medicago sativa","cat":1},{"t":"Arachis hypogea","cat":1},{"t":"Lathyrus sativus","cat":1},{"t":"Raphanus sativus","cat":2},{"t":"Brassica napus","cat":2}],"why":"Mais, riso e segale sono cereali delle Poaceae, con frutto a cariosside. Erba medica, arachide e cicerchia sono Fabaceae, con legume o lomento e noduli radicali con Rhizobium. Ravanello e colza sono Brassicaceae, con siliqua e glucosinolati.","real":false},{"id":25028,"topic":"Sistematica","type":"mc","q":"Il fiore tipico delle Fabaceae Faboideae ha:","opts":["corolla papilionacea zigomorfa, 10 stami monoadelfi o diadelfi (9+1) e gineceo monocarpellare supero","corolla papilionacea attinomorfa, 6 stami tetradinami e ovario bicarpellare supero","5 petali liberi regolari, stami numerosi e vistosi e gineceo tricarpellare infero","corolla papilionacea zigomorfa, 10 stami liberi e gineceo bicarpellare infero"],"correct":0,"why":"Le Faboideae hanno corolla papilionacea zigomorfa (vessillo, due ali, carena), 10 stami monoadelfi o diadelfi e un gineceo sempre monocarpellare supero, da cui deriva il legume. I fiori attinomorfi con stami vistosi sono delle Mimosoideae; l'androceo tetradinamo è delle Brassicaceae.","real":false},{"id":25029,"topic":"Sistematica","type":"cloze","q":"Completa trascinando le parole nei riquadri.","text":"Il fiore delle Brassicaceae è {0}, con 4 petali disposti a croce e androceo {1} a 6 stami. Il frutto è una capsula con un {2} centrale membranoso su cui restano i semi: la {3} è molto più lunga che larga, la siliquetta è circa isodiametrica.","answers":["tetramero","tetradinamo","replo","siliqua"],"bank":["pentamero","didinamo","opercolo","capsula poricida"],"why":"Le Crucifere hanno fiore tetramero dialipetalo a croce, androceo tetradinamo (4 stami lunghi e 2 corti) e ovario supero bicarpellare. Il frutto ha un replo persistente e si distingue in siliqua (Brassica, Sinapis), siliquetta (Lunaria, Capsella) e siliqua lomentacea (Raphanus). L'androceo didinamo è tipico delle Lamiaceae.","real":false},{"id":25030,"topic":"Sistematica","type":"mc","q":"Nelle Asteraceae il pappo è:","opts":["l'involucro di brattee che protegge il capolino","l'insieme delle antere saldate a tubo attorno allo stilo","il ricettacolo carnoso che si consuma nel carciofo","il calice modificato in peli o squame, che favorisce la dispersione anemocora dell'achenio"],"correct":3,"why":"Nelle Asteraceae il calice è ridotto a peli o squame (il pappo), che restano sul frutto achenio e ne permettono la dispersione con il vento. L'involucro di brattee circonda il capolino, le antere saldate formano il singenesio e il ricettacolo porta i fiori.","real":false},{"id":25031,"topic":"Sistematica","type":"cloze","q":"Completa trascinando le parole nei riquadri.","text":"Il capolino delle Asteraceae è un tipo di {0}. I fiori {1} sono attinomorfi con corolla di 5 petali saldati, mentre i fiori {2} sono zigomorfi con i petali fusi in una linguetta. L'ovario è {3} e il frutto è un {4}.","answers":["pseudanto","tubulosi","ligulati","infero","achenio"],"bank":["supero","cariosside","sorosio","spadice"],"why":"Il capolino è un finto fiore (pseudanto) formato da molti fiori su un ricettacolo con involucro di brattee. I fiori tubulosi formano il bottone centrale della margherita, quelli ligulati i petali bianchi. L'ovario è infero e il frutto è un achenio, con o senza pappo.","real":false},{"id":25032,"topic":"Sistematica","type":"mc","q":"Quale combinazione di caratteri è diagnostica delle Solanaceae?","opts":["fasci bicollaterali, viticci ascellari, fiori unisessuali e frutto a peponide","fasci bicollaterali, antere conniventi a tubo intorno allo stilo, ovario supero biloculare","fusto quadrangolare, corolla bilabiata, androceo didinamo e tetrachenio","antere saldate a tubo, ovario infero e achenio con pappo"],"correct":1,"why":"Le Solanaceae hanno fasci bicollaterali, antere conniventi a tubo, ossalato di calcio e ovario supero biloculare che dà bacca o capsula. Anche le Cucurbitaceae hanno fasci bicollaterali, ma con viticci, fiori unisessuali e peponide. Le altre combinazioni sono di Lamiaceae e Asteraceae.","real":false},{"id":25033,"topic":"Sistematica","type":"multi","q":"Seleziona le affermazioni corrette:","opts":["il tubero di Solanum tuberosum è un fusto modificato con gemme dette 'occhi'","Ipomea batatas produce radici tuberizzate ricche di zuccheri e amido","nella patata l'alcaloide solanina è presente nelle parti verdi","Ipomea batatas appartiene alle Solanaceae, come la patata comune","la carestia irlandese del 1845-1847 fu causata dal fungo Claviceps purpurea"],"correct":[0,1,2],"why":"Il tubero della patata è un fusto modificato che si forma all'apice degli stoloni; la solanina si trova nelle parti verdi. La patata dolce è invece una Convolvulaceae con radici tuberizzate. La carestia irlandese fu causata da Phytophthora infestans; Claviceps purpurea provoca l'ergotismo della segale.","real":false},{"id":25034,"topic":"Sistematica","type":"mc","q":"L'ocrea, guaina membranosa di origine stipolare che avvolge il fusto sopra i nodi, è caratteristica delle:","opts":["Caryophyllaceae","Polygonaceae","Poaceae","Apiaceae"],"correct":1,"why":"L'ocrea è il carattere distintivo delle Polygonaceae (es. Fagopyrum esculentum). Le Caryophyllaceae si riconoscono dai nodi ingrossati con foglie opposte, le Poaceae hanno guaina aperta con ligula e le Apiaceae foglie con base guainante, ma nessuna di queste ha un'ocrea.","real":false},{"id":25035,"topic":"Sistematica","type":"mc","q":"Nelle Oleaceae l'androceo è:","opts":["didinamo, con 4 stami di cui 2 più lunghi","monoadelfo, con 10 stami fusi alla base","ridotto a 2 stami epicorollini inseriti sul tubo della corolla","formato da 6 stami disposti in due verticilli da 3"],"correct":2,"why":"Le Oleaceae (olivo, frassini) hanno fiori tetrameri a corolla gamopetala con soli 2 stami inseriti sul tubo corollino e ovario supero bicarpellare. L'androceo didinamo è delle Lamiaceae, quello monoadelfo a 10 stami delle Geraniaceae, i 6 stami in due verticilli delle Liliaceae.","real":false},{"id":25036,"topic":"Sistematica","type":"cloze","q":"Completa trascinando le parole nei riquadri.","text":"Le Rosaceae si dividono in sottofamiglie in base al tipo di frutto. Prunoideae: {0}; Maloideae: {1} (falso frutto); Rosoideae: {2}; Spiroideae: {3}.","answers":["drupa","pomo","achenio","follicolo"],"bank":["balaustio","siliqua","cariosside","capsula"],"why":"Prunus (albicocco, pesco, susino) ha drupe; le Maloideae producono il pomo, falso frutto; nelle Rosoideae il cinorrodo di Rosa contiene numerosi acheni; le Spiroideae (Spiraea) hanno follicoli. Il balaustio è della Lythraceae Punica, la siliqua delle Brassicaceae, la cariosside delle Poaceae.","real":false},{"id":25037,"topic":"Sistematica","type":"mc","q":"Il fico (Ficus carica) è:","opts":["un sorosio, infruttescenza carnosa dolce e biancastra","un balaustio sormontato dal calice persistente","un falso frutto detto siconio, cavo e provvisto di ostiolo apicale","una bacca modificata detta esperidio"],"correct":2,"why":"Nelle Moraceae le infiorescenze diventano infruttescenze carnose: nel fico si forma il siconio, cavo e con ostiolo, legato all'impollinatore Blastophaga psenes. Il sorosio è del gelso (Morus alba), il balaustio del melograno, l'esperidio degli agrumi.","real":false},{"id":25038,"topic":"Sistematica","type":"multi","q":"Seleziona i caratteri tipici delle Poaceae:","opts":["culmi cavi negli internodi e pieni nei nodi","foglie con guaina aperta, ligula membranosa e lembo parallelinervio","fiori aclamidati racchiusi tra lemma e palea, riuniti in spighette","frutto a cariosside","fusto trigono privo di nodi","ocrea membranosa sopra i nodi"],"correct":[0,1,2,3],"why":"Le Poaceae hanno culmi con nodi pieni, foglie con guaina, ligula e lembo parallelinervio, fiori senza perianzio in spighette protette da glume, e la cariosside. Il fusto trigono senza nodi è delle Cyperaceae, l'ocrea delle Polygonaceae.","real":false},{"id":25039,"topic":"Sistematica","type":"mc","q":"Il grano duro (Triticum turgidum subsp. durum) è:","opts":["esaploide (6n=42, AABBDD), usato per la farina da panificazione","diploide (2n=14, AA), detto piccolo farro","tetraploide (4n=28, AADD), derivato dall'ibridazione con Aegilops tauschii","tetraploide (4n=28, AABB), con cariossidi vitree adatte per semola e pasta"],"correct":3,"why":"Il grano duro è tetraploide AABB, con il genoma B che viene da Aegilops speltoides, e ha cariossidi dure e vitree da semola. Il grano tenero è esaploide AABBDD (il genoma D viene da Ae. tauschii) e si usa per il pane; T. monococcum è il diploide AA.","real":false},{"id":25040,"topic":"Sistematica","type":"cloze","q":"Completa trascinando le parole nei riquadri.","text":"Il genoma D del grano tenero deriva da {0}. Tra le modificazioni della domesticazione ci sono la rachide {1}, che a maturità trattiene le cariossidi, e la cariosside {2}, che si libera alla trebbiatura.","answers":["Aegilops tauschii","tenace","nuda"],"bank":["Aegilops speltoides","fragile","vestita"],"why":"Gli esaploidi AABBDD sono nati inglobando il genoma di Aegilops tauschii, mentre Ae. speltoides ha fornito il genoma B. Nelle forme coltivate la rachide tenace non si frammenta, e la cariosside nuda (free-threshing) si separa dalle glume, al contrario delle forme selvatiche vestite.","real":false},{"id":25041,"topic":"Sistematica","type":"mc","q":"Le Iridaceae si distinguono dalle Liliaceae perché hanno:","opts":["3 stami e ovario infero tricarpellare","6 tepali in due verticilli, 6 stami e ovario supero","stami e stilo fusi in un ginostemio","un solo stame fertile e gli altri fusi in un labello petaloideo"],"correct":0,"why":"Le Iridaceae (Crocus, Iris) hanno fiori trimeri con 3 stami, ovario infero e stili petaloidi. Le Liliaceae hanno 6 tepali, 6 stami e ovario supero; il ginostemio è delle Orchidaceae e il labello di stami sterili delle Zingiberaceae.","real":false},{"id":25042,"topic":"Sistematica","type":"match","q":"Monocotiledoni: associa a ogni famiglia il suo carattere distintivo.","rows":[{"label":"Orchidaceae","ans":"ginostemio e polline agglutinato in pollinii"},{"label":"Araceae","ans":"spadice avvolto da una spata"},{"label":"Zingiberaceae","ans":"un solo stame fertile, gli altri fusi in un labello"},{"label":"Asparagaceae","ans":"foglie ridotte a squamette e cladodi fotosintetizzanti"},{"label":"Musaceae","ans":"pseudofusto formato da guaine fogliari embricate"}],"options":["ginostemio e polline agglutinato in pollinii","spadice avvolto da una spata","un solo stame fertile, gli altri fusi in un labello","foglie ridotte a squamette e cladodi fotosintetizzanti","pseudofusto formato da guaine fogliari embricate","fusto trigono privo di nodi"],"why":"Orchidaceae: stami e stilo fusi nel ginostemio, polline in pollinii. Araceae: spadice di fiori unisessuali con spata (Zantedeschia). Zingiberaceae: labello di stami sterili. Asparagaceae: cladodi (Asparagus, Ruscus). Musaceae: pseudoculmo di guaine fogliari. Il fusto trigono è delle Cyperaceae.","real":false},{"id":25043,"topic":"Sistematica","type":"multi","q":"Seleziona le famiglie caratterizzate dalla presenza di laticiferi (latice):","opts":["Euphorbiaceae","Moraceae","Papaveraceae","Apocynaceae","Lamiaceae","Rutaceae"],"correct":[0,1,2,3],"why":"Euphorbiaceae (Hevea, Euphorbia), Moraceae, Papaveraceae (latice bianco, aranciato o rosso) e Apocynaceae hanno latice. Le Lamiaceae hanno invece peli ghiandolari con oli essenziali, e le Rutaceae ghiandole lisigene con oli essenziali.","real":false},{"id":25044,"topic":"Sistematica","type":"cloze","q":"Completa trascinando le parole nei riquadri.","text":"Le Magnoliaceae hanno perianzio formato da 6 o più {0}, stami numerosi e ovari superi monocarpellari separati, cioè un gineceo {1}. Il frutto è un aggregato di {2}.","answers":["tepali","apocarpico","follicoli"],"bank":["sepali","sincarpico","acheni"],"why":"Nelle Magnoliales il perianzio non è differenziato in calice e corolla ma in tepali, e i carpelli sono liberi (gineceo apocarpico). Il frutto è un aggregato di follicoli, che si aprono lungo la nervatura mediana e liberano semi con tegumento rosso carnoso.","real":false}];
